impl V2LaneWorkAdapter {
    /// Open one adapter after verifying the frozen Nexus/AMX commitment.
    ///
    /// # Errors
    ///
    /// Returns [`V2LaneWorkError`] for malformed context, local-key drift, or
    /// committed-state/context drift. `recovered_applied_height` is accepted
    /// only when it identifies this exact context and canonical post-apply tip.
    #[cfg(test)]
    pub(crate) fn new(
        context: wire::HeightContext,
        local_peer: PeerId,
        key_pair: KeyPair,
        voting_enabled: bool,
        state: Arc<State>,
        kura: Arc<Kura>,
        limits: V2LaneWorkLimits,
        recovered_applied_height: Option<super::v2_recovery::PendingKuraApply>,
    ) -> Result<Self, V2LaneWorkError> {
        Self::new_with_output_guard(
            context,
            local_peer,
            key_pair,
            voting_enabled,
            state,
            kura,
            limits,
            None,
            recovered_applied_height,
            ConsensusOutputGuard::isolated(),
        )
    }

    /// Open one test adapter without retained cross-height sidecar ownership.
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new_with_output_guard(
        context: wire::HeightContext,
        local_peer: PeerId,
        key_pair: KeyPair,
        voting_enabled: bool,
        state: Arc<State>,
        kura: Arc<Kura>,
        limits: V2LaneWorkLimits,
        authenticated_genesis_nexus_amx_context: Option<AuthenticatedGenesisNexusAmxContext>,
        recovered_applied_height: Option<super::v2_recovery::PendingKuraApply>,
        output_guard: Arc<ConsensusOutputGuard>,
    ) -> Result<Self, V2LaneWorkError> {
        let (_, exact_output_handoff_owner) = durable_exact_output_handoff_owner_pair();
        Self::new_with_output_guard_and_transport(
            context,
            local_peer,
            key_pair,
            voting_enabled,
            state,
            kura,
            limits,
            authenticated_genesis_nexus_amx_context,
            recovered_applied_height,
            output_guard,
            exact_output_handoff_owner,
            None,
        )
    }

    /// Open one production adapter and retain process-local sidecar ownership
    /// from the immediately preceding height.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new_with_output_guard_and_transport(
        context: wire::HeightContext,
        local_peer: PeerId,
        key_pair: KeyPair,
        voting_enabled: bool,
        state: Arc<State>,
        kura: Arc<Kura>,
        limits: V2LaneWorkLimits,
        authenticated_genesis_nexus_amx_context: Option<AuthenticatedGenesisNexusAmxContext>,
        recovered_applied_height: Option<super::v2_recovery::PendingKuraApply>,
        output_guard: Arc<ConsensusOutputGuard>,
        exact_output_handoff_owner: DurableExactOutputTransportOwner,
        retained_merge_sidecars: Option<RetainedMergeSidecars>,
    ) -> Result<Self, V2LaneWorkError> {
        require_validator_storage_platform(
            voting_enabled,
            sumeragi_v2_validator_storage_supported(),
        )?;
        let construction_guard = Arc::clone(&output_guard);
        let construction = construction_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        context
            .validate()
            .map_err(|error| V2LaneWorkError::InvalidContext(error.to_string()))?;
        if local_peer.public_key() != key_pair.public_key() {
            return Err(V2LaneWorkError::LocalKeyMismatch);
        }
        let state_height = u64::try_from(state.committed_height())
            .map_err(|_| V2LaneWorkError::StateHeightMismatch)?;
        let is_pre_apply = state_height.checked_add(1) == Some(context.height);
        let is_post_apply = state_height == context.height;
        if !is_pre_apply && !is_post_apply {
            return Err(V2LaneWorkError::StateHeightMismatch);
        }
        let is_fresh_genesis_pre_apply = is_pre_apply
            && state_height == 0
            && context.height == 1
            && context.parent_commit_qc.is_none()
            && context.snapshot_bootstrap.is_none();
        let pre_apply_context_matches = if is_fresh_genesis_pre_apply {
            authenticated_genesis_nexus_amx_context
                .is_some_and(|authenticated| authenticated.hash() == context.nexus_amx_context_hash)
        } else {
            authenticated_genesis_nexus_amx_context.is_none()
                && super::v2_recovery::committed_nexus_amx_context_hash(state.as_ref())
                    == context.nexus_amx_context_hash
        };
        let recovered_applied_tip_matches = recovered_applied_height.is_some_and(|pending| {
            let Ok(height) = usize::try_from(context.height) else {
                return false;
            };
            let Some(nonzero_height) = NonZeroUsize::new(height) else {
                return false;
            };
            pending.context_id() == context.id()
                && pending.height() == context.height
                && state.committed_height() == height
                && state.latest_block_hash_fast() == Some(pending.block_hash())
                && kura
                    .exact_durable_blocks_count()
                    .is_ok_and(|durable_height| durable_height == height)
                && kura.get_durable_block_hash(nonzero_height) == Some(pending.block_hash())
        });
        if (is_post_apply || recovered_applied_height.is_some()) && !recovered_applied_tip_matches {
            return Err(V2LaneWorkError::RecoveredAppliedTipMismatch);
        }
        if authenticated_genesis_nexus_amx_context.is_some() && !is_fresh_genesis_pre_apply {
            return Err(V2LaneWorkError::NexusContextMismatch);
        }
        if is_pre_apply && !pre_apply_context_matches {
            return Err(V2LaneWorkError::NexusContextMismatch);
        }
        let committed_merge_epoch = state
            .merge_ledger()
            .latest()
            .map_or(0, |entry| entry.epoch_id);
        let merge_signing_guard = MergeSigningGuard::open_with_committed_frontier(
            &kura.store_root(),
            committed_merge_epoch,
            state_height,
            limits.merge_signing_guard_limits,
        )
        .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?;
        let native_signing_guard = if voting_enabled
            && local_peer.public_key().try_algorithm().ok() == Some(Algorithm::BlsNormal)
        {
            let _max_records = native_amx_signing_guard_capacity(limits)?;
            let chain_id = context.chain_id.clone().into_inner();
            Some(
                NativeAmxSigningGuard::open(
                    &kura.store_root(),
                    context.height,
                    context.id(),
                    context.epoch,
                    Hash::new(chain_id.as_bytes()),
                    local_peer.clone(),
                    limits.native_amx_signing_guard_limits,
                )
                .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?,
            )
        } else {
            None
        };
        let lane_drain_signing_guard = if voting_enabled
            && local_peer.public_key().try_algorithm().ok() == Some(Algorithm::BlsNormal)
        {
            let active_incarnations = state
                .lane_incarnations_snapshot()
                .into_iter()
                .collect::<BTreeSet<_>>();
            Some(
                LaneDrainSigningGuard::open(&kura.store_root(), &active_incarnations)
                    .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?,
            )
        } else {
            None
        };
        let sidecar_server_roster = context
            .roster
            .iter()
            .map(|entry| entry.validator.clone())
            .collect::<Vec<_>>();
        let sidecar_server_stream_capacity = sidecar_server_roster.len();
        let sidecar_server_roster_digest =
            canonical_merge_sidecar_roster_digest(&sidecar_server_roster);
        let merge_sidecars = match retained_merge_sidecars {
            Some(retained) => retained.rehydrate_for_successor(
                &context,
                limits.reply_source_capacity.get(),
                limits.merge_sidecar_limits,
                sidecar_server_stream_capacity,
                sidecar_server_roster_digest,
                Instant::now(),
            ),
            None => MergeSidecarTransport::open_durable_with_server_stream_capacity(
                &kura.store_root(),
                limits.reply_source_capacity.get(),
                limits.merge_sidecar_limits,
                sidecar_server_stream_capacity,
                sidecar_server_roster_digest,
            )
            .map_err(|error| V2LaneWorkError::InvalidContext(error.to_string())),
        }?;
        let mut adapter = Self {
            context,
            local_peer,
            key_pair,
            voting_enabled,
            state,
            kura,
            output_guard,
            limits,
            lane_sessions: LaneBlockSessionCache::new(limits.session_capacity.get()),
            pending_autonomous_reservation_batches: BTreeMap::new(),
            autonomous_production_attempted_routes: BTreeSet::new(),
            next_autonomous_producer_tick: Instant::now(),
            pending_autonomous_anchor_payloads: BTreeMap::new(),
            autonomous_payloads: BTreeMap::new(),
            autonomous_payload_order: VecDeque::new(),
            autonomous_payload_views: BTreeMap::new(),
            autonomous_new_view_started_at: BTreeMap::new(),
            autonomous_new_view_votes: LaneBlockNewViewVoteCache::new(
                limits.session_capacity.get(),
            ),
            autonomous_new_view_certificates: LaneBlockNewViewCertificateCache::new(
                limits.session_capacity.get(),
            ),
            native_sessions: NativeAmxSessionCache::with_limits(
                limits.session_capacity,
                limits.body_buckets_per_session,
            ),
            native_claims: BTreeMap::new(),
            native_claim_order: VecDeque::new(),
            local_native_claims: BTreeMap::new(),
            native_signing_guard,
            native_requests: BTreeMap::new(),
            lane_drain_signing_guard,
            lane_drain_votes: LaneDrainVoteState::new(),
            lane_drain_queue: None,
            lane_drain_fanout_cursor: 0,
            planned_lane_proposals: BTreeMap::new(),
            pending_local_lane_proposals: BTreeMap::new(),
            globally_locked_body: None,
            retained_merge_carrier_state: None,
            #[cfg(test)]
            merge_retention_scans: 0,
            locally_bound_lane_proposals: BTreeMap::new(),
            pending_committed_lanes: VecDeque::new(),
            committed_lane_outputs: VecDeque::new(),
            historical_recovery_sessions: VecDeque::new(),
            committed_lane_status_revision: 0,
            historical_recovery_diagnostics: HistoricalRecoveryDiagnostics::new(
                limits.session_capacity.get(),
                limits.historical_recovery_stuck_attempts,
                limits.historical_recovery_retry_tier_attempts,
                limits.historical_recovery_max_retry_tier,
            ),
            historical_recovery_requests: BTreeMap::new(),
            historical_recovery_request_owners: BTreeMap::new(),
            native_participant_recovery_requests: BTreeMap::new(),
            native_participant_recovery_request_owners: BTreeMap::new(),
            native_participant_recovery_retry_cursor: 0,
            committed_lane_output_cursor: 0,
            admitted_relays: BTreeSet::new(),
            merge_entries: BTreeMap::new(),
            merge_claims: BTreeMap::new(),
            merge_signing_guard,
            merge_sidecars,
            exact_output_handoff_owner,
            authenticated_merge_qcs: BTreeSet::new(),
            authenticated_merge_qc_order: VecDeque::new(),
            #[cfg(test)]
            merge_qc_preflight_checks: 0,
            completed_merge_sidecars: BTreeSet::new(),
            rejected_merge_sidecars: BTreeMap::new(),
            closed_sidecar_prefixes: BTreeMap::new(),
            sidecar_effects: VecDeque::new(),
            sidecar_effect_keys: BTreeSet::new(),
            effects: VecDeque::new(),
            effect_keys: BTreeSet::new(),
            drain_sidecar_next: true,
            sidecar_progress_drain_credit: SIDECAR_PROGRESS_DRAIN_WEIGHT,
            lane_fanout_cursor: 0,
            lane_artifact_cursor: 0,
            native_retransmit_cursor: 0,
            regular_retransmit_class_cursor: 0,
            #[cfg(test)]
            persistence_pause: None,
            #[cfg(test)]
            persistence_failure: None,
        };
        let finalized_cleanup_height = if is_post_apply {
            adapter.context.height
        } else {
            adapter.context.height.saturating_sub(1)
        };
        adapter
            .kura
            .prune_finalized_pending_certified_merge_entries(finalized_cleanup_height)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        adapter.repair_globally_applied_lane_receipts()?;
        adapter.hydrate_canonical_lane_artifacts()?;
        adapter.drive_lane_sessions();
        construction.complete();
        Ok(adapter)
    }

    /// Seal the height-local adapter's exact sidecar owner for one successor.
    ///
    /// This consumes both the adapter and the worker's one-shot receipt. A
    /// receipt from another service instance is rejected by process-local owner
    /// identity even if it carries byte-identical finality. No committed lane
    /// output or undispatched effect may remain outside the sealed worker
    /// corridor.
    pub(crate) fn into_retained_merge_sidecars(
        self,
        exact_output_handoff: DurableExactOutputHandoffReceipt,
        artifact: &wire::finality::V2FinalityArtifact,
        successor: &wire::HeightContext,
    ) -> Result<RetainedMergeSidecars, V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let handoff = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        if self.has_pending_committed_output_handoff() {
            return Err(V2LaneWorkError::InvalidContext(
                "retained merge-sidecar handoff still owns committed lane output".to_owned(),
            ));
        }
        if self.effect_count() != 0 {
            return Err(V2LaneWorkError::InvalidContext(
                "retained merge-sidecar handoff still owns undispatched lane output".to_owned(),
            ));
        }
        successor
            .validate()
            .map_err(|error| V2LaneWorkError::InvalidContext(error.to_string()))?;
        if !exact_output_handoff.is_bound_to_transport_owner(&self.exact_output_handoff_owner) {
            return Err(V2LaneWorkError::InvalidContext(
                "durable exact-output handoff belongs to another service/transport owner"
                    .to_owned(),
            ));
        }
        if !exact_output_handoff.matches_predecessor_context(&self.context)
            || !exact_output_handoff.matches_finality_artifact(artifact)
        {
            return Err(V2LaneWorkError::InvalidContext(
                "durable exact-output handoff belongs to another predecessor artifact".to_owned(),
            ));
        }
        if !exact_output_handoff.authorizes_immediate_successor(successor) {
            return Err(V2LaneWorkError::InvalidContext(
                "durable exact-output handoff does not authorize the immediate successor"
                    .to_owned(),
            ));
        }
        let retained = RetainedMergeSidecars {
            transport: self.merge_sidecars,
            exact_output_handoff,
            successor_context_id: successor.id(),
            successor_context_hash: HashOf::new(successor),
        };
        handoff.complete();
        Ok(retained)
    }

    /// Install the live queue used by the production drain-safety predicate.
    ///
    /// Construction remains queue-independent for deterministic recovery
    /// tests, but a production adapter cannot sign or carry a drain
    /// certificate until this exact blocker source is installed.
    pub(crate) fn install_lane_drain_queue(
        &mut self,
        queue: Arc<Queue>,
    ) -> Result<(), V2LaneWorkError> {
        if self
            .lane_drain_queue
            .as_ref()
            .is_some_and(|installed| !Arc::ptr_eq(installed, &queue))
        {
            return Err(V2LaneWorkError::InvalidContext(
                "lane-drain queue source changed within one height".to_owned(),
            ));
        }
        let nexus = self.state.nexus_snapshot();
        let autonomous_queue_ownership_active =
            nexus.enabled && proposal_lookahead_enabled(&nexus, self.context.height);
        for payload in self
            .pending_autonomous_anchor_payloads
            .values()
            .filter(|payload| {
                autonomous_queue_ownership_active && payload.producer == self.local_peer
            })
        {
            for reservation in &payload.reservation_keys {
                if queue
                    .retain_lane_reservation(reservation)
                    .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?
                    != LaneQueueReservationOutcome::Retained
                {
                    return Err(V2LaneWorkError::Persistence(format!(
                        "durable hint-free autonomous payload is missing exact live queue reservation {}",
                        reservation.signed_transaction_hash
                    )));
                }
            }
        }
        self.lane_drain_queue = Some(queue);
        Ok(())
    }

    fn autonomous_route_quota(
        total: usize,
        route_count: usize,
        route_index: usize,
        rotation: usize,
    ) -> usize {
        if total == 0 || route_count == 0 || route_index >= route_count {
            return 0;
        }
        let base = total / route_count;
        let remainder = total % route_count;
        let rotated_index = (route_index + route_count - (rotation % route_count)) % route_count;
        base + usize::from(rotated_index < remainder)
    }

    fn autonomous_proposal_matches_reservation_slot(
        proposal: &LaneBlockProposalV1,
        slot: &AutonomousLaneReservationSlotPlan,
    ) -> bool {
        let descriptor = &proposal.descriptor;
        descriptor.lane_id == slot.lane_id
            && descriptor.dataspace_id == slot.dataspace_id
            && descriptor.lane_incarnation == slot.lane_incarnation
            && descriptor.proposal_height == slot.proposal_height
            && descriptor.previous_lane_block_height == slot.previous_lane_block_height
            && descriptor.previous_lane_block_descriptor_hash
                == slot.previous_lane_block_descriptor_hash
            && descriptor.lane_block_height == slot.lane_block_height
            && descriptor.lane_block_view == slot.lane_block_view
            && descriptor.validator_set == slot.validator_set
            && descriptor.validator_set_hash == slot.validator_set_hash
            && descriptor.validator_count == slot.quorum.validator_count
            && descriptor.min_quorum == slot.quorum.min_quorum
            && descriptor.qc_mode_tag == slot.qc_mode_tag
            && lane_proposal_author(proposal) == Some(&slot.author)
    }

    fn drive_pending_autonomous_reservation_batch(
        &mut self,
        batch: PendingAutonomousReservationBatch,
        active_view: wire::View,
    ) -> Result<AutonomousProducerBatchOutcome, V2LaneWorkError> {
        if batch.reservations.is_empty()
            || batch.reservations.len() > self.limits.body_buckets_per_session.get()
        {
            self.release_autonomous_reservation_batch(&batch)?;
            return Ok(AutonomousProducerBatchOutcome::Released);
        }
        let accepted = batch
            .reservations
            .iter()
            .map(LaneReservedTransaction::clone_accepted)
            .collect::<Vec<_>>();
        let routing_plans = batch
            .reservations
            .iter()
            .map(|reservation| reservation.routing_plan().clone())
            .collect::<Vec<_>>();
        let candidates = accepted
            .iter()
            .zip(&routing_plans)
            .map(|(transaction, routing_plan)| CandidateDescriptor::new(transaction, routing_plan))
            .collect::<Vec<_>>();
        let coordinator_routes = routing_plans
            .iter()
            .map(RoutingPlan::coordinator_route)
            .collect::<Vec<_>>();
        let entrypoint_hashes = accepted
            .iter()
            .map(|transaction| Hash::from(transaction.hash_as_entrypoint()))
            .collect::<Vec<_>>();
        let lane_plan = match prepare_v2_lane_payload_plan(
            self.state.as_ref(),
            self.kura.as_ref(),
            &self.context,
            active_view,
            &self.local_peer,
            &coordinator_routes,
            &entrypoint_hashes,
        ) {
            Ok(plan) if plan.unavailable_indices.is_empty() && plan.proposals.len() == 1 => plan,
            _ => {
                self.release_autonomous_reservation_batch(&batch)?;
                return Ok(AutonomousProducerBatchOutcome::Released);
            }
        };
        let proposal = lane_plan
            .proposals
            .first()
            .expect("single-proposal autonomous lane plan checked above")
            .clone();
        if !Self::autonomous_proposal_matches_reservation_slot(&proposal, &batch.slot)
            || batch.reservations.iter().any(|reservation| {
                let key = reservation.key();
                key.reservation_owner_hash != batch.slot.reservation_owner_hash
                    || key.proposal_identity_hash != batch.slot.proposal_identity_hash
                    || key.lane_id != batch.slot.lane_id
                    || key.dataspace_id != batch.slot.dataspace_id
                    || key.lane_incarnation != batch.slot.lane_incarnation
                    || key.proposal_height != batch.slot.proposal_height
                    || key.lane_block_height != batch.slot.lane_block_height
                    || key.lane_block_view != batch.slot.lane_block_view
            })
        {
            self.release_autonomous_reservation_batch(&batch)?;
            return Ok(AutonomousProducerBatchOutcome::Released);
        }

        let participant_controls =
            match self.prepare_native_participant_controls(&candidates, &lane_plan.proposals) {
                Ok(controls) => controls,
                Err(_) => {
                    self.release_autonomous_reservation_batch(&batch)?;
                    return Ok(AutonomousProducerBatchOutcome::Released);
                }
            };
        let mut native_amx_receipts = Vec::with_capacity(candidates.len());
        let mut waiting_for_receipt = false;
        for candidate in candidates.iter().copied() {
            match candidate.routing_plan() {
                RoutingPlan::Single(_) => native_amx_receipts.push(None),
                RoutingPlan::NativeAmx(_) => {
                    let receipt = self.prepare_native_receipt(
                        active_view,
                        candidate,
                        &lane_plan.proposals,
                        &participant_controls,
                    );
                    waiting_for_receipt |= receipt.is_none();
                    native_amx_receipts.push(receipt);
                }
            }
        }
        if waiting_for_receipt {
            return Ok(AutonomousProducerBatchOutcome::Pending(batch));
        }

        let entrypoints = accepted
            .into_iter()
            .map(|transaction| transaction.entrypoint().clone())
            .collect::<Vec<_>>();
        let reservation_keys = batch
            .reservations
            .iter()
            .map(|reservation| *reservation.key())
            .collect::<Vec<_>>();
        let payload = match LaneExecutablePayloadV1::new_signed_with_reservations(
            self.native_chain_id_hash(),
            self.context.epoch,
            proposal,
            entrypoints,
            reservation_keys,
            routing_plans,
            native_amx_receipts,
            self.local_peer.clone(),
            self.key_pair.private_key(),
        ) {
            Ok(payload) => payload,
            Err(_) => {
                self.release_autonomous_reservation_batch(&batch)?;
                return Ok(AutonomousProducerBatchOutcome::Released);
            }
        };
        let envelope = autonomous_lane_payload_envelope(
            &payload,
            self.native_chain_id_hash(),
            self.context.epoch,
        )
        .map_err(|error| V2LaneWorkError::InvalidContext(error.to_string()))?;
        let envelope_bytes = norito::to_bytes(&envelope)
            .map_err(|error| V2LaneWorkError::InvalidContext(error.to_string()))?;
        if envelope_bytes.len() > batch.envelope_byte_limit {
            self.release_autonomous_reservation_batch(&batch)?;
            return Ok(AutonomousProducerBatchOutcome::Released);
        }

        // The locally selected FIFO batch crosses its independent Kura
        // durability boundary before it becomes visible to either the
        // candidate provider or the network.
        self.kura
            .persist_lane_executable_payload(
                &payload,
                self.native_chain_id_hash(),
                self.context.epoch,
            )
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        let local_peer = self.local_peer.clone();
        if self.insert_autonomous_lane_payload(payload.clone(), Some(&local_peer), active_view)
            == V2LaneIngressOutcome::Rejected
        {
            return Err(V2LaneWorkError::Persistence(
                "durable local autonomous payload failed exact adapter admission".to_owned(),
            ));
        }
        let global_committee = self.frozen_validator_set();
        self.fanout_lane_message(
            BlockMessage::LaneExecutablePayload(payload.clone()),
            &global_committee,
        );
        Ok(AutonomousProducerBatchOutcome::Published(payload))
    }

    /// Run one bounded autonomous lane-producer tick for the current global
    /// height.
    ///
    /// Every validator invokes this method, but only the deterministic
    /// height-rotated author of each independent lane may reserve FIFO work.
    /// Queue ownership is durable before the selected entries leave ordinary
    /// FIFO, and the completed hint-free payload is durable before fanout.
    pub(crate) fn schedule_autonomous_lane_production(
        &mut self,
        active_view: wire::View,
        limits: CandidateLimits,
    ) -> Result<(), V2LaneWorkError> {
        if self.globally_locked_body.is_some()
            || self.decision_pending()
            || !self.voting_enabled
            || self.output_guard.restart_required()
        {
            return Ok(());
        }
        let committed_height = u64::try_from(self.state.committed_height())
            .map_err(|_| V2LaneWorkError::StateHeightMismatch)?;
        if committed_height.checked_add(1) != Some(self.context.height) {
            return Ok(());
        }
        let nexus = self.state.nexus_snapshot();
        if !nexus.enabled || !proposal_lookahead_enabled(&nexus, self.context.height) {
            return Ok(());
        }
        let now = Instant::now();
        if now < self.next_autonomous_producer_tick {
            return Ok(());
        }
        self.next_autonomous_producer_tick = now
            .checked_add(self.limits.autonomous_producer_recheck)
            .unwrap_or(now);
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;

        let pending_routes = self
            .pending_autonomous_reservation_batches
            .keys()
            .copied()
            .collect::<Vec<_>>();
        for route in pending_routes {
            let Some(batch) = self.pending_autonomous_reservation_batches.remove(&route) else {
                continue;
            };
            match self.drive_pending_autonomous_reservation_batch(batch, active_view)? {
                AutonomousProducerBatchOutcome::Pending(batch) => {
                    self.pending_autonomous_reservation_batches
                        .insert(route, batch);
                }
                AutonomousProducerBatchOutcome::Published(payload) => {
                    debug_assert_eq!(
                        (
                            payload.origin_proposal.descriptor.lane_id,
                            payload.origin_proposal.descriptor.dataspace_id,
                        ),
                        route
                    );
                    self.autonomous_production_attempted_routes.insert(route);
                }
                AutonomousProducerBatchOutcome::Released => {
                    self.autonomous_production_attempted_routes.insert(route);
                }
            }
        }

        let mut routes = self
            .state
            .consensus_lane_routes_at_height(self.context.height)
            .into_keys()
            .collect::<Vec<_>>();
        if routes.is_empty() {
            operation.complete();
            return Ok(());
        }
        let route_rotation = usize::try_from(self.context.height.saturating_sub(1))
            .unwrap_or(usize::MAX)
            % routes.len();
        if routes.len() > self.limits.session_capacity.get() {
            routes.rotate_left(route_rotation);
            routes.truncate(self.limits.session_capacity.get());
            routes.sort();
        }
        let route_count = routes.len();
        let max_payload_bytes = limits.max_payload_bytes().get();
        let usable_envelope_bytes = max_payload_bytes
            .checked_sub(self.limits.autonomous_carrier_headroom_bytes.get())
            .ok_or_else(|| {
                V2LaneWorkError::InvalidContext(
                    "autonomous carrier headroom exhausts the configured payload budget".to_owned(),
                )
            })?;
        let block_gas_limit = {
            let world = self.state.world_view();
            crate::state::gas_limit_from_parameters(world.parameters())
        };
        let drain_route = self
            .state
            .pending_autoscale_lane_drain_body()
            .map(|(body, _)| {
                (
                    body.intent.lane_id,
                    body.intent.dataspace_id,
                    body.intent.lane_incarnation,
                )
            });
        let queue = Arc::clone(self.lane_drain_queue.as_ref().ok_or_else(|| {
            V2LaneWorkError::InvalidContext(
                "autonomous lane production requires the installed live queue".to_owned(),
            )
        })?);

        for (route_index, (lane_id, dataspace_id)) in routes.into_iter().enumerate() {
            if self
                .autonomous_production_attempted_routes
                .contains(&(lane_id, dataspace_id))
                || self
                    .pending_autonomous_reservation_batches
                    .contains_key(&(lane_id, dataspace_id))
                || self
                    .pending_autonomous_anchor_payloads
                    .keys()
                    .any(|key| key.lane_id == lane_id && key.dataspace_id == dataspace_id)
                || self
                    .autonomous_payloads
                    .keys()
                    .any(|key| key.lane_id == lane_id && key.dataspace_id == dataspace_id)
            {
                continue;
            }
            let Some(incarnation) = self
                .state
                .lane_incarnation_at_height(lane_id, self.context.height)
            else {
                continue;
            };
            if drain_route == Some((lane_id, dataspace_id, incarnation)) {
                continue;
            }
            let slot = match plan_autonomous_lane_reservation_slot(
                self.state.as_ref(),
                self.kura.as_ref(),
                &self.context,
                lane_id,
                dataspace_id,
            ) {
                Ok(slot) if slot.author == self.local_peer => slot,
                Ok(_) => continue,
                Err(_) => {
                    self.autonomous_production_attempted_routes
                        .insert((lane_id, dataspace_id));
                    continue;
                }
            };
            let transaction_limit = Self::autonomous_route_quota(
                limits.max_transactions().get(),
                route_count,
                route_index,
                route_rotation,
            );
            let envelope_byte_limit = Self::autonomous_route_quota(
                usable_envelope_bytes,
                route_count,
                route_index,
                route_rotation,
            );
            let queue_scan_limit = Self::autonomous_route_quota(
                limits.max_queue_scan().get(),
                route_count,
                route_index,
                route_rotation,
            );
            let gas_limit = Self::autonomous_route_quota(
                usize::try_from(block_gas_limit).unwrap_or(usize::MAX),
                route_count,
                route_index,
                route_rotation,
            );
            if transaction_limit == 0
                || envelope_byte_limit == 0
                || queue_scan_limit == 0
                || gas_limit == 0
            {
                continue;
            }
            let Some(transaction_limit) = NonZeroUsize::new(transaction_limit) else {
                continue;
            };
            let selection_limits = LaneQueueReservationSelectionLimits {
                max_transactions: transaction_limit,
                max_scan: NonZeroUsize::new(queue_scan_limit)
                    .expect("positive autonomous queue-scan quota checked above"),
                max_encoded_bytes: NonZeroU64::new(
                    u64::try_from(envelope_byte_limit).unwrap_or(u64::MAX),
                )
                .expect("positive autonomous envelope-byte quota checked above"),
                max_gas: NonZeroU64::new(u64::try_from(gas_limit).unwrap_or(u64::MAX))
                    .expect("positive autonomous gas quota checked above"),
            };
            let reservations = queue
                .reserve_transactions_for_lane_bounded(
                    self.state.as_ref(),
                    slot.reservation_scope(),
                    selection_limits,
                    &BTreeSet::new(),
                    LaneQueueReservationRoutingMode::AnyCoordinatorPlan,
                )
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            if reservations.is_empty() {
                continue;
            }
            let batch = PendingAutonomousReservationBatch {
                slot,
                reservations,
                envelope_byte_limit,
            };
            match self.drive_pending_autonomous_reservation_batch(batch, active_view)? {
                AutonomousProducerBatchOutcome::Pending(batch) => {
                    self.pending_autonomous_reservation_batches
                        .insert((lane_id, dataspace_id), batch);
                }
                AutonomousProducerBatchOutcome::Published(_) => {
                    self.autonomous_production_attempted_routes
                        .insert((lane_id, dataspace_id));
                }
                AutonomousProducerBatchOutcome::Released => {
                    self.autonomous_production_attempted_routes
                        .insert((lane_id, dataspace_id));
                }
            }
        }
        operation.complete();
        Ok(())
    }

    /// Derive the stripped carrier header shared by merge pre-execution and
    /// global candidate assembly for one exact reducer view.
    ///
    /// Ledger time comes only from the committed parent plus the signed
    /// Sumeragi cadence. The runner consumes this same header when it creates
    /// the block builder, so an autonomous execution batch can never be
    /// certified against one timestamp and carried under another.
    pub(crate) fn merge_carrier_context_header(
        &self,
        active_view: wire::View,
    ) -> Result<BlockHeader, V2LaneWorkError> {
        let committed_height = u64::try_from(self.state.committed_height())
            .map_err(|_| V2LaneWorkError::StateHeightMismatch)?;
        if committed_height.checked_add(1) != Some(self.context.height) {
            return Err(V2LaneWorkError::StateHeightMismatch);
        }
        let cadence = self.state.sumeragi_block_cadence();
        let cadence_ms = u64::try_from(cadence.as_millis()).map_err(|_| {
            V2LaneWorkError::InvalidContext(
                "Sumeragi block cadence exceeds the carrier timestamp namespace".to_owned(),
            )
        })?;
        if cadence_ms == 0 || Duration::from_millis(cadence_ms) != cadence {
            return Err(V2LaneWorkError::InvalidContext(
                "Sumeragi block cadence is not an exact positive millisecond duration".to_owned(),
            ));
        }

        let (logical_time, parent_height, parent_hash, parent_body) = match (
            &self.context.parent_commit_qc,
            &self.context.snapshot_bootstrap,
        ) {
            (Some(parent_qc), None) => {
                let parent_height = usize::try_from(committed_height)
                    .ok()
                    .and_then(NonZeroUsize::new)
                    .ok_or(V2LaneWorkError::StateHeightMismatch)?;
                if self
                    .kura
                    .exact_durable_blocks_count()
                    .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?
                    != parent_height.get()
                {
                    return Err(V2LaneWorkError::StateHeightMismatch);
                }
                let parent = self
                    .kura
                    .get_block(parent_height)
                    .ok_or(V2LaneWorkError::StateHeightMismatch)?;
                if parent.hash() != parent_qc.subject.block_hash
                    || self.state.latest_block_hash_fast() != Some(parent.hash())
                {
                    return Err(V2LaneWorkError::StateHeightMismatch);
                }
                let logical_time = parent
                    .header()
                    .creation_time()
                    .checked_add(cadence)
                    .ok_or_else(|| {
                        V2LaneWorkError::InvalidContext(
                            "merge carrier timestamp overflow".to_owned(),
                        )
                    })?;
                (logical_time, committed_height, parent.hash(), Some(parent))
            }
            (None, Some(anchor)) => {
                if anchor.snapshot_height != committed_height
                    || self.state.latest_block_hash_fast() != Some(anchor.snapshot_block_hash)
                {
                    return Err(V2LaneWorkError::StateHeightMismatch);
                }
                let logical_time_ms = anchor
                    .snapshot_block_creation_time_ms
                    .checked_add(cadence_ms)
                    .ok_or_else(|| {
                        V2LaneWorkError::InvalidContext(
                            "snapshot-successor carrier timestamp overflow".to_owned(),
                        )
                    })?;
                (
                    Duration::from_millis(logical_time_ms),
                    anchor.snapshot_height,
                    anchor.snapshot_block_hash,
                    None,
                )
            }
            (Some(_), Some(_)) | (None, None) => {
                return Err(V2LaneWorkError::InvalidContext(
                    "non-genesis carrier requires exactly one authenticated parent".to_owned(),
                ));
            }
        };
        let (_, time_source) = TimeSource::new_mock(logical_time);
        let pending = BlockBuilder::new_with_time_source(Vec::new(), time_source);
        let header = match parent_body.as_deref() {
            Some(parent) => pending
                .chain(active_view, Some(parent))
                .carrier_context_header(),
            None => pending
                .chain_with_parent_hash(active_view, parent_height, parent_hash)
                .carrier_context_header(),
        };
        if header.height().get() != self.context.height
            || header.prev_block_hash() != Some(parent_hash)
            || header.view_change_index() != active_view
            || header.creation_time() != logical_time
            || header.merkle_root().is_some()
            || header.result_merkle_root().is_some()
        {
            return Err(V2LaneWorkError::InvalidContext(
                "derived merge carrier header differs from the frozen round".to_owned(),
            ));
        }
        Ok(header)
    }

    fn repair_globally_applied_lane_receipts(&mut self) -> Result<usize, V2LaneWorkError> {
        let pending = self
            .state
            .unapplied_lane_block_artifact_heights_snapshot_cached();
        let mut repaired = 0_usize;
        for ((lane_id, dataspace_id), lane_block_height) in
            pending.into_iter().take(self.limits.session_capacity.get())
        {
            let Some(artifact) = self
                .kura
                .read_lane_block_artifact(lane_id, lane_block_height)
            else {
                continue;
            };
            if artifact.ownership.dataspace_id != dataspace_id {
                continue;
            }
            let Some(proposal) =
                proposal_from_ownership(&artifact.ownership, artifact.proposal_block_hash)
            else {
                continue;
            };
            let Some(certified) = self
                .kura
                .read_certified_lane_block_artifact(lane_id, lane_block_height)
            else {
                continue;
            };
            if certified.proposal != proposal {
                continue;
            }
            if !self.proposal_anchor_is_committed_in_state(&proposal) {
                if proposal.descriptor.proposal_height
                    > u64::try_from(self.state.committed_height()).unwrap_or(u64::MAX)
                {
                    continue;
                }
                return Err(V2LaneWorkError::Persistence(
                    "certified lane block anchor conflicts with committed State".to_owned(),
                ));
            }
            if !self
                .state
                .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(&proposal)
            {
                return Err(V2LaneWorkError::Persistence(
                    "certified lane block has no applied predecessor during recovery".to_owned(),
                ));
            }
            let persisted = self
                .kura
                .persist_lane_block_application_receipt_if_ready(&proposal)
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            if !persisted {
                return Err(V2LaneWorkError::Persistence(
                    "certified globally applied lane block has no canonical results".to_owned(),
                ));
            }
            repaired = repaired.saturating_add(1);
        }

        let pending_native = self
            .state
            .native_amx_participant_frontiers_pending_durable_evidence_snapshot_cached()
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        if pending_native.len() > self.limits.session_capacity.get() {
            return Err(V2LaneWorkError::Persistence(
                "Native AMX participant receipt repair exceeds the bounded session capacity"
                    .to_owned(),
            ));
        }
        let committed_height = u64::try_from(self.state.committed_height())
            .map_err(|_| V2LaneWorkError::StateHeightMismatch)?;
        let mut repaired_carriers = BTreeSet::new();
        let mut remote_recovery_markers = BTreeSet::new();
        for marker in &pending_native {
            if marker.application_block_height > committed_height {
                return Err(V2LaneWorkError::Persistence(format!(
                    "Native AMX participant frontier at lane {} references uncommitted carrier height {}",
                    marker.lane_id.as_u32(),
                    marker.application_block_height,
                )));
            }
            let Some(height) = usize::try_from(marker.application_block_height)
                .ok()
                .and_then(NonZeroUsize::new)
            else {
                return Err(V2LaneWorkError::Persistence(
                    "Native AMX participant frontier has an invalid carrier height".to_owned(),
                ));
            };
            let Some(block) = self.kura.get_block(height) else {
                let recovery_marker = NativeAmxParticipantRecoveryMarkerV1::from(*marker);
                remote_recovery_markers.insert(recovery_marker);
                let _queued = self.schedule_native_participant_recovery_request(recovery_marker)?;
                continue;
            };
            if block.hash() != marker.application_block_hash {
                return Err(V2LaneWorkError::Persistence(format!(
                    "Native AMX participant frontier at lane {} conflicts with the canonical carrier hash at height {}",
                    marker.lane_id.as_u32(),
                    marker.application_block_height,
                )));
            }
            if repaired_carriers.insert((
                marker.application_block_height,
                marker.application_block_hash,
            )) {
                repaired = repaired.saturating_add(
                    self.kura
                        .repair_native_amx_participant_application_evidence(&block)
                        .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?,
                );
            }
        }
        let unresolved_native = self
            .state
            .native_amx_participant_frontiers_pending_durable_evidence_snapshot_cached()
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        for marker in pending_native
            .iter()
            .filter(|marker| unresolved_native.contains(marker))
        {
            let recovery_marker = NativeAmxParticipantRecoveryMarkerV1::from(*marker);
            if remote_recovery_markers.contains(&recovery_marker) {
                continue;
            }
            return Err(V2LaneWorkError::Persistence(format!(
                "Native AMX participant frontier at lane {} remains without exact durable evidence after repair",
                marker.lane_id.as_u32(),
            )));
        }
        Ok(repaired)
    }

    /// Project the latest exact certified block for every active lane.
    ///
    /// Durable sessions are merged with every volatile committed-session owner
    /// before selecting one latest lane-local height. More than one certified
    /// proposal at that height is double-finalization evidence across views and
    /// suppresses the lane. Classification is then performed once per unique
    /// selected session against exact durable evidence.
    pub(crate) fn committed_lane_block_status_snapshot(
        &self,
    ) -> Vec<super::status::CommittedLaneBlockSnapshot> {
        let mut latest_by_lane =
            BTreeMap::<(LaneId, DataSpaceId, Hash), (CommittedLaneBlockSession, bool)>::new();
        let durable_sessions = self
            .state
            .latest_certified_lane_block_frontier_sessions_snapshot_cached();
        {
            let mut retain_latest = |session: &CommittedLaneBlockSession| {
                if let Err(error) = validate_committed_lane_block_session(session) {
                    let descriptor = &session.proposal.descriptor;
                    iroha_logger::warn!(
                        lane = %descriptor.lane_id.as_u32(),
                        dataspace = %descriptor.dataspace_id.as_u64(),
                        lane_block_height = descriptor.lane_block_height,
                        lane_block_view = descriptor.lane_block_view,
                        ?error,
                        "dropping malformed committed lane session from operator status"
                    );
                    return;
                }
                let descriptor = &session.proposal.descriptor;
                if !self.lane_route_active(
                    descriptor.lane_id,
                    descriptor.dataspace_id,
                    descriptor.lane_incarnation,
                    descriptor.proposal_height,
                ) {
                    return;
                }
                let key = (
                    descriptor.lane_id,
                    descriptor.dataspace_id,
                    descriptor.lane_incarnation,
                );
                let replace = latest_by_lane.get(&key).is_none_or(|(existing, _)| {
                    let existing = &existing.proposal.descriptor;
                    descriptor.lane_block_height > existing.lane_block_height
                });
                if replace {
                    latest_by_lane.insert(key, (session.clone(), false));
                } else if let Some((existing, ambiguous)) = latest_by_lane.get_mut(&key) {
                    let existing_descriptor = &existing.proposal.descriptor;
                    if descriptor.lane_block_height == existing_descriptor.lane_block_height
                        && session.proposal != existing.proposal
                    {
                        if !*ambiguous {
                            iroha_logger::warn!(
                                lane = %descriptor.lane_id.as_u32(),
                                dataspace = %descriptor.dataspace_id.as_u64(),
                                lane_block_height = descriptor.lane_block_height,
                                retained_lane_block_view = existing_descriptor.lane_block_view,
                                conflicting_lane_block_view = descriptor.lane_block_view,
                                retained_proposal = %existing.proposal.proposal_hash,
                                conflicting_proposal = %session.proposal.proposal_hash,
                                "suppressing double-finalized lane height from operator status"
                            );
                        }
                        *ambiguous = true;
                    }
                }
            };
            for session in &durable_sessions {
                retain_latest(session);
            }
            for session in &self.pending_committed_lanes {
                retain_latest(session);
            }
            for output in &self.committed_lane_outputs {
                retain_latest(&output.session);
            }
            for session in &self.historical_recovery_sessions {
                retain_latest(session);
            }
        }

        let current_state_height = u64::try_from(self.state.committed_height()).unwrap_or(u64::MAX);
        let mut current_state_hash = None;
        latest_by_lane
            .into_values()
            .filter_map(|(session, ambiguous)| (!ambiguous).then_some(session))
            .map(|session| {
                let proposal = &session.proposal;
                let descriptor = &proposal.descriptor;
                let execution_status = classify_committed_lane_block_execution_status(
                    || {
                        self.kura
                            .lane_block_application_receipt_conflicts_with_preflight_without_sidecar_repair(
                                proposal,
                            )
                    },
                    || {
                        self.kura
                            .read_lane_block_application_receipt(
                                descriptor.lane_id,
                                descriptor.lane_block_height,
                            )
                            .filter(|receipt| receipt.proposal == *proposal)
                            .map(|receipt| receipt.format)
                    },
                    || {
                        self.state
                            .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(
                                proposal,
                            )
                    },
                    || {
                        let preflight = self.kura.read_lane_block_execution_preflight(
                            descriptor.lane_id,
                            descriptor.lane_block_height,
                        )?;
                        if preflight.proposal != *proposal
                            || preflight.preflight_state_height != current_state_height
                        {
                            return None;
                        }
                        let state_hash = *current_state_hash
                            .get_or_insert_with(|| self.state.lane_execution_state_hash());
                        (preflight.preflight_state_hash == Some(state_hash))
                            .then(|| preflight.has_rejections())
                    },
                    || {
                        self.kura
                            .read_lane_block_execution_input(
                                descriptor.lane_id,
                                descriptor.lane_block_height,
                            )
                            .is_some_and(|input| input.proposal == *proposal)
                    },
                    || self.kura.lane_block_payload_is_recoverable(proposal),
                );
                super::status::CommittedLaneBlockSnapshot::from_committed_session_with_execution_status(
                    &session,
                    execution_status,
                )
            })
            .collect()
    }

    /// Cheap semantic revision used to coalesce operator-status projection.
    pub(crate) fn committed_lane_block_status_revision(&self) -> (u64, u64, u64) {
        (
            self.committed_lane_status_revision,
            self.kura.committed_lane_status_revision(),
            self.state.state_view_generation(),
        )
    }

    fn note_committed_lane_status_change(&mut self) {
        self.committed_lane_status_revision = self.committed_lane_status_revision.wrapping_add(1);
    }

    /// Bind locally planned lane proposals to the exact global block body.
    pub(crate) fn bind_local_candidate(
        &mut self,
        round: wire::ConsensusRound,
        block_hash: HashOf<BlockHeader>,
    ) -> V2LaneIngressOutcome {
        let output_guard = Arc::clone(&self.output_guard);
        let Some(_permit) = output_guard.acquire() else {
            return V2LaneIngressOutcome::Rejected;
        };
        if !self.round_is_current(round) {
            return V2LaneIngressOutcome::Rejected;
        }
        let Some(global_leader) = usize::try_from(self.context.leader(round.view))
            .ok()
            .and_then(|index| self.context.roster.get(index))
            .map(|entry| entry.validator.clone())
        else {
            return V2LaneIngressOutcome::Rejected;
        };
        if self.local_peer != global_leader {
            return V2LaneIngressOutcome::Rejected;
        }
        let nexus = self.state.nexus_snapshot();
        let shared_committee =
            !nexus.enabled || !proposal_lookahead_enabled(&nexus, self.context.height);
        let Some(proposals) = self.planned_lane_proposals.remove(&round) else {
            return V2LaneIngressOutcome::Duplicate;
        };
        let proposals = proposals
            .into_iter()
            .map(|proposal| {
                proposal.with_payload_block_hint(LaneBlockProposalPayloadHintV1 {
                    proposal_height: round.height,
                    proposal_view: round.view,
                    proposal_block_hash: block_hash,
                })
            })
            .collect::<Vec<_>>();
        let mut next_sessions = self.lane_sessions.clone();
        let mut inserted = false;
        for proposal in &proposals {
            let Some(lane_author) = self.expected_lane_author(proposal).cloned() else {
                return V2LaneIngressOutcome::Rejected;
            };
            if (shared_committee && lane_author != global_leader)
                || !self.lane_proposal_authorized(proposal, Some(&lane_author), false, round.view)
            {
                return V2LaneIngressOutcome::Rejected;
            }
            match next_sessions
                .insert_replanned_proposal_replacing_uncommitted_conflict(proposal.clone())
            {
                Ok(LaneBlockSessionInsertOutcome::Inserted) => inserted = true,
                Ok(LaneBlockSessionInsertOutcome::Duplicate) => {}
                Err(_) => return V2LaneIngressOutcome::Rejected,
            }
        }
        self.lane_sessions = next_sessions;
        self.locally_bound_lane_proposals.clear();
        self.pending_local_lane_proposals.clear();
        self.pending_local_lane_proposals
            .insert(block_hash, proposals);
        if inserted {
            V2LaneIngressOutcome::Inserted
        } else {
            V2LaneIngressOutcome::Duplicate
        }
    }

    /// Record the one global subject protected by the reducer's durable
    /// PrepareQC lock. The exact durable body must still be bound with
    /// [`Self::bind_locked_global_body`] before any lane proposal becomes
    /// signable.
    #[must_use]
    pub(crate) fn mark_global_body_locked(
        &mut self,
        round: wire::ConsensusRound,
        subject: wire::BlockSubject,
    ) -> Result<GlobalBodyLockOutcome, V2LaneWorkError> {
        if round.context_id != self.context.id() || round.height != self.context.height {
            return Err(V2LaneWorkError::InvalidGlobalBodyLock);
        }
        let superseded_subject = if let Some(existing) = self.globally_locked_body {
            if existing == (GlobalBodyLock { round, subject }) {
                return Ok(GlobalBodyLockOutcome::Duplicate);
            }
            if round.view <= existing.round.view {
                return Err(V2LaneWorkError::ConflictingGlobalBodyLock);
            }
            (existing.subject != subject).then_some(existing.subject)
        } else {
            None
        };
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        self.globally_locked_body = Some(GlobalBodyLock { round, subject });
        if let Some(superseded_subject) = superseded_subject
            && superseded_subject.block_hash == subject.block_hash
        {
            self.lane_sessions
                .retire_uncommitted_global_anchor(superseded_subject.block_hash);
        } else {
            self.lane_sessions
                .retire_uncommitted_global_anchors_except(subject.block_hash);
        }
        self.locally_bound_lane_proposals.clear();
        self.pending_local_lane_proposals.clear();
        self.retain_autonomous_carrier(subject.block_hash)?;
        self.merge_entries.clear();
        self.merge_claims.clear();
        self.retain_committed_lane_outputs_for_subject(subject);
        self.purge_queued_global_body_effects_except_committed_outputs();
        self.schedule_committed_lane_outputs();
        operation.complete();
        Ok(GlobalBodyLockOutcome::Inserted)
    }

    /// Prune losing pending merge entries after a certified view transition
    /// only when neither a safety lock nor a durable Decision protects an
    /// earlier immutable body.
    pub(crate) fn retain_merge_sidecars_for_global_view(
        &mut self,
        view: wire::View,
        locked_subject: Option<wire::BlockSubject>,
        decided_subject: Option<wire::BlockSubject>,
    ) -> Result<(), V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        let result = self.retain_merge_sidecars_for_global_view_guarded(
            view,
            locked_subject,
            decided_subject,
        );
        if result.is_ok() {
            operation.complete();
        }
        result
    }

    fn retain_merge_sidecars_for_global_view_guarded(
        &mut self,
        view: wire::View,
        locked_subject: Option<wire::BlockSubject>,
        decided_subject: Option<wire::BlockSubject>,
    ) -> Result<(), V2LaneWorkError> {
        let carrier_state = (view, locked_subject, decided_subject);
        if self.retained_merge_carrier_state == Some(carrier_state) {
            return Ok(());
        }
        self.purge_queued_merge_broadcasts();
        if let Some(decided) = decided_subject {
            // Publish the terminal carrier predicate before any retained lane
            // session is driven. Quorum-protected losing evidence may remain
            // cached for safety checks, but must never receive one final
            // outbound turn during Decision installation.
            self.retained_merge_carrier_state = Some(carrier_state);
            self.retire_speculative_work_after_decision(decided)?;
            self.merge_entries.clear();
            self.merge_claims.clear();
            return Ok(());
        }
        if locked_subject.is_some() {
            self.merge_entries.clear();
            self.merge_claims.clear();
            self.retained_merge_carrier_state = Some(carrier_state);
            return Ok(());
        }
        #[cfg(test)]
        {
            self.merge_retention_scans = self.merge_retention_scans.saturating_add(1);
        }
        let Some(parent) = self
            .context
            .parent_commit_qc
            .as_ref()
            .map(|certificate| certificate.subject.block_hash)
            .or_else(|| {
                self.context
                    .snapshot_bootstrap
                    .as_ref()
                    .map(|anchor| anchor.snapshot_block_hash)
            })
        else {
            self.kura
                .retain_pending_certified_merge_entry_for_locked_carrier(self.context.height, None)
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            self.retained_merge_carrier_state = Some(carrier_state);
            self.refresh_merge_candidates(view)?;
            return Ok(());
        };
        self.kura
            .prune_pending_certified_merge_entries_not_bound_to(self.context.height, parent, view)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        self.retained_merge_carrier_state = Some(carrier_state);
        self.refresh_merge_candidates(view)?;
        Ok(())
    }

    fn decision_pending(&self) -> bool {
        self.retained_merge_carrier_state
            .is_some_and(|(_, _, decided)| decided.is_some())
    }

    fn proposal_is_bound_to_decided_carrier(&self, proposal: &LaneBlockProposalV1) -> bool {
        let Some((_, _, Some(decided))) = self.retained_merge_carrier_state else {
            return false;
        };
        if proposal.descriptor.proposal_height != self.context.height {
            return false;
        }
        if let Some(hint) = proposal.payload_block_hint
            && proposal.proposal_hash == proposal.computed_proposal_hash()
            && hint.proposal_height == self.context.height
            && hint.proposal_block_hash == decided.block_hash
            && self.globally_locked_body.is_some_and(|locked| {
                locked.subject == decided
                    && locked.round.height == self.context.height
                    && locked.round.view == hint.proposal_view
            })
            && self
                .locally_bound_lane_proposals
                .get(&proposal.proposal_hash)
                == Some(&hint)
        {
            // The exact body was validated and bound before Decision, but its
            // canonical Kura publication follows global application. Keep
            // this in-memory witness so a late certificate can finish during
            // that bounded pre-publication interval.
            return true;
        }
        let Some(height) = usize::try_from(self.context.height)
            .ok()
            .and_then(NonZeroUsize::new)
        else {
            return false;
        };
        let Some(block) = self.kura.get_block(height) else {
            return false;
        };
        let Ok(canonical_payload_hash) = block.canonical_proposal_wire_hash() else {
            return false;
        };
        let canonical_subject = wire::BlockSubject {
            parent_block_hash: block.header().prev_block_hash(),
            block_hash: block.hash(),
            payload_hash: canonical_payload_hash,
        };
        canonical_subject == decided
            && block.execution_context().is_some_and(|bundle| {
                bundle.lane_payload_ownerships.iter().any(|ownership| {
                    proposal_from_ownership(ownership, decided.block_hash).as_ref()
                        == Some(proposal)
                }) || bundle.autonomous_lane_payloads.iter().any(|envelope| {
                    decode_autonomous_lane_payload_envelope(
                        envelope,
                        self.native_chain_id_hash(),
                        self.context.epoch,
                    )
                    .and_then(|payload| {
                        payload.attach_global_hint_exact(
                            LaneBlockProposalPayloadHintV1 {
                                proposal_height: block.header().height().get(),
                                proposal_view: block.header().view_change_index(),
                                proposal_block_hash: block.hash(),
                            },
                            self.native_chain_id_hash(),
                            self.context.epoch,
                        )
                    })
                    .is_ok_and(|payload| payload.origin_proposal == *proposal)
                })
            })
    }

    fn lane_message_is_allowed_after_decision(&self, message: &BlockMessage) -> bool {
        match message {
            BlockMessage::LaneBlockProposal(proposal) => {
                self.proposal_is_bound_to_decided_carrier(proposal)
            }
            BlockMessage::LaneBlockVote(vote) => self
                .canonical_proposal_for_vote_body(&vote.body)
                .is_some_and(|proposal| self.proposal_is_bound_to_decided_carrier(&proposal)),
            BlockMessage::LaneBlockQc(qc) => self
                .canonical_proposal_for_vote_body(&qc.body)
                .is_some_and(|proposal| self.proposal_is_bound_to_decided_carrier(&proposal)),
            BlockMessage::LaneBlockCertificate(certificate) => {
                certificate.proposal.descriptor.proposal_height < self.context.height
                    || self.proposal_is_bound_to_decided_carrier(&certificate.proposal)
            }
            BlockMessage::LaneHistoricalRecoveryRequest(request) => match &request.kind {
                LaneHistoricalRecoveryKindV1::NativeAmxParticipantCanonicalBlock { .. } => {
                    request.source_height() <= self.context.height
                }
                _ => request.source_height() < self.context.height,
            },
            BlockMessage::LaneHistoricalRecoveryResponse(response) => {
                self.historical_recovery_request_owners
                    .contains_key(&response.request_hash)
                    || self
                        .native_participant_recovery_request_owners
                        .contains_key(&response.request_hash)
            }
            BlockMessage::LaneExecutablePayload(payload) => {
                self.proposal_is_bound_to_decided_carrier(&payload.origin_proposal)
            }
            BlockMessage::LaneBlockNewViewVote(vote) => self
                .autonomous_payloads
                .get(&AutonomousLanePayloadKey::from(&vote.body))
                .is_some_and(|payload| {
                    self.proposal_is_bound_to_decided_carrier(&payload.origin_proposal)
                }),
            BlockMessage::LaneBlockNewViewCertificate(certificate) => self
                .autonomous_payloads
                .get(&AutonomousLanePayloadKey::from(&certificate.body))
                .is_some_and(|payload| {
                    self.proposal_is_bound_to_decided_carrier(&payload.origin_proposal)
                }),
            _ => false,
        }
    }

    fn retire_autonomous_payload_batch(
        &self,
        payloads: &[LaneExecutablePayloadV1],
    ) -> Result<(), V2LaneWorkError> {
        if payloads.is_empty() {
            return Ok(());
        }
        let queue = self.lane_drain_queue.as_ref().ok_or_else(|| {
            V2LaneWorkError::InvalidContext(
                "autonomous reservation release requires the installed live queue".to_owned(),
            )
        })?;
        let chain_id_hash = self.native_chain_id_hash();
        let epoch = self.context.epoch;
        for payload in payloads {
            let descriptor = &payload.origin_proposal.descriptor;
            let retirement = crate::kura::AutonomousLaneSlotRetirementV1::from_payload(payload);
            match self
                .kura
                .read_autonomous_lane_slot_retirement(
                    descriptor.lane_id,
                    descriptor.lane_block_height,
                    chain_id_hash,
                    epoch,
                )
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?
            {
                Some(existing) if existing == retirement => {}
                Some(_) => {
                    return Err(V2LaneWorkError::Persistence(
                        "losing autonomous carrier conflicts with its durable slot retirement"
                            .to_owned(),
                    ));
                }
                None => self
                    .kura
                    .persist_lane_executable_payload(payload, chain_id_hash, epoch)
                    .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?,
            }
            super::v2_apply::retire_autonomous_lane_slot_and_release_reservations(
                self.kura.as_ref(),
                queue.as_ref(),
                &retirement,
                chain_id_hash,
                epoch,
            )
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        }
        Ok(())
    }

    fn release_pending_autonomous_reservation_batches(&mut self) -> Result<usize, V2LaneWorkError> {
        if self.pending_autonomous_reservation_batches.is_empty() {
            return Ok(0);
        }
        let queue = self.lane_drain_queue.as_ref().ok_or_else(|| {
            V2LaneWorkError::InvalidContext(
                "autonomous reservation release requires the installed live queue".to_owned(),
            )
        })?;
        let batches = std::mem::take(&mut self.pending_autonomous_reservation_batches);
        let mut released = 0_usize;
        for batch in batches.into_values() {
            let keys = batch
                .reservations
                .iter()
                .map(|reservation| *reservation.key())
                .collect::<Vec<_>>();
            released = released.saturating_add(
                queue
                    .release_lane_reservations_in_order(&keys)
                    .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?,
            );
        }
        Ok(released)
    }

    fn release_autonomous_reservation_batch(
        &self,
        batch: &PendingAutonomousReservationBatch,
    ) -> Result<usize, V2LaneWorkError> {
        let queue = self.lane_drain_queue.as_ref().ok_or_else(|| {
            V2LaneWorkError::InvalidContext(
                "autonomous reservation release requires the installed live queue".to_owned(),
            )
        })?;
        let keys = batch
            .reservations
            .iter()
            .map(|reservation| *reservation.key())
            .collect::<Vec<_>>();
        queue
            .release_lane_reservations_in_order(&keys)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))
    }

    fn retain_autonomous_carrier(
        &mut self,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<(), V2LaneWorkError> {
        self.release_pending_autonomous_reservation_batches()?;
        let losing_payloads = self
            .autonomous_payloads
            .values()
            .filter(|payload| {
                payload
                    .origin_proposal
                    .payload_block_hint
                    .is_none_or(|hint| hint.proposal_block_hash != block_hash)
            })
            .cloned()
            .collect::<Vec<_>>();
        self.retire_autonomous_payload_batch(&losing_payloads)?;

        self.autonomous_payloads.retain(|_, payload| {
            payload
                .origin_proposal
                .payload_block_hint
                .is_some_and(|hint| hint.proposal_block_hash == block_hash)
        });
        let retained = &self.autonomous_payloads;
        self.autonomous_payload_order
            .retain(|key| retained.contains_key(key));
        self.autonomous_payload_views
            .retain(|key, _| retained.contains_key(key));
        self.autonomous_new_view_started_at
            .retain(|key, _| retained.contains_key(key));
        // Votes and certificates can name a losing carrier indirectly through
        // their payload hash. Drop the bounded collectors when the global lock
        // changes; exact retained payloads can safely rebuild a contiguous
        // certificate suffix from authenticated retransmissions.
        self.autonomous_new_view_votes =
            LaneBlockNewViewVoteCache::new(self.limits.session_capacity.get());
        self.autonomous_new_view_certificates =
            LaneBlockNewViewCertificateCache::new(self.limits.session_capacity.get());
        Ok(())
    }

    fn retire_speculative_work_after_decision(
        &mut self,
        decided: wire::BlockSubject,
    ) -> Result<(), V2LaneWorkError> {
        self.retain_autonomous_carrier(decided.block_hash)?;
        self.collect_committed_lane_sessions();
        self.lane_sessions
            .retire_uncommitted_global_anchors_except(decided.block_hash);
        self.planned_lane_proposals.clear();
        self.pending_local_lane_proposals.clear();
        // A certificate for the decided carrier may arrive after the global
        // Decision. Keep only that carrier's immutable body binding so the
        // late atomic certificate can complete; losing carriers remain
        // permanently retired.
        self.locally_bound_lane_proposals
            .retain(|_, hint| hint.proposal_block_hash == decided.block_hash);
        self.native_requests.clear();
        self.native_claims.clear();
        self.local_native_claims.clear();
        self.admitted_relays.clear();
        self.retain_committed_lane_outputs_for_subject(decided);
        self.purge_queued_global_body_effects_except_committed_outputs();
        // Global Decision retires every losing carrier, but it does not
        // supersede the decided carrier's lane certificate. Keep driving that
        // exact same-height session until its certificate and application
        // receipt cross the durable rollover boundary.
        self.drive_lane_sessions();
        self.schedule_lane_artifact_retransmissions();
        self.schedule_committed_lane_outputs();
        Ok(())
    }

    /// Bind lane proposals reconstructed from the exact durable globally
    /// locked body, then release their bounded lane-local consensus sessions.
    ///
    /// This ordinary path authenticates an immutable block header from the
    /// locked round or an earlier unchanged reproposal round. Height-one recovery must use
    /// [`Self::bind_locked_genesis_body`] instead.
    pub(crate) fn bind_locked_global_body(&mut self, block: &SignedBlock) -> V2LaneIngressOutcome {
        self.bind_locked_global_body_from_origin(
            block,
            LockedGlobalBodyOrigin::AuthenticatedHeaderAtOrBeforeLock,
        )
    }

    /// Bind the exact authenticated fixed view-zero genesis body under its
    /// durable proposal-origin lock.
    ///
    /// Genesis is signed once by its configured authority and therefore keeps
    /// a view-zero header when a certified view change moves its Proposal to a
    /// later round. The supplied staged genesis is the runner-authenticated
    /// source of truth; this path rejects every other byte sequence and every
    /// parented, context-bearing, or non-height-one body.
    pub(crate) fn bind_locked_genesis_body(
        &mut self,
        block: &SignedBlock,
        authenticated_genesis: &SignedBlock,
    ) -> V2LaneIngressOutcome {
        self.bind_locked_global_body_from_origin(
            block,
            LockedGlobalBodyOrigin::FixedGenesisViewZero {
                authenticated_genesis,
            },
        )
    }

    fn bind_locked_global_body_from_origin(
        &mut self,
        block: &SignedBlock,
        origin: LockedGlobalBodyOrigin<'_>,
    ) -> V2LaneIngressOutcome {
        let output_guard = Arc::clone(&self.output_guard);
        let Some(validation_permit) = output_guard.acquire() else {
            return V2LaneIngressOutcome::Rejected;
        };
        let block_hash = block.hash();
        let Ok(canonical_wire) = block.encode_wire() else {
            return V2LaneIngressOutcome::Rejected;
        };
        let subject = wire::BlockSubject {
            parent_block_hash: block.header().prev_block_hash(),
            block_hash,
            payload_hash: Hash::new(&canonical_wire),
        };
        let Some(global_lock) = self.globally_locked_body else {
            return V2LaneIngressOutcome::Rejected;
        };
        let origin_matches = match origin {
            LockedGlobalBodyOrigin::AuthenticatedHeaderAtOrBeforeLock => {
                self.context.height != 1
                    && block.header().view_change_index() <= global_lock.round.view
            }
            LockedGlobalBodyOrigin::FixedGenesisViewZero {
                authenticated_genesis,
            } => {
                let Ok(authenticated_wire) = authenticated_genesis
                    .canonical_resultless_proposal()
                    .encode_wire()
                else {
                    return V2LaneIngressOutcome::Rejected;
                };
                self.context.height == 1
                    && self.context.parent_commit_qc.is_none()
                    && self.context.snapshot_bootstrap.is_none()
                    && block.header().height().get() == 1
                    && block.header().view_change_index() == 0
                    && block.header().prev_block_hash().is_none()
                    && block.header().execution_context_hash().is_none()
                    && block.execution_context().is_none()
                    && block.is_resultless_proposal()
                    && canonical_wire == authenticated_wire
            }
        };
        if global_lock.subject != subject
            || !origin_matches
            || block.header().height().get() != self.context.height
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let bundle = block.execution_context();
        let ownerships = bundle.map_or(&[][..], |bundle| bundle.lane_payload_ownerships.as_slice());
        let autonomous_envelopes =
            bundle.map_or(&[][..], |bundle| bundle.autonomous_lane_payloads.as_slice());
        if ownerships.len().saturating_add(autonomous_envelopes.len())
            > self.limits.session_capacity.get()
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let routes = bundle
            .into_iter()
            .flat_map(|bundle| &bundle.external)
            .map(|entry| RoutingDecision::new(entry.lane_id, entry.dataspace_id))
            .collect::<Vec<_>>();
        let hashes = bundle
            .into_iter()
            .flat_map(|bundle| &bundle.external)
            .map(|entry| Hash::from(entry.entrypoint_hash))
            .collect::<Vec<_>>();
        let global_view = block.header().view_change_index();
        let Some(global_leader) = usize::try_from(self.context.leader(global_view))
            .ok()
            .and_then(|index| self.context.roster.get(index))
            .map(|entry| &entry.validator)
        else {
            return V2LaneIngressOutcome::Rejected;
        };
        let nexus = self.state.nexus_snapshot();
        let shared_committee =
            !nexus.enabled || !proposal_lookahead_enabled(&nexus, self.context.height);
        let canonical_recovery = canonical_v2_lane_payload_matches_kura(
            self.state.as_ref(),
            self.kura.as_ref(),
            &self.context,
            block,
        );
        if !canonical_recovery {
            let Ok(expected) = prepare_v2_lane_payload_plan(
                self.state.as_ref(),
                self.kura.as_ref(),
                &self.context,
                global_view,
                global_leader,
                &routes,
                &hashes,
            ) else {
                return V2LaneIngressOutcome::Rejected;
            };
            if !expected.unavailable_indices.is_empty() || expected.ownerships != ownerships {
                return V2LaneIngressOutcome::Rejected;
            }
        }
        let mut proposals = Vec::with_capacity(ownerships.len());
        for ownership in ownerships {
            let Some(proposal) = proposal_from_ownership(ownership, block_hash) else {
                return V2LaneIngressOutcome::Rejected;
            };
            let descriptor = &proposal.descriptor;
            let expected_lane_author = self.expected_lane_author(&proposal);
            if descriptor.proposal_height != self.context.height
                || ownership.proposal_view != global_view
                || !self.qc_mode_tag_matches_context(
                    &descriptor.qc_mode_tag,
                    descriptor.lane_id,
                    descriptor.dataspace_id,
                )
                || !self.lane_route_active(
                    descriptor.lane_id,
                    descriptor.dataspace_id,
                    descriptor.lane_incarnation,
                    descriptor.proposal_height,
                )
                || self.expected_lane_validators(descriptor.lane_id, descriptor.proposal_height)
                    != Some(descriptor.validator_set.clone())
                || expected_lane_author.is_none()
                || (shared_committee && expected_lane_author != Some(global_leader))
            {
                return V2LaneIngressOutcome::Rejected;
            }
            proposals.push(proposal);
        }

        let local = self.pending_local_lane_proposals.get(&block_hash).cloned();
        if local.as_ref().is_some_and(|planned| planned != &proposals) {
            return V2LaneIngressOutcome::Rejected;
        }
        let global_hint = LaneBlockProposalPayloadHintV1 {
            proposal_height: self.context.height,
            proposal_view: global_view,
            proposal_block_hash: block_hash,
        };
        let mut anchored_autonomous_payloads = Vec::with_capacity(autonomous_envelopes.len());
        for envelope in autonomous_envelopes {
            let Ok(payload) = decode_autonomous_lane_payload_envelope(
                envelope,
                self.native_chain_id_hash(),
                self.context.epoch,
            ) else {
                return V2LaneIngressOutcome::Rejected;
            };
            let proposal = &payload.origin_proposal;
            let descriptor = &proposal.descriptor;
            if !self.unanchored_autonomous_origin_matches_context(proposal)
                || self.expected_lane_author(proposal) != Some(&payload.producer)
                || !self.autonomous_reservation_keys_are_canonical(
                    proposal,
                    &payload.producer,
                    &payload.reservation_keys,
                )
                || descriptor.proposal_height != self.context.height
            {
                return V2LaneIngressOutcome::Rejected;
            }
            let Ok(attached) = payload.attach_global_hint_exact(
                global_hint,
                self.native_chain_id_hash(),
                self.context.epoch,
            ) else {
                return V2LaneIngressOutcome::Rejected;
            };
            proposals.push(attached.origin_proposal.clone());
            anchored_autonomous_payloads.push(attached);
        }
        if proposals
            .iter()
            .map(|proposal| proposal.proposal_hash)
            .collect::<BTreeSet<_>>()
            .len()
            != proposals.len()
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let locally_authored = proposals
            .iter()
            .filter(|proposal| self.expected_lane_author(proposal) == Some(&self.local_peer))
            .cloned()
            .collect::<Vec<_>>();
        let mut next_sessions = self.lane_sessions.clone();
        let mut inserted = false;
        for proposal in &proposals {
            match next_sessions
                .insert_recovered_proposal_replacing_uncommitted_conflict(proposal.clone())
            {
                Ok(LaneBlockSessionInsertOutcome::Inserted) => inserted = true,
                Ok(LaneBlockSessionInsertOutcome::Duplicate) => {}
                Err(_) => return V2LaneIngressOutcome::Rejected,
            }
        }
        let Some(locally_bound_lane_proposals) = proposals
            .iter()
            .map(|proposal| {
                proposal
                    .payload_block_hint
                    .map(|hint| (proposal.proposal_hash, hint))
            })
            .collect::<Option<BTreeMap<_, _>>>()
        else {
            return V2LaneIngressOutcome::Rejected;
        };
        // Do not delete any losing durable sidecar until every in-memory
        // locked-body check and session insertion has succeeded. Once this
        // exact retention succeeds, the remaining operations are infallible.
        drop(validation_permit);
        let Some(persistence) = output_guard.begin_fail_stop_operation() else {
            return V2LaneIngressOutcome::Rejected;
        };
        if self
            .kura
            .retain_pending_certified_merge_entry_for_locked_carrier(
                self.context.height,
                bundle.and_then(|bundle| bundle.merge_entry.as_ref()),
            )
            .is_err()
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let mut winning_unanchored = BTreeMap::new();
        for payload in &anchored_autonomous_payloads {
            let key = AutonomousLanePayloadKey::from(&payload.origin_proposal);
            let mut unanchored = payload.clone();
            unanchored.origin_proposal.payload_block_hint = None;
            if winning_unanchored.insert(key, unanchored).is_some() {
                return V2LaneIngressOutcome::Rejected;
            }
        }
        if winning_unanchored.iter().any(|(key, payload)| {
            self.pending_autonomous_anchor_payloads
                .get(key)
                .is_some_and(|pending| pending != payload)
        }) {
            return V2LaneIngressOutcome::Rejected;
        }
        let losing_pending = self
            .pending_autonomous_anchor_payloads
            .iter()
            .filter(|(key, payload)| winning_unanchored.get(key) != Some(*payload))
            .map(|(_, payload)| payload.clone())
            .collect::<Vec<_>>();
        if self
            .retire_autonomous_payload_batch(&losing_pending)
            .is_err()
        {
            return V2LaneIngressOutcome::Rejected;
        }
        self.pending_autonomous_anchor_payloads.clear();
        for payload in &anchored_autonomous_payloads {
            let key = AutonomousLanePayloadKey::from(&payload.origin_proposal);
            match self.autonomous_payloads.get(&key) {
                Some(existing) if existing == payload => {}
                Some(_) => return V2LaneIngressOutcome::Rejected,
                None => {
                    self.autonomous_payload_views
                        .insert(key, payload.origin_proposal.descriptor.lane_block_view);
                    self.autonomous_payloads.insert(key, payload.clone());
                    self.autonomous_payload_order.push_back(key);
                }
            }
        }
        self.pending_local_lane_proposals.remove(&block_hash);
        self.pending_local_lane_proposals.clear();
        self.lane_sessions = next_sessions;
        self.locally_bound_lane_proposals = locally_bound_lane_proposals;
        for proposal in &proposals {
            let Some(payload) = self.durable_autonomous_payload_for_proposal(proposal) else {
                continue;
            };
            if let Err(error) = self.persist_and_authorize_autonomous_payload(&payload, proposal) {
                iroha_logger::error!(
                    %error,
                    lane = %proposal.descriptor.lane_id.as_u32(),
                    lane_block_height = proposal.descriptor.lane_block_height,
                    "globally protected autonomous payload failed its durable READY boundary"
                );
                return V2LaneIngressOutcome::Rejected;
            }
            if let Err(error) =
                self.restore_autonomous_new_view_state(&payload, global_view, Instant::now())
            {
                iroha_logger::error!(
                    %error,
                    lane = %proposal.descriptor.lane_id.as_u32(),
                    lane_block_height = proposal.descriptor.lane_block_height,
                    "globally protected autonomous payload failed NewView cursor restoration"
                );
                return V2LaneIngressOutcome::Rejected;
            }
        }
        for proposal in locally_authored {
            self.fanout_lane_message(
                BlockMessage::LaneBlockProposal(proposal.clone()),
                &proposal.descriptor.validator_set,
            );
        }
        self.drive_lane_sessions();
        let outcome = if inserted {
            V2LaneIngressOutcome::Inserted
        } else {
            V2LaneIngressOutcome::Duplicate
        };
        persistence.complete();
        outcome
    }

    /// Persist only completed lane sessions anchored by canonical Kura blocks.
    ///
    /// # Errors
    ///
    /// Returns [`V2LaneWorkError::Persistence`] if an anchored certificate or
    /// its canonical globally-applied receipt cannot be written durably.
    pub(crate) fn persist_anchored_sessions(&mut self) -> Result<usize, V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        // Block sync can deliver and apply the current canonical body after
        // this height's adapter was constructed. Rehydrate its exact Kura
        // ownerships at the rollover boundary so a validator which missed the
        // lane CommitQC retains a bounded proposal source for certificate
        // recovery instead of waiting forever with an already-applied block.
        self.hydrate_canonical_lane_artifacts()?;
        self.collect_committed_lane_sessions();
        let mut sessions = self
            .pending_committed_lanes
            .iter()
            .cloned()
            .collect::<Vec<_>>();
        sessions.sort_by_key(|session| {
            let descriptor = &session.proposal.descriptor;
            (
                descriptor.lane_id,
                descriptor.dataspace_id,
                descriptor.lane_incarnation,
                descriptor.lane_block_height,
                descriptor.lane_block_view,
            )
        });
        let mut retained = VecDeque::new();
        let mut persisted = 0usize;
        for session in sessions {
            if !self.session_has_canonical_anchor(&session) {
                retained.push_back(session);
                continue;
            }
            if !self.proposal_anchor_is_committed_in_state(&session.proposal) {
                return Err(V2LaneWorkError::Persistence(
                    "lane certificate anchor is not committed in State".to_owned(),
                ));
            }
            // A complete certificate may arrive through recovery without this
            // validator ever executing the local Prepare-to-Commit transition.
            // Preserve the same ordering as the live path: the authenticated
            // READY quorum must be durable before the certified autonomous
            // bundle can become a Kura publication source.
            self.persist_autonomous_prepare_availability(&session.proposal, &session.prepare_qc)
                .map_err(V2LaneWorkError::Persistence)?;
            // `CommittedLaneBlockSession` is an internal transport container,
            // not a validated proof type. Recheck every proof variant before
            // the same-proposal shortcut can retire it against an earlier
            // durable certificate.
            let pops = self.pops_for_lane_session(&session);
            let candidate = CertifiedLaneBlockArtifact::new(session.clone(), pops.clone());
            Kura::validate_certified_lane_block_artifact(&candidate).map_err(|message| {
                V2LaneWorkError::Persistence(format!(
                    "pending committed lane certificate is invalid: {message}"
                ))
            })?;
            let descriptor = &session.proposal.descriptor;
            let autonomous_anchor =
                self.canonical_autonomous_anchor_matches_kura(&session.proposal);
            let durable_exact_proposal = self
                .kura
                .read_certified_lane_block_artifact(
                    descriptor.lane_id,
                    descriptor.lane_block_height,
                )
                .filter(|durable| durable.proposal == session.proposal);
            if let Some(durable) = durable_exact_proposal {
                if autonomous_anchor {
                    // Autonomous certification is merge eligibility, not
                    // evidence that the carrier block already executed these
                    // entrypoints. Its application receipt is written only by
                    // the later canonical merge carrier.
                    persisted = persisted.saturating_add(1);
                    continue;
                }
                if !self
                    .state
                    .certified_lane_block_session_is_applied_or_snapshot_anchored_cached(&session)
                {
                    if !self
                        .state
                        .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(
                            &durable.proposal,
                        )
                    {
                        return Err(V2LaneWorkError::Persistence(
                            "globally applied lane block has no applied predecessor".to_owned(),
                        ));
                    }
                    let receipt_persisted = self
                        .kura
                        .persist_lane_block_application_receipt_if_ready(&durable.proposal)
                        .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
                    if !receipt_persisted {
                        return Err(V2LaneWorkError::Persistence(
                            "globally applied lane block has no recoverable canonical results"
                                .to_owned(),
                        ));
                    }
                }
                // Quorum signer subsets are proof variants, not lane-block
                // identity. Retain the first exact durable proof and retire
                // this volatile replay only after repairing or observing the
                // same proposal's application witness. Peers must otherwise
                // keep serving the lane session so a lagging validator can
                // reconstruct it.
                persisted = persisted.saturating_add(1);
                continue;
            }
            self.state
                .persist_committed_lane_block_session_lifecycle_bound(&session, &pops)
                .map_err(V2LaneWorkError::Persistence)?;
            if autonomous_anchor {
                persisted = persisted.saturating_add(1);
                continue;
            }
            if self
                .state
                .certified_lane_block_session_is_applied_or_snapshot_anchored_cached(&session)
            {
                persisted = persisted.saturating_add(1);
                continue;
            }
            if !self
                .state
                .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(
                    &session.proposal,
                )
            {
                return Err(V2LaneWorkError::Persistence(
                    "globally applied lane block has no applied predecessor".to_owned(),
                ));
            }
            let receipt_persisted = self
                .kura
                .persist_lane_block_application_receipt_if_ready(&session.proposal)
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            if !receipt_persisted {
                return Err(V2LaneWorkError::Persistence(
                    "globally applied lane block has no recoverable canonical results".to_owned(),
                ));
            }
            persisted = persisted.saturating_add(1);
        }
        self.pending_committed_lanes = retained;
        self.schedule_committed_lane_outputs();
        operation.complete();
        Ok(persisted)
    }

    /// Build the complete lane-output rollover authority after every winning
    /// current-height session is independently readable across Kura's strict
    /// certificate and application-receipt boundaries.
    pub(crate) fn durable_lane_rollover_authority(
        &self,
        finality_artifact: &wire::finality::V2FinalityArtifact,
    ) -> Result<Option<DurableLaneRolloverAuthority>, V2LaneWorkError> {
        let _permit = self
            .output_guard
            .acquire()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        finality_artifact
            .validate()
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        if finality_artifact.height_context != self.context {
            return Err(V2LaneWorkError::Persistence(
                "lane rollover finality authority differs from the frozen height context"
                    .to_owned(),
            ));
        }

        let Some(height) = usize::try_from(finality_artifact.height)
            .ok()
            .and_then(NonZeroUsize::new)
        else {
            return Err(V2LaneWorkError::Persistence(
                "lane rollover finality authority has an invalid zero height".to_owned(),
            ));
        };
        let block = self.kura.get_block(height).ok_or_else(|| {
            V2LaneWorkError::Persistence(
                "lane rollover finality authority has no canonical block body".to_owned(),
            )
        })?;
        if block.header().height().get() != finality_artifact.height
            || block.hash() != finality_artifact.block_hash
        {
            return Err(V2LaneWorkError::Persistence(
                "lane rollover finality authority differs from the canonical block body".to_owned(),
            ));
        }
        // This boundary audits canonical lane ownership, not the already
        // validated execution plan as a whole. In particular, result-bearing
        // genesis and any other already-finalized canonical empty ownership
        // set have no lane durability debt; external entries alone do not
        // manufacture one at rollover.
        let bundle = block.execution_context();
        let ownerships = bundle.map_or(&[][..], |bundle| bundle.lane_payload_ownerships.as_slice());
        let autonomous_envelopes =
            bundle.map_or(&[][..], |bundle| bundle.autonomous_lane_payloads.as_slice());
        if ownerships.len().saturating_add(autonomous_envelopes.len())
            > self.limits.session_capacity.get()
        {
            return Err(V2LaneWorkError::Persistence(
                "canonical lane payload exceeds the frozen session capacity".to_owned(),
            ));
        }
        let mut winning_proposals = BTreeMap::new();
        for ownership in ownerships {
            let proposal = proposal_from_ownership(ownership, finality_artifact.block_hash)
                .ok_or_else(|| {
                    V2LaneWorkError::Persistence(
                        "canonical lane ownership cannot reconstruct its exact proposal".to_owned(),
                    )
                })?;
            if winning_proposals
                .insert(proposal.proposal_hash, proposal)
                .is_some()
            {
                return Err(V2LaneWorkError::Persistence(
                    "canonical lane payload contains a duplicate winning proposal".to_owned(),
                ));
            }
        }
        let chain_id = self.context.chain_id.clone().into_inner();
        let chain_id_hash = Hash::new(chain_id.as_bytes());
        for envelope in autonomous_envelopes {
            let payload = decode_autonomous_lane_payload_envelope(
                envelope,
                chain_id_hash,
                self.context.epoch,
            )
            .and_then(|payload| {
                payload.attach_global_hint_exact(
                    LaneBlockProposalPayloadHintV1 {
                        proposal_height: finality_artifact.height,
                        proposal_view: block.header().view_change_index(),
                        proposal_block_hash: finality_artifact.block_hash,
                    },
                    chain_id_hash,
                    self.context.epoch,
                )
            })
            .map_err(|error| {
                V2LaneWorkError::Persistence(format!(
                    "canonical autonomous lane anchor is invalid: {error}"
                ))
            })?;
            let proposal = payload.origin_proposal;
            if winning_proposals
                .insert(proposal.proposal_hash, proposal)
                .is_some()
            {
                return Err(V2LaneWorkError::Persistence(
                    "canonical lane payload contains a duplicate autonomous proposal".to_owned(),
                ));
            }
        }
        let winning_proposal_hashes = winning_proposals.keys().copied().collect::<BTreeSet<_>>();
        let mut retained_proposal_hashes = BTreeSet::new();
        for output in &self.committed_lane_outputs {
            let proposal = &output.session.proposal;
            if winning_proposals.get(&proposal.proposal_hash) != Some(proposal)
                || !retained_proposal_hashes.insert(proposal.proposal_hash)
            {
                return Err(V2LaneWorkError::Persistence(
                    "retained lane CommitQC is not an exact unique winner of the applied block"
                        .to_owned(),
                ));
            }
        }
        if !durable_lane_completion_matches_finality(self.kura.as_ref(), finality_artifact)
            .map_err(V2LaneWorkError::Persistence)?
        {
            return Ok(None);
        }
        let mut durable_sessions = BTreeMap::new();
        for proposal in winning_proposals.values() {
            let descriptor = &proposal.descriptor;
            let durable = self
                .kura
                .read_certified_lane_block_artifact(
                    descriptor.lane_id,
                    descriptor.lane_block_height,
                )
                .ok_or_else(|| {
                    V2LaneWorkError::Persistence(
                        "retained lane CommitQC has no durable certified artifact".to_owned(),
                    )
                })?;
            let autonomous_payload = self
                .canonical_autonomous_anchor_matches_kura(proposal)
                .then(|| {
                    self.kura.read_autonomous_lane_block_artifact(
                        descriptor.lane_id,
                        descriptor.lane_block_height,
                        chain_id_hash,
                        self.context.epoch,
                    )
                })
                .flatten()
                .map(|artifact| artifact.executable_payload);
            let application_receipt = if autonomous_payload.is_some() {
                None
            } else {
                Some(
                    self.kura
                        .read_lane_block_application_receipt(
                            descriptor.lane_id,
                            descriptor.lane_block_height,
                        )
                        .ok_or_else(|| {
                            V2LaneWorkError::Persistence(
                                "retained lane CommitQC has no durable application receipt"
                                    .to_owned(),
                            )
                        })?,
                )
            };
            let Some(hint) = proposal.payload_block_hint else {
                return Err(V2LaneWorkError::Persistence(
                    "retained current-height lane CommitQC has no global block anchor".to_owned(),
                ));
            };
            let retained = self
                .committed_lane_outputs
                .iter()
                .find(|output| output.session.proposal.proposal_hash == proposal.proposal_hash);
            if let Some(output) = retained {
                let session = &output.session;
                let pops = self.pops_for_lane_session(session);
                let candidate = CertifiedLaneBlockArtifact::new(session.clone(), pops);
                Kura::validate_certified_lane_block_artifact(&candidate).map_err(|message| {
                    V2LaneWorkError::Persistence(format!(
                        "retained lane CommitQC output is invalid: {message}"
                    ))
                })?;
                let same_commit_decision = session.commit_qc.body == durable.commit_qc.body
                    && session.commit_qc.validator_set_hash_version
                        == durable.commit_qc.validator_set_hash_version
                    && session.commit_qc.validator_set_hash == durable.commit_qc.validator_set_hash
                    && session.commit_qc.validator_set == durable.commit_qc.validator_set
                    && session.commit_qc.payload_availability_qc
                        == durable.commit_qc.payload_availability_qc;
                if !same_commit_decision {
                    return Err(V2LaneWorkError::Persistence(
                        "retained lane CommitQC differs from the exact durable decision".to_owned(),
                    ));
                }
            }
            if durable.proposal != *proposal
                || descriptor.proposal_height != finality_artifact.height
                || hint.proposal_height != finality_artifact.height
                || hint.proposal_block_hash != finality_artifact.block_hash
                || application_receipt.as_ref().is_some_and(|receipt| {
                    receipt.proposal != *proposal
                        || receipt.application_block_height != finality_artifact.height
                        || receipt.application_block_hash != finality_artifact.block_hash
                })
            {
                return Err(V2LaneWorkError::Persistence(
                    "retained lane CommitQC is not bound to the exact applied global artifact"
                        .to_owned(),
                ));
            }
            let mut signer_pops = durable.signer_pops.clone();
            if let Some(output) = retained {
                signer_pops.extend(self.pops_for_lane_session(&output.session));
            }
            let source = if let Some(payload) = autonomous_payload {
                if payload.origin_proposal != *proposal {
                    return Err(V2LaneWorkError::Persistence(
                        "autonomous rollover payload differs from its certified proposal"
                            .to_owned(),
                    ));
                }
                DurableLaneSessionSource::autonomous_certified(
                    finality_artifact,
                    &durable,
                    &payload,
                    signer_pops,
                )
            } else {
                DurableLaneSessionSource::persistent(
                    finality_artifact,
                    &durable,
                    application_receipt
                        .as_ref()
                        .expect("ordinary rollover source requires its application receipt"),
                    signer_pops,
                )
            };
            if durable_sessions
                .insert(proposal.proposal_hash, source)
                .is_some()
            {
                return Err(V2LaneWorkError::Persistence(
                    "duplicate winning lane proposal in rollover authority".to_owned(),
                ));
            }
        }
        Ok(Some(DurableLaneRolloverAuthority::new(
            finality_artifact,
            winning_proposal_hashes,
            durable_sessions,
        )))
    }

    /// Advance one earlier-height certificate through its strict durability
    /// and application-witness boundary.
    ///
    /// The FIFO is serviced independently of the current global carrier.
    /// Recoverable dependencies retain the exact session and publish one
    /// bounded, payload-free stage observation. Invalid or conflicting durable
    /// evidence returns an error without retiring the owner, causing the
    /// process-wide output guard to fail closed.
    pub(crate) fn service_next_historical_recovery(
        &mut self,
    ) -> Result<HistoricalRecoveryServiceOutcome, V2LaneWorkError> {
        let Some(session) = self.historical_recovery_sessions.pop_front() else {
            return Ok(HistoricalRecoveryServiceOutcome::Idle);
        };
        let output_guard = Arc::clone(&self.output_guard);
        let Some(operation) = output_guard.begin_fail_stop_operation() else {
            self.historical_recovery_sessions.push_front(session);
            return Err(V2LaneWorkError::RestartRequired);
        };
        let identity = match HistoricalRecoveryIdentity::from_proposal(&session.proposal) {
            Ok(identity) => identity,
            Err(error) => {
                self.historical_recovery_sessions.push_front(session);
                return Err(error);
            }
        };
        match self.persist_historical_recovery_session(&session) {
            Ok(HistoricalRecoveryPersistence::Complete) => {
                self.historical_recovery_diagnostics.complete(identity);
                self.retire_historical_recovery_request(identity);
                operation.complete();
                Ok(HistoricalRecoveryServiceOutcome::Complete(identity))
            }
            Ok(HistoricalRecoveryPersistence::Waiting(reason)) => {
                let observation = self
                    .historical_recovery_diagnostics
                    .observe(identity, reason);
                if let Err(error) =
                    self.schedule_historical_recovery_request(identity, &session, observation.retry)
                {
                    self.historical_recovery_sessions.push_front(session);
                    return Err(error);
                }
                self.historical_recovery_sessions.push_back(session);
                if observation.first_observation {
                    iroha_logger::info!(
                        lane = identity.lane_id.as_u32(),
                        dataspace = identity.dataspace_id.as_u64(),
                        ?identity.lane_incarnation,
                        lane_block_height = identity.lane_block_height,
                        proposal_height = identity.proposal_height,
                        ?identity.proposal_hash,
                        ?identity.descriptor_hash,
                        ?identity.proposal_block_hash,
                        stage = ?observation.stage,
                        reason = ?observation.reason,
                        retry = ?observation.retry,
                        "scheduled typed historical lane recovery retry"
                    );
                }
                if observation.became_stuck {
                    iroha_logger::warn!(
                        lane = identity.lane_id.as_u32(),
                        dataspace = identity.dataspace_id.as_u64(),
                        ?identity.lane_incarnation,
                        lane_block_height = identity.lane_block_height,
                        proposal_height = identity.proposal_height,
                        ?identity.proposal_hash,
                        ?identity.descriptor_hash,
                        ?identity.proposal_block_hash,
                        stage = ?observation.stage,
                        reason = ?observation.reason,
                        retry = ?observation.retry,
                        consecutive_attempts = observation.consecutive_attempts,
                        total_attempts = observation.total_attempts,
                        "historical lane recovery remains stuck at a typed durable boundary"
                    );
                }
                operation.complete();
                Ok(HistoricalRecoveryServiceOutcome::Waiting(observation))
            }
            Err(error) => {
                self.historical_recovery_sessions.push_front(session);
                Err(error)
            }
        }
    }

    fn retire_historical_recovery_request(&mut self, identity: HistoricalRecoveryIdentity) {
        if let Some(retired) = self.historical_recovery_requests.remove(&identity) {
            self.historical_recovery_request_owners
                .remove(&retired.request_hash);
        }
    }

    fn retire_native_participant_recovery_request(
        &mut self,
        marker: NativeAmxParticipantRecoveryMarkerV1,
    ) {
        if let Some(retired) = self.native_participant_recovery_requests.remove(&marker) {
            self.native_participant_recovery_request_owners
                .remove(&retired.request_hash);
            self.effects.retain(|effect| {
                !matches!(
                    effect,
                    V2LaneWorkEffect::PostLaneBlock {
                        message: BlockMessage::LaneHistoricalRecoveryRequest(request),
                        ..
                    } if HashOf::new(request.as_ref()) == retired.request_hash
                )
            });
            self.effect_keys = self.effects.iter().map(lane_work_effect_key).collect();
        }
    }

    fn pending_native_participant_recovery_markers(
        &self,
    ) -> Result<BTreeSet<NativeAmxParticipantRecoveryMarkerV1>, V2LaneWorkError> {
        let markers = self
            .state
            .native_amx_participant_frontiers_pending_durable_evidence_snapshot_cached()
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        if markers.len() > self.limits.session_capacity.get() {
            return Err(V2LaneWorkError::Persistence(
                "Native AMX participant carrier recovery exceeds the bounded session capacity"
                    .to_owned(),
            ));
        }
        Ok(markers
            .into_iter()
            .map(NativeAmxParticipantRecoveryMarkerV1::from)
            .collect())
    }

    fn reconcile_native_participant_recovery_requests(
        &mut self,
    ) -> Result<BTreeSet<NativeAmxParticipantRecoveryMarkerV1>, V2LaneWorkError> {
        let pending = self.pending_native_participant_recovery_markers()?;
        let resolved = self
            .native_participant_recovery_requests
            .keys()
            .filter(|marker| !pending.contains(marker))
            .copied()
            .collect::<Vec<_>>();
        for marker in resolved {
            self.retire_native_participant_recovery_request(marker);
        }
        Ok(pending)
    }

    /// Advance at most one deterministic Native participant recovery fanout.
    ///
    /// State remains the authoritative retry queue. An effect-capacity or
    /// request-capacity boundary therefore leaves no response owner behind;
    /// the next service turn rotates to the next pending marker and retries.
    pub(crate) fn service_next_native_participant_recovery_request(
        &mut self,
    ) -> Result<(), V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let Some(_permit) = output_guard.acquire() else {
            return Err(V2LaneWorkError::RestartRequired);
        };
        let pending = self.reconcile_native_participant_recovery_requests()?;
        if pending.is_empty() {
            self.native_participant_recovery_retry_cursor = 0;
            return Ok(());
        }
        let markers = pending.into_iter().collect::<Vec<_>>();
        let start = self.native_participant_recovery_retry_cursor % markers.len();
        let marker = markers[start];
        let _queued = self.schedule_native_participant_recovery_request(marker)?;
        self.native_participant_recovery_retry_cursor = (start + 1) % markers.len();
        Ok(())
    }

    fn schedule_native_participant_recovery_request(
        &mut self,
        marker: NativeAmxParticipantRecoveryMarkerV1,
    ) -> Result<bool, V2LaneWorkError> {
        if !native_participant_recovery_marker_is_well_formed(&marker)
            || !self.lane_route_active(
                marker.lane_id,
                marker.dataspace_id,
                marker.lane_incarnation,
                marker.application_block_height,
            )
            || self
                .state
                .committed_block_hash_at_height(marker.application_block_height)
                != Some(marker.application_block_hash)
        {
            return Err(V2LaneWorkError::Persistence(
                "refusing Native participant carrier recovery for a malformed, stale, or non-canonical frontier"
                    .to_owned(),
            ));
        }
        let finality = self
            .kura
            .v2_finality_artifact(marker.application_block_height)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?
            .ok_or_else(|| {
                V2LaneWorkError::Persistence(
                    "Native participant carrier recovery lacks durable V2 finality".to_owned(),
                )
            })?;
        finality.verify().map_err(|error| {
            V2LaneWorkError::Persistence(format!(
                "Native participant carrier recovery finality is invalid: {error}"
            ))
        })?;
        let execution_commitment = finality.commit_qc.execution_commitment;
        if finality.height != marker.application_block_height
            || finality.block_hash != marker.application_block_hash
            || execution_commitment.validate().is_err()
            || execution_commitment.native_amx_application_manifest_count == 0
        {
            return Err(V2LaneWorkError::Persistence(
                "Native participant carrier recovery finality conflicts with the exact frontier"
                    .to_owned(),
            ));
        }
        let request = LaneHistoricalRecoveryRequestV1 {
            version: LANE_HISTORICAL_RECOVERY_VERSION_V2,
            requester: self.local_peer.clone(),
            certificate: None,
            signer_pops: BTreeMap::new(),
            kind: LaneHistoricalRecoveryKindV1::NativeAmxParticipantCanonicalBlock {
                marker: Box::new(marker),
                finality_artifact_hash: HashOf::new(&finality),
                execution_commitment: Box::new(execution_commitment),
            },
        };
        if !self.historical_recovery_request_fits_frame(&request) {
            return Err(V2LaneWorkError::Persistence(
                "Native participant carrier recovery request exceeds the authenticated frame bound"
                    .to_owned(),
            ));
        }
        let request_hash = HashOf::new(&request);
        let local_peer = self.local_peer.clone();
        let mut seen = BTreeSet::new();
        let eligible_peers = finality
            .commit_qc
            .signers
            .iter()
            .filter_map(|index| {
                usize::try_from(*index)
                    .ok()
                    .and_then(|index| finality.height_context.roster.get(index))
                    .map(|entry| entry.validator.clone())
            })
            .filter(|peer| peer != &local_peer && seen.insert(peer.clone()))
            .collect::<Vec<_>>();
        if eligible_peers.is_empty() {
            return Err(V2LaneWorkError::Persistence(
                "Native participant carrier recovery has no remote CommitQC signer".to_owned(),
            ));
        }
        if let Some(existing) = self.native_participant_recovery_requests.get(&marker) {
            if existing.request != request
                || existing.request_hash != request_hash
                || existing.eligible_peers != eligible_peers
            {
                self.retire_native_participant_recovery_request(marker);
            }
        }
        if !self
            .native_participant_recovery_requests
            .contains_key(&marker)
        {
            if self
                .historical_recovery_requests
                .len()
                .saturating_add(self.native_participant_recovery_requests.len())
                >= self.limits.session_capacity.get()
            {
                return Ok(false);
            }
            if self
                .historical_recovery_request_owners
                .contains_key(&request_hash)
                || self
                    .native_participant_recovery_request_owners
                    .contains_key(&request_hash)
            {
                return Err(V2LaneWorkError::Persistence(
                    "Native participant recovery request hash aliases another owner".to_owned(),
                ));
            }
        }

        let next_peer_index = self
            .native_participant_recovery_requests
            .get(&marker)
            .map_or(0, |outstanding| {
                outstanding.next_peer_index % eligible_peers.len()
            });
        let peer = eligible_peers[next_peer_index].clone();
        if !self.push_effect(V2LaneWorkEffect::PostLaneBlock {
            peer,
            message: BlockMessage::LaneHistoricalRecoveryRequest(Box::new(request.clone())),
        }) {
            return Ok(false);
        }
        let following_peer_index = (next_peer_index + 1) % eligible_peers.len();
        if let Some(outstanding) = self.native_participant_recovery_requests.get_mut(&marker) {
            outstanding.next_peer_index = following_peer_index;
        } else {
            debug_assert!(
                !self
                    .native_participant_recovery_request_owners
                    .contains_key(&request_hash)
            );
            self.native_participant_recovery_request_owners
                .insert(request_hash, marker);
            self.native_participant_recovery_requests.insert(
                marker,
                OutstandingNativeParticipantRecoveryRequest {
                    request_hash,
                    request,
                    eligible_peers,
                    next_peer_index: following_peer_index,
                },
            );
        }
        Ok(true)
    }

    fn historical_recovery_request_fits_frame(
        &self,
        request: &LaneHistoricalRecoveryRequestV1,
    ) -> bool {
        BlockMessage::LaneHistoricalRecoveryRequest(Box::new(request.clone()))
            .encode()
            .len()
            <= self
                .limits
                .merge_share_frame_capacity
                .get()
                .min(MAX_MERGE_EXECUTION_SOURCE_BUNDLE_BYTES)
    }

    fn historical_recovery_signer_pops(
        &self,
        session: &CommittedLaneBlockSession,
    ) -> Result<BTreeMap<PublicKey, Vec<u8>>, String> {
        let descriptor = &session.proposal.descriptor;
        if let Some(durable) = self
            .kura
            .read_certified_lane_block_artifact(descriptor.lane_id, descriptor.lane_block_height)
        {
            if durable.proposal != session.proposal
                || durable.prepare_qc != session.prepare_qc
                || durable.commit_qc != session.commit_qc
            {
                return Err(
                    "historical lane certificate conflicts with its durable certified slot"
                        .to_owned(),
                );
            }
            Kura::validate_certified_lane_block_artifact(&durable).map_err(|error| {
                format!("historical durable lane certificate is invalid: {error}")
            })?;
            return Ok(durable.signer_pops);
        }

        let identity = HistoricalRecoveryIdentity::from_proposal(&session.proposal)
            .map_err(|error| error.to_string())?;
        if let Some(outstanding) = self.historical_recovery_requests.get(&identity) {
            let request = &outstanding.request;
            let Some(certificate) = request.certificate.as_ref() else {
                return Err("historical lane recovery request lost its lane certificate".to_owned());
            };
            if certificate.proposal != session.proposal
                || certificate.prepare_qc != session.prepare_qc
                || certificate.commit_qc != session.commit_qc
            {
                return Err(
                    "historical recovery request conflicts with its retained session".to_owned(),
                );
            }
            let candidate =
                CertifiedLaneBlockArtifact::new(session.clone(), request.signer_pops.clone());
            Kura::validate_certified_lane_block_artifact(&candidate).map_err(|error| {
                format!("historical recovery request signer PoPs are invalid: {error}")
            })?;
            return Ok(request.signer_pops.clone());
        }

        // Autonomous READY evidence already carries the complete historical
        // validator-set PoP vector. Project only the union of Prepare/Commit
        // signers so the certified artifact retains an exact, no-extras map.
        let signer_pops = if let Some(availability) =
            session.prepare_qc.payload_availability_qc.as_ref()
        {
            crate::lane_consensus::validate_lane_payload_availability_qc(availability).map_err(
                |error| format!("historical autonomous READY signer PoPs are invalid: {error}"),
            )?;
            if availability.validator_set != session.prepare_qc.validator_set
                || availability.validator_set != session.commit_qc.validator_set
                || availability.validator_set_pops.len() != availability.validator_set.len()
            {
                return Err(
                    "historical autonomous READY PoPs differ from the lane certificate roster"
                        .to_owned(),
                );
            }
            let mut pops = BTreeMap::new();
            for qc in [&session.prepare_qc, &session.commit_qc] {
                for (index, validator) in qc.validator_set.iter().enumerate() {
                    if bitmap_selects(&qc.signers_bitmap, index) {
                        let pop = availability
                            .validator_set_pops
                            .get(index)
                            .ok_or_else(|| {
                                "historical autonomous READY PoP index is missing".to_owned()
                            })?
                            .clone();
                        pops.insert(validator.public_key().clone(), pop);
                    }
                }
            }
            pops
        } else {
            // Ordinary lane certificates do not carry PoPs. This fallback is
            // used only while constructing the first self-contained request;
            // the result is immediately validated and thereafter retained in
            // the request or certified Kura artifact.
            self.pops_for_lane_session(session)
        };
        let candidate = CertifiedLaneBlockArtifact::new(session.clone(), signer_pops.clone());
        Kura::validate_certified_lane_block_artifact(&candidate).map_err(|error| {
            format!("historical lane session lacks exact validated signer PoPs: {error}")
        })?;
        Ok(signer_pops)
    }

    fn schedule_historical_recovery_request(
        &mut self,
        identity: HistoricalRecoveryIdentity,
        session: &CommittedLaneBlockSession,
        retry: HistoricalRecoveryRetry,
    ) -> Result<(), V2LaneWorkError> {
        let descriptor = &session.proposal.descriptor;
        if retry != HistoricalRecoveryRetry::LocalState
            && (!self.lane_route_active(
                descriptor.lane_id,
                descriptor.dataspace_id,
                descriptor.lane_incarnation,
                descriptor.proposal_height,
            ) || !self
                .state
                .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(
                    &session.proposal,
                ))
        {
            return Err(V2LaneWorkError::Persistence(
                "refusing historical recovery request for a stale route, incarnation, or predecessor"
                    .to_owned(),
            ));
        }
        if retry == HistoricalRecoveryRetry::AuthenticatedLanePayload
            && !self.session_has_canonical_anchor(session)
        {
            return Err(V2LaneWorkError::Persistence(
                "refusing historical payload request without its exact committed global anchor"
                    .to_owned(),
            ));
        }
        let (kind, peers) = match retry {
            HistoricalRecoveryRetry::LocalState => {
                self.retire_historical_recovery_request(identity);
                return Ok(());
            }
            HistoricalRecoveryRetry::AuthenticatedBlockSync => {
                let Some(finality) = self
                    .kura
                    .v2_finality_artifact(identity.proposal_height)
                    .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?
                else {
                    // The authenticated global synchronizer owns recovery when
                    // even the immutable proof is absent. Never issue an
                    // unbound body request from State's hash alone.
                    self.retire_historical_recovery_request(identity);
                    return Ok(());
                };
                finality.verify().map_err(|error| {
                    V2LaneWorkError::Persistence(format!(
                        "historical canonical-body finality is invalid: {error}"
                    ))
                })?;
                if finality.height != identity.proposal_height
                    || finality.block_hash != identity.proposal_block_hash
                    || finality.commit_qc.proposal_round.view
                        != session
                            .proposal
                            .payload_block_hint
                            .map_or(u64::MAX, |hint| hint.proposal_view)
                {
                    return Err(V2LaneWorkError::Persistence(
                        "historical canonical-body finality conflicts with the lane anchor"
                            .to_owned(),
                    ));
                }
                let peers = finality
                    .commit_qc
                    .signers
                    .iter()
                    .filter_map(|index| {
                        usize::try_from(*index)
                            .ok()
                            .and_then(|index| finality.height_context.roster.get(index))
                            .map(|validator| validator.validator.clone())
                    })
                    .collect::<Vec<_>>();
                (
                    LaneHistoricalRecoveryKindV1::CanonicalBlock {
                        finality_artifact_hash: HashOf::new(&finality),
                    },
                    peers,
                )
            }
            HistoricalRecoveryRetry::AuthenticatedLanePayload => {
                let Some(availability) = session.prepare_qc.payload_availability_qc.as_ref() else {
                    return Err(V2LaneWorkError::Persistence(
                        "historical autonomous payload wait has no READY certificate".to_owned(),
                    ));
                };
                crate::lane_consensus::validate_lane_payload_availability_qc(availability)
                    .map_err(|error| {
                        V2LaneWorkError::Persistence(format!(
                            "historical autonomous READY certificate is invalid: {error}"
                        ))
                    })?;
                let peers = availability
                    .validator_set
                    .iter()
                    .enumerate()
                    .filter(|(index, _)| bitmap_selects(&availability.signers_bitmap, *index))
                    .map(|(_, peer)| peer.clone())
                    .collect::<Vec<_>>();
                (
                    LaneHistoricalRecoveryKindV1::AutonomousPayload {
                        executable_payload_hash: availability.body.executable_payload_hash,
                        prepare_qc_hash: HashOf::new(&session.prepare_qc),
                        commit_qc_hash: HashOf::new(&session.commit_qc),
                    },
                    peers,
                )
            }
        };
        let signer_pops = self
            .historical_recovery_signer_pops(session)
            .map_err(V2LaneWorkError::Persistence)?;

        let request = LaneHistoricalRecoveryRequestV1 {
            version: LANE_HISTORICAL_RECOVERY_VERSION_V2,
            requester: self.local_peer.clone(),
            certificate: Some(LaneBlockCertificateV1 {
                proposal: session.proposal.clone(),
                prepare_qc: session.prepare_qc.clone(),
                commit_qc: session.commit_qc.clone(),
            }),
            signer_pops,
            kind,
        };
        let request_hash = HashOf::new(&request);
        let message = BlockMessage::LaneHistoricalRecoveryRequest(Box::new(request.clone()));
        if !self.historical_recovery_request_fits_frame(&request) {
            return Err(V2LaneWorkError::Persistence(
                "historical recovery request exceeds the authenticated frame bound".to_owned(),
            ));
        }

        if let Some(existing) = self.historical_recovery_requests.get(&identity) {
            if existing.request != request || existing.request_hash != request_hash {
                self.retire_historical_recovery_request(identity);
            }
        }
        if !self.historical_recovery_requests.contains_key(&identity) {
            if self
                .historical_recovery_requests
                .len()
                .saturating_add(self.native_participant_recovery_requests.len())
                >= self.limits.session_capacity.get()
            {
                return Err(V2LaneWorkError::Persistence(
                    "historical recovery request capacity exhausted".to_owned(),
                ));
            }
            if self
                .native_participant_recovery_request_owners
                .contains_key(&request_hash)
            {
                return Err(V2LaneWorkError::Persistence(
                    "historical recovery request hash aliases a Native participant owner"
                        .to_owned(),
                ));
            }
            if self
                .historical_recovery_request_owners
                .insert(request_hash, identity)
                .is_some()
            {
                return Err(V2LaneWorkError::Persistence(
                    "historical recovery request hash aliases another owner".to_owned(),
                ));
            }
            self.historical_recovery_requests.insert(
                identity,
                OutstandingHistoricalRecoveryRequest {
                    request_hash,
                    request,
                },
            );
        }

        let local_peer = self.local_peer.clone();
        let mut seen = BTreeSet::new();
        for peer in peers
            .into_iter()
            .filter(|peer| peer != &local_peer && seen.insert(peer.clone()))
        {
            if !self.push_effect(V2LaneWorkEffect::PostLaneBlock {
                peer,
                message: message.clone(),
            }) {
                break;
            }
        }
        Ok(())
    }

    /// Return whether an earlier-height lane session or Native participant
    /// frontier still owns local persistence/application recovery.
    pub(crate) fn has_pending_historical_recovery(&self) -> bool {
        !self.historical_recovery_sessions.is_empty()
            || !self.native_participant_recovery_requests.is_empty()
            || match self.pending_native_participant_recovery_markers() {
                Ok(markers) => !markers.is_empty(),
                Err(_) => true,
            }
    }

    /// Return the bounded deterministic stage/stuck-reason snapshot.
    #[cfg(test)]
    pub(crate) fn historical_recovery_waits_snapshot(&self) -> Vec<HistoricalRecoveryWait> {
        self.historical_recovery_diagnostics.snapshot()
    }

    fn persist_historical_recovery_session(
        &self,
        session: &CommittedLaneBlockSession,
    ) -> Result<HistoricalRecoveryPersistence, V2LaneWorkError> {
        let pops = self
            .historical_recovery_signer_pops(session)
            .map_err(V2LaneWorkError::Persistence)?;
        let candidate = CertifiedLaneBlockArtifact::new(session.clone(), pops.clone());
        Kura::validate_certified_lane_block_artifact(&candidate).map_err(|message| {
            V2LaneWorkError::Persistence(format!(
                "historical lane certificate is invalid: {message}"
            ))
        })?;
        if let Some(reason) = self.historical_proposal_anchor_wait(&session.proposal)? {
            return Ok(HistoricalRecoveryPersistence::Waiting(reason));
        }

        let autonomous_payload = session.prepare_qc.payload_availability_qc.is_some();
        let (recovered_payload, autonomous_epoch) = if autonomous_payload {
            let proposal_height = session.proposal.descriptor.proposal_height;
            let expected_epoch = if proposal_height == self.context.height {
                self.context.epoch
            } else {
                let world = self.state.world_view();
                crate::sumeragi::epoch_for_height_from_world(&world, proposal_height)
            };
            let recovered = match self.kura.recover_autonomous_lane_block_payload(
                &session.proposal,
                self.native_chain_id_hash(),
                expected_epoch,
            ) {
                Ok(recovered) => Ok(recovered),
                Err(LaneBlockPayloadAvailability::MissingLaneArtifact) => {
                    let (anchored_payload, ordinary_anchor) = self
                        .historical_autonomous_payload_from_anchor(
                            &session.proposal,
                            expected_epoch,
                        )?;
                    let Some(payload) = anchored_payload else {
                        if ordinary_anchor {
                            // A READY-bearing session may be globally carried
                            // through ordinary ownership. In that shape the
                            // canonical block authenticates the proposal but
                            // not the independently signed executable bytes,
                            // so only an authenticated lane-payload source can
                            // fill the durable sidecar.
                            return Ok(HistoricalRecoveryPersistence::Waiting(
                                HistoricalRecoveryWaitReason::AutonomousPayloadPending,
                            ));
                        }
                        return Err(V2LaneWorkError::Persistence(
                            "historical autonomous certificate is absent from its canonical carrier"
                                .to_owned(),
                        ));
                    };
                    // A pure autonomous carrier authenticates the complete
                    // envelope. A crash before publishing its lane sidecar is
                    // therefore repaired locally from those exact bytes.
                    self.kura
                        .persist_lane_executable_payload(
                            &payload,
                            self.native_chain_id_hash(),
                            expected_epoch,
                        )
                        .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
                    self.kura.recover_autonomous_lane_block_payload(
                        &session.proposal,
                        self.native_chain_id_hash(),
                        expected_epoch,
                    )
                }
                Err(availability) => Err(availability),
            };
            (recovered, Some(expected_epoch))
        } else {
            (
                self.kura.recover_lane_block_payload(&session.proposal),
                None,
            )
        };
        let recovered_payload = match recovered_payload {
            Ok(recovered) => recovered,
            Err(LaneBlockPayloadAvailability::MissingProposalBlock) => {
                return Ok(HistoricalRecoveryPersistence::Waiting(
                    HistoricalRecoveryWaitReason::CanonicalBlockPending,
                ));
            }
            Err(availability) => {
                return Err(V2LaneWorkError::Persistence(format!(
                    "historical lane certificate is anchored to invalid payload: {availability:?}"
                )));
            }
        };
        // Ordinary recovery repairs a missing ownership sidecar directly from
        // the already-authenticated canonical block body. Recheck the strict
        // sidecar/State projection only after that repair; checking it first
        // was the former payload-recovery-to-application deadlock.
        if !self.session_has_canonical_anchor(session)
            || !self.proposal_anchor_is_committed_in_state(&session.proposal)
        {
            return Err(V2LaneWorkError::Persistence(
                "historical lane payload differs from its committed canonical anchor".to_owned(),
            ));
        }
        if let Some(expected_epoch) = autonomous_epoch {
            self.kura
                .persist_lane_block_execution_input(&recovered_payload)
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            self.kura
                .persist_lane_payload_availability_certificate(
                    session.proposal.descriptor.lane_id,
                    session.proposal.descriptor.lane_block_height,
                    DurableLanePayloadAvailabilityCertificateV1 {
                        certificate: session.prepare_qc.clone(),
                    },
                    self.native_chain_id_hash(),
                    expected_epoch,
                )
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        }
        let descriptor = &session.proposal.descriptor;
        let durable = self
            .kura
            .read_certified_lane_block_artifact(descriptor.lane_id, descriptor.lane_block_height);
        let durable_proposal = match durable {
            Some(durable) if durable.proposal == session.proposal => durable.proposal,
            Some(_) | None => {
                self.state
                    .persist_committed_lane_block_session_lifecycle_bound(session, &pops)
                    .map_err(V2LaneWorkError::Persistence)?;
                session.proposal.clone()
            }
        };

        if autonomous_payload {
            return Ok(HistoricalRecoveryPersistence::Complete);
        }
        if self
            .state
            .certified_lane_block_session_is_applied_or_snapshot_anchored_cached(session)
        {
            return Ok(HistoricalRecoveryPersistence::Complete);
        }
        if !self
            .state
            .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(
                &durable_proposal,
            )
        {
            return Ok(HistoricalRecoveryPersistence::Waiting(
                HistoricalRecoveryWaitReason::PredecessorApplicationPending,
            ));
        }
        let receipt_persisted = self
            .kura
            .persist_lane_block_application_receipt_if_ready(&durable_proposal)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        if !receipt_persisted {
            let reason = match self.kura.lane_block_payload_availability(&durable_proposal) {
                LaneBlockPayloadAvailability::MissingProposalBlock => {
                    HistoricalRecoveryWaitReason::CanonicalBlockPending
                }
                LaneBlockPayloadAvailability::Available => {
                    HistoricalRecoveryWaitReason::CanonicalResultsPending
                }
                availability => {
                    return Err(V2LaneWorkError::Persistence(format!(
                        "historical lane application evidence is immutably invalid: {availability:?}"
                    )));
                }
            };
            return Ok(HistoricalRecoveryPersistence::Waiting(reason));
        }
        Ok(HistoricalRecoveryPersistence::Complete)
    }

    fn historical_autonomous_payload_from_anchor(
        &self,
        proposal: &LaneBlockProposalV1,
        expected_epoch: u64,
    ) -> Result<(Option<LaneExecutablePayloadV1>, bool), V2LaneWorkError> {
        let hint = proposal.payload_block_hint.ok_or_else(|| {
            V2LaneWorkError::Persistence(
                "historical autonomous certificate has no canonical proposal hint".to_owned(),
            )
        })?;
        let height = usize::try_from(hint.proposal_height)
            .ok()
            .and_then(NonZeroUsize::new)
            .ok_or_else(|| {
                V2LaneWorkError::Persistence(
                    "historical autonomous proposal height is not representable".to_owned(),
                )
            })?;
        let block = self.kura.get_block(height).ok_or_else(|| {
            V2LaneWorkError::Persistence(
                "historical autonomous carrier disappeared after anchor validation".to_owned(),
            )
        })?;
        let bundle = block.execution_context().ok_or_else(|| {
            V2LaneWorkError::Persistence(
                "historical autonomous certificate names a carrier without execution context"
                    .to_owned(),
            )
        })?;
        if bundle
            .lane_payload_ownerships
            .len()
            .saturating_add(bundle.autonomous_lane_payloads.len())
            > self.limits.session_capacity.get()
        {
            return Err(V2LaneWorkError::Persistence(
                "historical autonomous carrier exceeds the frozen lane-session bound".to_owned(),
            ));
        }

        let chain_id_hash = self.native_chain_id_hash();
        let ordinary_anchor = bundle.lane_payload_ownerships.iter().any(|ownership| {
            proposal_from_ownership(ownership, block.hash()).as_ref() == Some(proposal)
        });
        let mut exact = None;
        for envelope in &bundle.autonomous_lane_payloads {
            let payload =
                decode_autonomous_lane_payload_envelope(envelope, chain_id_hash, expected_epoch)
                    .and_then(|payload| {
                        payload.attach_global_hint_exact(hint, chain_id_hash, expected_epoch)
                    })
                    .map_err(|error| {
                        V2LaneWorkError::Persistence(format!(
                            "historical autonomous carrier contains an invalid payload: {error}"
                        ))
                    })?;
            if payload.origin_proposal != *proposal {
                continue;
            }
            if exact.replace(payload).is_some() {
                return Err(V2LaneWorkError::Persistence(
                    "historical autonomous carrier contains duplicate exact payloads".to_owned(),
                ));
            }
        }
        Ok((exact, ordinary_anchor))
    }

    /// Retire losing certified merge sidecars once another carrier is durably
    /// finalized at this height.
    pub(crate) fn prune_finalized_merge_sidecars(&mut self) -> Result<(), V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        #[cfg(test)]
        if let Some(pause) = &self.persistence_pause {
            let _ = pause.entered.send(());
            pause.release.wait();
        }
        #[cfg(test)]
        if let Some(reason) = self.persistence_failure.take() {
            return Err(V2LaneWorkError::Persistence(reason));
        }
        self.merge_entries.clear();
        self.merge_claims.clear();
        self.purge_queued_merge_broadcasts();
        self.merge_sidecars
            .retain_pending_blocks(&BTreeSet::new(), self.context.height)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        self.kura
            .prune_finalized_pending_certified_merge_entries(self.context.height)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        operation.complete();
        Ok(())
    }

    fn historical_proposal_anchor_wait(
        &self,
        proposal: &LaneBlockProposalV1,
    ) -> Result<Option<HistoricalRecoveryWaitReason>, V2LaneWorkError> {
        let Some(hint) = proposal.payload_block_hint else {
            return Err(V2LaneWorkError::Persistence(
                "historical lane certificate has no canonical proposal hint".to_owned(),
            ));
        };
        if hint.proposal_height != proposal.descriptor.proposal_height || hint.proposal_height == 0
        {
            return Err(V2LaneWorkError::Persistence(
                "historical lane certificate has an invalid canonical proposal height".to_owned(),
            ));
        }
        let Some(height) = usize::try_from(hint.proposal_height)
            .ok()
            .and_then(NonZeroUsize::new)
        else {
            return Err(V2LaneWorkError::Persistence(
                "historical lane certificate proposal height is not representable".to_owned(),
            ));
        };

        let committed_height = u64::try_from(self.state.committed_height()).map_err(|_| {
            V2LaneWorkError::Persistence(
                "committed State height is not representable during historical recovery".to_owned(),
            )
        })?;
        let Some(committed_hash) = self
            .state
            .committed_block_hash_at_height(hint.proposal_height)
        else {
            if committed_height < hint.proposal_height {
                return Ok(Some(HistoricalRecoveryWaitReason::StateCommitPending));
            }
            return Err(V2LaneWorkError::Persistence(
                "committed State is missing a historical block identity".to_owned(),
            ));
        };
        if committed_hash != hint.proposal_block_hash {
            return Err(V2LaneWorkError::Persistence(
                "historical lane certificate conflicts with committed State".to_owned(),
            ));
        }

        match self.kura.get_durable_block_hash(height) {
            Some(hash) if hash == hint.proposal_block_hash => {}
            Some(_) => {
                return Err(V2LaneWorkError::Persistence(
                    "historical lane certificate conflicts with Kura's canonical hash journal"
                        .to_owned(),
                ));
            }
            None => {
                return Ok(Some(HistoricalRecoveryWaitReason::CanonicalBlockPending));
            }
        }
        let Some(block) = self.kura.get_block(height) else {
            return Ok(Some(HistoricalRecoveryWaitReason::CanonicalBlockPending));
        };
        if block.header().height().get() != hint.proposal_height
            || block.hash() != hint.proposal_block_hash
            || block.header().view_change_index() != hint.proposal_view
        {
            return Err(V2LaneWorkError::Persistence(
                "historical lane certificate conflicts with the canonical Kura block body"
                    .to_owned(),
            ));
        }
        Ok(None)
    }

    fn historical_block_anchors_proposal(
        &self,
        block: &SignedBlock,
        proposal: &LaneBlockProposalV1,
    ) -> bool {
        let Some(hint) = proposal.payload_block_hint else {
            return false;
        };
        if hint.proposal_height != proposal.descriptor.proposal_height
            || block.header().height().get() != hint.proposal_height
            || block.header().view_change_index() != hint.proposal_view
            || block.hash() != hint.proposal_block_hash
        {
            return false;
        }
        let Some(bundle) = block.execution_context() else {
            return false;
        };
        if bundle
            .lane_payload_ownerships
            .len()
            .saturating_add(bundle.autonomous_lane_payloads.len())
            > self.limits.session_capacity.get()
        {
            return false;
        }
        let mut matches = bundle
            .lane_payload_ownerships
            .iter()
            .filter(|ownership| {
                proposal_from_ownership(ownership, block.hash()).as_ref() == Some(proposal)
            })
            .count();
        let expected_epoch = {
            let world = self.state.world_view();
            crate::sumeragi::epoch_for_height_from_world(&world, hint.proposal_height)
        };
        for envelope in &bundle.autonomous_lane_payloads {
            let Ok(payload) = decode_autonomous_lane_payload_envelope(
                envelope,
                self.native_chain_id_hash(),
                expected_epoch,
            )
            .and_then(|payload| {
                payload.attach_global_hint_exact(hint, self.native_chain_id_hash(), expected_epoch)
            }) else {
                return false;
            };
            if payload.origin_proposal == *proposal {
                matches = matches.saturating_add(1);
            }
        }
        matches == 1
    }

    fn proposal_anchor_is_committed_in_state(&self, proposal: &LaneBlockProposalV1) -> bool {
        let Some(hint) = proposal.payload_block_hint else {
            return false;
        };
        let Some(height) = usize::try_from(hint.proposal_height)
            .ok()
            .and_then(NonZeroUsize::new)
        else {
            return false;
        };
        let Some(block) = self.kura.get_block(height) else {
            return false;
        };
        if hint.proposal_height != proposal.descriptor.proposal_height
            || block.hash() != hint.proposal_block_hash
            || block.header().view_change_index() != hint.proposal_view
            || self
                .state
                .committed_block_hash_at_height(hint.proposal_height)
                != Some(hint.proposal_block_hash)
        {
            return false;
        }
        if let Some(anchor) = self.canonical_anchor_for_proposal(proposal) {
            return hint.proposal_block_hash == anchor.proposal_block_hash
                && hint.proposal_view == anchor.ownership.proposal_view
                && block.execution_context().is_some_and(|bundle| {
                    bundle
                        .lane_payload_ownerships
                        .iter()
                        .any(|ownership| ownership == &anchor.ownership)
                });
        }
        self.canonical_autonomous_anchor_matches_kura(proposal)
    }

    /// Consume the exact fair-ingress carrier while accepting a lane message.
    ///
    /// Missing, altered, or route-inconsistent ownership fails closed at this
    /// seam; callers cannot reconstruct it from public sender identities.
    pub(crate) fn accept_lane_message_with_ingress_ownership(
        &mut self,
        mut inbound: InboundBlockMessage,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        let Some(ingress_ownership) = inbound.take_ingress_ownership() else {
            return V2LaneIngressOutcome::Rejected;
        };
        self.accept_lane_message_owned(inbound, Some(ingress_ownership), active_view)
    }

    /// Unit-test compatibility seam for constructing lane protocol fixtures
    /// without the outer fair queue. Production calls the ownership-requiring
    /// method above.
    #[cfg(test)]
    pub(crate) fn accept_lane_message(
        &mut self,
        mut inbound: InboundBlockMessage,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        let ingress_ownership = inbound.take_ingress_ownership();
        self.accept_lane_message_owned(inbound, ingress_ownership, active_view)
    }

    fn accept_lane_message_owned(
        &mut self,
        inbound: InboundBlockMessage,
        ingress_ownership: Option<FairV2IngressOwnershipEvidence>,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        let output_guard = Arc::clone(&self.output_guard);
        let Some(_permit) = output_guard.acquire() else {
            return V2LaneIngressOutcome::Rejected;
        };
        let (message, sender, reply_routes) = inbound.into_message_sender_and_reply_routes();
        if ingress_ownership.as_ref().is_some_and(|ownership| {
            !ownership.validate_exact()
                || !ownership.matches_message(&message)
                || !ownership.matches_semantic_origin(sender.as_ref())
                || !ownership.matches_reply_routes(reply_routes.as_ref())
        }) {
            return V2LaneIngressOutcome::Rejected;
        }
        if self.decision_pending()
            && let BlockMessage::LaneBlockProposal(proposal) = &message
            && proposal.descriptor.proposal_height >= self.context.height
            && !self.proposal_is_bound_to_decided_carrier(proposal)
        {
            return V2LaneIngressOutcome::Rejected;
        }
        if let BlockMessage::LaneBlockProposal(proposal) = &message
            && let Some(outcome) = self.serve_durable_lane_certificate(
                proposal,
                sender.as_ref(),
                reply_routes,
                ingress_ownership,
            )
        {
            return outcome;
        }
        if self.decision_pending() && !self.lane_message_is_allowed_after_decision(&message) {
            return V2LaneIngressOutcome::Rejected;
        }
        let outcome = match message {
            BlockMessage::LaneBlockProposal(proposal) => {
                self.insert_lane_proposal(proposal, sender.as_ref(), false, active_view)
            }
            BlockMessage::LaneExecutablePayload(payload) => {
                self.insert_autonomous_lane_payload(payload, sender.as_ref(), active_view)
            }
            BlockMessage::LaneBlockNewViewVote(vote) => {
                self.insert_autonomous_new_view_vote(vote, sender.as_ref(), active_view)
            }
            BlockMessage::LaneBlockNewViewCertificate(certificate) => self
                .insert_autonomous_new_view_certificate(certificate, sender.as_ref(), active_view),
            BlockMessage::LaneBlockVote(vote) => {
                self.insert_lane_vote(vote, sender.as_ref(), active_view)
            }
            BlockMessage::LaneBlockQc(qc) => self.insert_lane_qc(qc, active_view),
            BlockMessage::LaneBlockCertificate(certificate) => {
                self.insert_lane_certificate(*certificate, active_view)
            }
            BlockMessage::LaneHistoricalRecoveryRequest(request) => {
                self.serve_historical_recovery_request(*request, sender.as_ref())
            }
            BlockMessage::LaneHistoricalRecoveryResponse(response) => {
                self.accept_historical_recovery_response(*response, sender.as_ref())
            }
            _ => V2LaneIngressOutcome::Rejected,
        };
        if outcome != V2LaneIngressOutcome::Rejected {
            self.drive_lane_sessions();
        }
        outcome
    }

    fn autonomous_origin_matches_context(
        &self,
        proposal: &LaneBlockProposalV1,
        active_view: wire::View,
    ) -> bool {
        let descriptor = &proposal.descriptor;
        let Some(hint) = proposal.payload_block_hint else {
            return false;
        };
        validate_lane_block_proposal(proposal).is_ok()
            && descriptor.proposal_height == self.context.height
            && descriptor.lane_block_view == 0
            && hint.proposal_height == descriptor.proposal_height
            && hint.proposal_view <= active_view
            && self
                .globally_locked_body
                .is_none_or(|locked| hint.proposal_block_hash == locked.subject.block_hash)
            && self.qc_mode_tag_matches_context(
                &descriptor.qc_mode_tag,
                descriptor.lane_id,
                descriptor.dataspace_id,
            )
            && self.lane_route_active(
                descriptor.lane_id,
                descriptor.dataspace_id,
                descriptor.lane_incarnation,
                descriptor.proposal_height,
            )
            && self.expected_lane_validators(descriptor.lane_id, descriptor.proposal_height)
                == Some(descriptor.validator_set.clone())
            && self
                .state
                .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(proposal)
    }

    fn unanchored_autonomous_origin_matches_context(&self, proposal: &LaneBlockProposalV1) -> bool {
        let descriptor = &proposal.descriptor;
        proposal.payload_block_hint.is_none()
            && validate_lane_block_proposal(proposal).is_ok()
            && descriptor.proposal_height == self.context.height
            && descriptor.lane_block_view == 0
            && self.qc_mode_tag_matches_context(
                &descriptor.qc_mode_tag,
                descriptor.lane_id,
                descriptor.dataspace_id,
            )
            && self.lane_route_active(
                descriptor.lane_id,
                descriptor.dataspace_id,
                descriptor.lane_incarnation,
                descriptor.proposal_height,
            )
            && self.expected_lane_validators(descriptor.lane_id, descriptor.proposal_height)
                == Some(descriptor.validator_set.clone())
            && self
                .state
                .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(proposal)
    }

    fn autonomous_reservation_keys_are_canonical(
        &self,
        proposal: &LaneBlockProposalV1,
        author: &PeerId,
        reservation_keys: &[crate::queue::LaneQueueReservationKeyV2],
    ) -> bool {
        let Ok((reservation_owner_hash, proposal_identity_hash)) =
            autonomous_lane_reservation_identity_hashes_for_proposal(
                self.native_chain_id_hash(),
                self.context.id(),
                self.context.epoch,
                proposal,
                author,
            )
        else {
            return false;
        };
        !reservation_keys.is_empty()
            && reservation_keys.iter().all(|key| {
                key.reservation_owner_hash == reservation_owner_hash
                    && key.proposal_identity_hash == proposal_identity_hash
            })
    }

    fn durable_autonomous_payload_for_proposal(
        &self,
        proposal: &LaneBlockProposalV1,
    ) -> Option<LaneExecutablePayloadV1> {
        let key = AutonomousLanePayloadKey::from(proposal);
        self.autonomous_payloads
            .get(&key)
            .filter(|payload| payload.origin_proposal == *proposal)
            .cloned()
            .or_else(|| {
                self.kura
                    .read_autonomous_lane_block_artifact(
                        proposal.descriptor.lane_id,
                        proposal.descriptor.lane_block_height,
                        self.native_chain_id_hash(),
                        self.context.epoch,
                    )
                    .map(|artifact| artifact.executable_payload)
                    .filter(|payload| payload.origin_proposal == *proposal)
            })
    }

    fn latest_durable_autonomous_new_view_certificate(
        artifact: &AutonomousLaneBlockArtifact,
        current_view: u64,
    ) -> Option<&DurableLaneBlockNewViewCertificateV1> {
        artifact
            .new_view_certificates
            .last()
            .or_else(|| {
                artifact
                    .view_checkpoint
                    .as_ref()
                    .map(|checkpoint| &checkpoint.certificate)
            })
            .filter(|durable| durable.certificate.body.target_view == current_view)
    }

    /// Rebind Kura's authoritative synthetic cursor after the exact hinted
    /// payload crossed its protected-carrier durability boundary.
    ///
    /// Constructor hydration cannot trust a hinted payload until the reducer
    /// supplies the matching lock. This helper therefore runs only after
    /// `persist_and_authorize_autonomous_payload`, seeds the latest durable
    /// certificate for immediate retransmission, and never changes the
    /// immutable origin proposal used by READY/Prepare/Commit.
    fn restore_autonomous_new_view_state(
        &mut self,
        payload: &LaneExecutablePayloadV1,
        active_view: wire::View,
        restored_at: Instant,
    ) -> Result<(), String> {
        if !self.autonomous_origin_matches_context(&payload.origin_proposal, active_view) {
            return Err(
                "durable autonomous NewView restore requires the exact protected carrier"
                    .to_owned(),
            );
        }
        let descriptor = &payload.origin_proposal.descriptor;
        let artifact = self
            .kura
            .read_autonomous_lane_block_artifact(
                descriptor.lane_id,
                descriptor.lane_block_height,
                self.native_chain_id_hash(),
                self.context.epoch,
            )
            .ok_or_else(|| {
                "failed to recover durable autonomous payload for NewView restore".to_owned()
            })?;
        let (durable_payload, current) = self
            .kura
            .current_autonomous_lane_payload(
                descriptor.lane_id,
                descriptor.lane_block_height,
                self.native_chain_id_hash(),
                self.context.epoch,
            )
            .ok_or_else(|| {
                "failed to recover durable autonomous NewView cursor after payload persistence"
                    .to_owned()
            })?;
        if durable_payload != *payload || artifact.executable_payload != *payload {
            return Err(
                "durable autonomous NewView restore recovered different executable bytes"
                    .to_owned(),
            );
        }
        let key = AutonomousLanePayloadKey::from(&payload.origin_proposal);
        if let Some(existing) = self.autonomous_payloads.get(&key) {
            if existing != payload {
                return Err(
                    "durable autonomous NewView restore conflicts with the retained payload"
                        .to_owned(),
                );
            }
        } else {
            if self
                .pending_autonomous_anchor_payloads
                .len()
                .saturating_add(self.autonomous_payloads.len())
                >= self.limits.session_capacity.get()
            {
                return Err(
                    "durable autonomous NewView restore exceeds the payload capacity".to_owned(),
                );
            }
            self.autonomous_payloads.insert(key, payload.clone());
            self.autonomous_payload_order.push_back(key);
        }

        let current_view = current.descriptor.lane_block_view;
        let mut next_certificates = self.autonomous_new_view_certificates.clone();
        if current_view == payload.origin_proposal.descriptor.lane_block_view {
            if Self::latest_durable_autonomous_new_view_certificate(&artifact, current_view)
                .is_some()
            {
                return Err(
                    "origin autonomous cursor unexpectedly retains a NewView certificate"
                        .to_owned(),
                );
            }
        } else {
            let durable =
                Self::latest_durable_autonomous_new_view_certificate(&artifact, current_view)
                    .ok_or_else(|| {
                        "advanced autonomous cursor lacks its latest durable NewView certificate"
                            .to_owned()
                    })?;
            next_certificates
                .insert(durable.certificate.clone(), &durable.signer_pops)
                .map_err(|error| {
                    format!(
                        "latest durable autonomous NewView certificate conflicts with live cache: {error}"
                    )
                })?;
        }

        self.autonomous_new_view_certificates = next_certificates;
        self.autonomous_payload_views.insert(key, current_view);
        if self.voting_enabled
            && self.local_peer.public_key().try_algorithm().ok() == Some(Algorithm::BlsNormal)
            && payload
                .origin_proposal
                .descriptor
                .validator_set
                .contains(&self.local_peer)
        {
            match self.autonomous_new_view_started_at.entry(key) {
                std::collections::btree_map::Entry::Occupied(mut entry)
                    if entry.get().0 != current_view =>
                {
                    entry.insert((current_view, restored_at));
                }
                std::collections::btree_map::Entry::Occupied(_) => {}
                std::collections::btree_map::Entry::Vacant(entry) => {
                    entry.insert((current_view, restored_at));
                }
            }
        } else {
            self.autonomous_new_view_started_at.remove(&key);
        }
        Ok(())
    }

    fn autonomous_payload_is_expected_for(&self, proposal: &LaneBlockProposalV1) -> bool {
        self.durable_autonomous_payload_for_proposal(proposal)
            .is_some()
    }

    /// Cross the payload and execution-input durability barriers before
    /// authorizing any READY signature for this exact proposal.
    fn persist_and_authorize_autonomous_payload(
        &mut self,
        payload: &LaneExecutablePayloadV1,
        proposal: &LaneBlockProposalV1,
    ) -> Result<(), String> {
        if payload.origin_proposal != *proposal || !self.proposal_body_available(proposal) {
            return Err(
                "autonomous payload does not match an exact protected global carrier".to_owned(),
            );
        }
        let chain_id_hash = self.native_chain_id_hash();
        let epoch = self.context.epoch;
        self.kura
            .persist_lane_executable_payload(payload, chain_id_hash, epoch)
            .map_err(|error| format!("failed to persist autonomous executable payload: {error}"))?;
        let recovered = self
            .kura
            .recover_autonomous_lane_block_payload(proposal, chain_id_hash, epoch)
            .map_err(|error| format!("failed to recover durable autonomous payload: {error:?}"))?;
        self.kura
            .persist_lane_block_execution_input(&recovered)
            .map_err(|error| format!("failed to persist autonomous execution input: {error}"))?;
        let availability = lane_payload_availability_body(payload, proposal, chain_id_hash, epoch)
            .map_err(|error| format!("failed to derive autonomous READY body: {error}"))?;
        self.lane_sessions
            .authorize_payload_availability(proposal, availability)
            .map_err(|error| format!("failed to authorize autonomous READY body: {error}"))
    }

    fn persist_autonomous_prepare_availability(
        &self,
        proposal: &LaneBlockProposalV1,
        prepare_qc: &LaneBlockQcV1,
    ) -> Result<(), String> {
        if prepare_qc.payload_availability_qc.is_none() {
            return Ok(());
        }
        let payload = self
            .durable_autonomous_payload_for_proposal(proposal)
            .ok_or_else(|| {
                "autonomous PrepareQC has no exact durable executable payload".to_owned()
            })?;
        if payload.origin_proposal != *proposal {
            return Err(
                "autonomous availability certificate must retain the immutable origin proposal"
                    .to_owned(),
            );
        }
        self.kura
            .persist_lane_payload_availability_certificate(
                proposal.descriptor.lane_id,
                proposal.descriptor.lane_block_height,
                DurableLanePayloadAvailabilityCertificateV1 {
                    certificate: prepare_qc.clone(),
                },
                self.native_chain_id_hash(),
                self.context.epoch,
            )
            .map_err(|error| {
                format!("failed to persist autonomous availability certificate: {error}")
            })
    }

    fn insert_autonomous_lane_payload(
        &mut self,
        payload: LaneExecutablePayloadV1,
        sender: Option<&PeerId>,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        if sender != Some(&payload.producer)
            || payload
                .validate(self.native_chain_id_hash(), self.context.epoch)
                .is_err()
            || self.expected_lane_author(&payload.origin_proposal) != Some(&payload.producer)
            || !self.autonomous_reservation_keys_are_canonical(
                &payload.origin_proposal,
                &payload.producer,
                &payload.reservation_keys,
            )
        {
            return V2LaneIngressOutcome::Rejected;
        }

        let key = AutonomousLanePayloadKey::from(&payload.origin_proposal);
        if payload.origin_proposal.payload_block_hint.is_none() {
            if self.globally_locked_body.is_some()
                || self.decision_pending()
                || !self.unanchored_autonomous_origin_matches_context(&payload.origin_proposal)
                || self
                    .autonomous_payloads
                    .get(&key)
                    .is_some_and(|existing| existing != &payload)
            {
                return V2LaneIngressOutcome::Rejected;
            }
            if let Some(existing) = self.pending_autonomous_anchor_payloads.get(&key) {
                return if existing == &payload {
                    V2LaneIngressOutcome::Duplicate
                } else {
                    V2LaneIngressOutcome::Rejected
                };
            }
            if self
                .pending_autonomous_anchor_payloads
                .len()
                .saturating_add(self.autonomous_payloads.len())
                >= self.limits.session_capacity.get()
            {
                return V2LaneIngressOutcome::Rejected;
            }
            self.pending_autonomous_anchor_payloads.insert(key, payload);
            return V2LaneIngressOutcome::Inserted;
        }
        if !self.autonomous_origin_matches_context(&payload.origin_proposal, active_view) {
            return V2LaneIngressOutcome::Rejected;
        }
        let outcome = if let Some(existing) = self.autonomous_payloads.get(&key) {
            if existing != &payload {
                return V2LaneIngressOutcome::Rejected;
            }
            V2LaneIngressOutcome::Duplicate
        } else {
            if self
                .pending_autonomous_anchor_payloads
                .len()
                .saturating_add(self.autonomous_payloads.len())
                >= self.limits.session_capacity.get()
            {
                return V2LaneIngressOutcome::Rejected;
            }
            self.autonomous_payload_views
                .insert(key, payload.origin_proposal.descriptor.lane_block_view);
            self.autonomous_payloads.insert(key, payload.clone());
            self.autonomous_payload_order.push_back(key);
            V2LaneIngressOutcome::Inserted
        };
        if self.proposal_body_available(&payload.origin_proposal) {
            let durable = self
                .persist_and_authorize_autonomous_payload(&payload, &payload.origin_proposal)
                .and_then(|()| {
                    self.restore_autonomous_new_view_state(&payload, active_view, Instant::now())
                });
            if let Err(error) = durable {
                iroha_logger::error!(
                    %error,
                    lane = %payload.origin_proposal.descriptor.lane_id.as_u32(),
                    lane_block_height = payload.origin_proposal.descriptor.lane_block_height,
                    "autonomous payload durability failed; closing consensus output"
                );
                self.output_guard.close_admission_for_restart();
                return V2LaneIngressOutcome::Rejected;
            }
        }
        outcome
    }

    fn autonomous_new_view_transition_is_current(
        &self,
        body: &crate::lane_consensus::LaneBlockNewViewBodyV1,
        active_view: wire::View,
    ) -> bool {
        if body.chain_id_hash != self.native_chain_id_hash()
            || body.epoch != self.context.epoch
            || body.proposal_height != self.context.height
            || !self.qc_mode_tag_matches_context(&body.qc_mode_tag, body.lane_id, body.dataspace_id)
            || !self.lane_route_active(
                body.lane_id,
                body.dataspace_id,
                body.lane_incarnation,
                body.proposal_height,
            )
        {
            return false;
        }
        let key = AutonomousLanePayloadKey::from(body);
        let Some(payload) = self.autonomous_payloads.get(&key) else {
            return false;
        };
        if !self.autonomous_origin_matches_context(&payload.origin_proposal, active_view)
            || !self
                .lane_sessions
                .proposals_without_commit_qc()
                .iter()
                .any(|proposal| proposal == &payload.origin_proposal)
            || payload.payload_hash != body.executable_payload_hash
            || self.autonomous_payload_views.get(&key) != Some(&body.from_view)
            || payload
                .origin_proposal
                .descriptor
                .validator_set_hash_version
                != body.validator_set_hash_version
            || payload.origin_proposal.descriptor.validator_set_hash != body.validator_set_hash
            || payload.origin_proposal.descriptor.validator_count != body.validator_count
            || payload.origin_proposal.descriptor.min_quorum != body.min_quorum
        {
            return false;
        }
        let Some((durable_payload, source)) = self.kura.current_autonomous_lane_payload(
            body.lane_id,
            body.lane_block_height,
            self.native_chain_id_hash(),
            self.context.epoch,
        ) else {
            return false;
        };
        if durable_payload != *payload || source.descriptor.lane_block_view != body.from_view {
            return false;
        }
        crate::lane_consensus::LaneBlockNewViewBodyV1::for_transition(
            &source,
            &durable_payload,
            body.target_view,
            self.native_chain_id_hash(),
            self.context.epoch,
        )
        .is_ok_and(|expected| expected == *body)
    }

    fn pops_for_autonomous_new_view(
        &self,
        certificate: &crate::lane_consensus::LaneBlockNewViewCertificateV1,
    ) -> Option<BTreeMap<PublicKey, Vec<u8>>> {
        let aligned_pops = match pinned_autoscale_validator_pops_for_set(
            &self.state,
            certificate.body.lane_id,
            &certificate.validator_set,
        )? {
            Some(pops) => pops,
            None => {
                let world = self.state.world_view();
                certificate
                    .validator_set
                    .iter()
                    .map(|peer| {
                        crate::state::live_consensus_key_pop_for_peer(
                            &world,
                            peer,
                            certificate.body.proposal_height,
                        )
                    })
                    .collect::<Option<Vec<_>>>()?
            }
        };
        if aligned_pops.len() != certificate.validator_set.len() {
            return None;
        }
        Some(
            certificate
                .validator_set
                .iter()
                .zip(aligned_pops)
                .enumerate()
                .filter(|(index, _)| {
                    certificate
                        .signers_bitmap
                        .get(index / 8)
                        .is_some_and(|byte| byte & (1_u8 << (index % 8)) != 0)
                })
                .map(|(_, (peer, pop))| (peer.public_key().clone(), pop))
                .collect(),
        )
    }

    fn persist_and_install_autonomous_new_view_certificate(
        &mut self,
        certificate: crate::lane_consensus::LaneBlockNewViewCertificateV1,
        signer_pops: BTreeMap<PublicKey, Vec<u8>>,
        next_certificates: LaneBlockNewViewCertificateCache,
        active_view: wire::View,
        installed_at: Instant,
    ) -> Result<(), V2LaneWorkError> {
        if !self.autonomous_new_view_transition_is_current(&certificate.body, active_view)
            || crate::lane_consensus::validate_lane_block_new_view_certificate(
                &certificate,
                &signer_pops,
            )
            .is_err()
        {
            return Err(V2LaneWorkError::InvalidContext(
                "autonomous NewView certificate no longer extends the exact current cursor"
                    .to_owned(),
            ));
        }
        let key = AutonomousLanePayloadKey::from(&certificate.body);
        let Some(expected_payload) = self.autonomous_payloads.get(&key).cloned() else {
            return Err(V2LaneWorkError::InvalidContext(
                "autonomous NewView certificate has no retained executable payload".to_owned(),
            ));
        };
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        let (durable_payload, durable_source) = self
            .kura
            .current_autonomous_lane_payload(
                certificate.body.lane_id,
                certificate.body.lane_block_height,
                self.native_chain_id_hash(),
                self.context.epoch,
            )
            .ok_or_else(|| {
                V2LaneWorkError::Persistence(
                    "missing or invalid durable autonomous payload at NewView installation"
                        .to_owned(),
                )
            })?;
        if durable_payload != expected_payload
            || durable_source.descriptor.lane_block_view != certificate.body.from_view
        {
            return Err(V2LaneWorkError::Persistence(
                "durable autonomous NewView cursor differs from the validated live transition"
                    .to_owned(),
            ));
        }
        let expected_target = crate::lane_consensus::retarget_lane_block_proposal_view(
            &durable_source,
            certificate.body.target_view,
        )
        .map_err(|error| {
            V2LaneWorkError::Persistence(format!(
                "failed to derive durable autonomous NewView target: {error}"
            ))
        })?;
        let target = self
            .kura
            .persist_lane_new_view_certificate(
                certificate.body.lane_id,
                certificate.body.lane_block_height,
                DurableLaneBlockNewViewCertificateV1 {
                    certificate: certificate.clone(),
                    signer_pops,
                },
                self.native_chain_id_hash(),
                self.context.epoch,
            )
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        if target != expected_target {
            return Err(V2LaneWorkError::Persistence(
                "persisted autonomous NewView target differs from the deterministic cursor"
                    .to_owned(),
            ));
        }

        // Kura is authoritative. Volatile conflict detection, the cursor, the
        // next timeout, and outbound transport become visible only after the
        // exact certificate and signer PoPs are durable.
        self.autonomous_new_view_certificates = next_certificates;
        self.autonomous_payload_views
            .insert(key, certificate.body.target_view);
        if self.voting_enabled
            && self.local_peer.public_key().try_algorithm().ok() == Some(Algorithm::BlsNormal)
            && certificate.validator_set.contains(&self.local_peer)
        {
            self.autonomous_new_view_started_at
                .insert(key, (certificate.body.target_view, installed_at));
        } else {
            self.autonomous_new_view_started_at.remove(&key);
        }
        let validators = certificate.validator_set.clone();
        if validators.contains(&self.local_peer) {
            self.fanout_lane_message(
                BlockMessage::LaneBlockNewViewCertificate(certificate),
                &validators,
            );
        }
        operation.complete();
        Ok(())
    }

    fn try_insert_autonomous_new_view_vote(
        &mut self,
        vote: crate::lane_consensus::LaneBlockNewViewVoteV1,
        sender: Option<&PeerId>,
        active_view: wire::View,
        observed_at: Instant,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        if sender != Some(&vote.signer) {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let Some(validators) =
            self.expected_lane_validators(vote.body.lane_id, vote.body.proposal_height)
        else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        if !validators.contains(&vote.signer) {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        if self.autonomous_new_view_votes.contains(&vote) {
            return Ok(V2LaneIngressOutcome::Duplicate);
        }
        if !self.autonomous_new_view_transition_is_current(&vote.body, active_view) {
            return Ok(V2LaneIngressOutcome::Rejected);
        }

        let mut next_votes = self.autonomous_new_view_votes.clone();
        let Ok((outcome, certificate)) = next_votes.insert_and_maybe_seal(vote, &validators) else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        if let Some(certificate) = certificate {
            let Some(pops) = self.pops_for_autonomous_new_view(&certificate) else {
                return Ok(V2LaneIngressOutcome::Rejected);
            };
            let mut next_certificates = self.autonomous_new_view_certificates.clone();
            if next_certificates
                .insert(certificate.clone(), &pops)
                .is_err()
            {
                return Ok(V2LaneIngressOutcome::Rejected);
            }
            self.persist_and_install_autonomous_new_view_certificate(
                certificate,
                pops,
                next_certificates,
                active_view,
                observed_at,
            )?;
        }
        self.autonomous_new_view_votes = next_votes;
        Ok(match outcome {
            LaneBlockNewViewCacheOutcome::Inserted => V2LaneIngressOutcome::Inserted,
            LaneBlockNewViewCacheOutcome::Duplicate => V2LaneIngressOutcome::Duplicate,
        })
    }

    fn insert_autonomous_new_view_vote(
        &mut self,
        vote: crate::lane_consensus::LaneBlockNewViewVoteV1,
        sender: Option<&PeerId>,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        match self.try_insert_autonomous_new_view_vote(vote, sender, active_view, Instant::now()) {
            Ok(outcome) => outcome,
            Err(error) => {
                iroha_logger::error!(
                    %error,
                    height = self.context.height,
                    "failed to durably install an autonomous NewView certificate"
                );
                V2LaneIngressOutcome::Rejected
            }
        }
    }

    fn try_insert_autonomous_new_view_certificate(
        &mut self,
        certificate: crate::lane_consensus::LaneBlockNewViewCertificateV1,
        sender: Option<&PeerId>,
        active_view: wire::View,
        observed_at: Instant,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        let expected_validators = self
            .expected_lane_validators(certificate.body.lane_id, certificate.body.proposal_height);
        if !sender.is_some_and(|sender| certificate.validator_set.contains(sender))
            || expected_validators != Some(certificate.validator_set.clone())
        {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let Some(pops) = self.pops_for_autonomous_new_view(&certificate) else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        if crate::lane_consensus::validate_lane_block_new_view_certificate(&certificate, &pops)
            .is_err()
        {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        if self.autonomous_new_view_certificates.contains(&certificate) {
            return Ok(V2LaneIngressOutcome::Duplicate);
        }
        if !self.autonomous_new_view_transition_is_current(&certificate.body, active_view) {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let mut next = self.autonomous_new_view_certificates.clone();
        match next.insert(certificate.clone(), &pops) {
            Ok(LaneBlockNewViewCacheOutcome::Inserted) => {
                self.persist_and_install_autonomous_new_view_certificate(
                    certificate,
                    pops,
                    next,
                    active_view,
                    observed_at,
                )?;
                Ok(V2LaneIngressOutcome::Inserted)
            }
            Ok(LaneBlockNewViewCacheOutcome::Duplicate) => Ok(V2LaneIngressOutcome::Duplicate),
            Err(_) => Ok(V2LaneIngressOutcome::Rejected),
        }
    }

    fn insert_autonomous_new_view_certificate(
        &mut self,
        certificate: crate::lane_consensus::LaneBlockNewViewCertificateV1,
        sender: Option<&PeerId>,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        match self.try_insert_autonomous_new_view_certificate(
            certificate,
            sender,
            active_view,
            Instant::now(),
        ) {
            Ok(outcome) => outcome,
            Err(error) => {
                iroha_logger::error!(
                    %error,
                    height = self.context.height,
                    "failed to durably install a received autonomous NewView certificate"
                );
                V2LaneIngressOutcome::Rejected
            }
        }
    }

    /// Treat an exact canonical proposal retransmission as an idempotent
    /// request for the complete Kura-backed certificate.
    ///
    /// The requester retains and periodically retransmits its incomplete
    /// proposal, so an occupied effect slot leaves reconstruction at the
    /// durable source instead of requiring an unbounded response queue here.
    fn serve_durable_lane_certificate(
        &mut self,
        proposal: &LaneBlockProposalV1,
        sender: Option<&PeerId>,
        reply_routes: Option<NetworkReplyRoutes>,
        ingress_ownership: Option<FairV2IngressOwnershipEvidence>,
    ) -> Option<V2LaneIngressOutcome> {
        let sender = sender?;
        let Some(reply_routes) = reply_routes else {
            return Some(V2LaneIngressOutcome::Rejected);
        };
        if !reply_routes_are_live_for_peer(&reply_routes, sender) {
            return Some(V2LaneIngressOutcome::Rejected);
        }
        let certificate = match self.reconstruct_durable_lane_certificate(proposal, sender) {
            Ok(Some(certificate)) => certificate,
            Ok(None) => return None,
            Err(()) => return Some(V2LaneIngressOutcome::Rejected),
        };
        let queued = self.push_effect(V2LaneWorkEffect::PostDurableLaneCertificate {
            peer: sender.clone(),
            reply_routes: Some(reply_routes),
            ingress_ownership,
            certificate,
        });
        Some(if queued {
            V2LaneIngressOutcome::Inserted
        } else {
            V2LaneIngressOutcome::Duplicate
        })
    }

    fn reconstruct_durable_lane_certificate(
        &self,
        proposal: &LaneBlockProposalV1,
        sender: &PeerId,
    ) -> Result<Option<LaneBlockCertificateV1>, ()> {
        let artifact = self.kura.read_certified_lane_block_artifact(
            proposal.descriptor.lane_id,
            proposal.descriptor.lane_block_height,
        );
        let Some(artifact) = artifact else {
            return Ok(None);
        };
        if artifact.proposal != *proposal {
            return Ok(None);
        }
        // The requester need not belong to the historical lane committee: a
        // current global validator which missed the original lane fanout must
        // still be able to apply the already-committed global block. Limit the
        // idempotent response to an authenticated member of either the frozen
        // current global roster or the canonical historical lane committee.
        let requester_is_current_validator = self
            .context
            .roster
            .iter()
            .any(|entry| &entry.validator == sender);
        if !requester_is_current_validator && !artifact.commit_qc.validator_set.contains(sender) {
            return Err(());
        }
        Ok(Some(LaneBlockCertificateV1 {
            proposal: artifact.proposal,
            prepare_qc: artifact.prepare_qc,
            commit_qc: artifact.commit_qc,
        }))
    }

    fn historical_recovery_response_fits_frame(
        &self,
        response: &LaneHistoricalRecoveryResponseV1,
    ) -> bool {
        let block_message_bytes =
            BlockMessage::LaneHistoricalRecoveryResponse(Box::new(response.clone()))
                .encode()
                .len();
        super::fair_v2_ingress_required_lane_p2p_frame_bytes(block_message_bytes)
            <= self
                .limits
                .historical_recovery_response_frame_capacity
                .get()
    }

    fn peer_is_global_finality_signer(
        finality: &wire::finality::V2FinalityArtifact,
        peer: &PeerId,
    ) -> bool {
        finality
            .height_context
            .roster
            .iter()
            .position(|entry| &entry.validator == peer)
            .and_then(|index| u32::try_from(index).ok())
            .is_some_and(|index| finality.commit_qc.signers.binary_search(&index).is_ok())
    }

    fn peer_is_ready_signer(
        availability: &iroha_data_model::block::consensus::LanePayloadAvailabilityQcV1,
        peer: &PeerId,
    ) -> bool {
        availability
            .validator_set
            .iter()
            .position(|validator| validator == peer)
            .is_some_and(|index| bitmap_selects(&availability.signers_bitmap, index))
    }

    fn validate_historical_recovery_request(
        &self,
        request: &LaneHistoricalRecoveryRequestV1,
        sender: &PeerId,
    ) -> Result<CommittedLaneBlockSession, String> {
        let certificate = request
            .certificate
            .as_ref()
            .ok_or_else(|| "historical lane recovery request has no lane certificate".to_owned())?;
        if request.version != LANE_HISTORICAL_RECOVERY_VERSION_V2
            || &request.requester != sender
            || certificate.proposal.descriptor.proposal_height >= self.context.height
            || !self.historical_recovery_request_fits_frame(request)
            || matches!(
                &request.kind,
                LaneHistoricalRecoveryKindV1::NativeAmxParticipantCanonicalBlock { .. }
            )
        {
            return Err(
                "historical recovery request has an invalid version, sender, height, or size"
                    .to_owned(),
            );
        }
        let requester_is_authorized = self
            .context
            .roster
            .iter()
            .any(|entry| &entry.validator == sender)
            || certificate.commit_qc.validator_set.contains(sender);
        if !requester_is_authorized {
            return Err(
                "historical recovery requester is outside the active and certified committees"
                    .to_owned(),
            );
        }
        let session = CommittedLaneBlockSession {
            proposal: certificate.proposal.clone(),
            prepare_qc: certificate.prepare_qc.clone(),
            commit_qc: certificate.commit_qc.clone(),
        };
        let candidate =
            CertifiedLaneBlockArtifact::new(session.clone(), request.signer_pops.clone());
        Kura::validate_certified_lane_block_artifact(&candidate)
            .map_err(|error| format!("historical recovery certificate is invalid: {error}"))?;
        let identity = HistoricalRecoveryIdentity::from_proposal(&session.proposal)
            .map_err(|error| error.to_string())?;
        let descriptor = &session.proposal.descriptor;
        if !self.lane_route_active(
            descriptor.lane_id,
            descriptor.dataspace_id,
            descriptor.lane_incarnation,
            descriptor.proposal_height,
        ) || !self
            .state
            .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(
                &session.proposal,
            )
        {
            return Err(
                "historical recovery certificate has a stale route, incarnation, or predecessor"
                    .to_owned(),
            );
        }
        match self
            .historical_proposal_anchor_wait(&session.proposal)
            .map_err(|error| error.to_string())?
        {
            None => {}
            Some(_) => {
                return Err(
                    "historical recovery source lacks the exact committed global anchor".to_owned(),
                );
            }
        }
        if !self.session_has_canonical_anchor(&session) {
            return Err(
                "historical recovery certificate is absent from its exact global carrier"
                    .to_owned(),
            );
        }
        match &request.kind {
            LaneHistoricalRecoveryKindV1::CanonicalBlock {
                finality_artifact_hash,
            } => {
                let hint = session.proposal.payload_block_hint.ok_or_else(|| {
                    "historical canonical-body request lacks a global proposal hint".to_owned()
                })?;
                let finality = self
                    .kura
                    .v2_finality_artifact(identity.proposal_height)
                    .map_err(|error| error.to_string())?
                    .ok_or_else(|| {
                        "historical recovery source lacks the requested finality artifact"
                            .to_owned()
                    })?;
                finality.verify().map_err(|error| error.to_string())?;
                if HashOf::new(&finality) != *finality_artifact_hash
                    || finality.height != identity.proposal_height
                    || finality.block_hash != identity.proposal_block_hash
                    || hint.proposal_height != identity.proposal_height
                    || hint.proposal_block_hash != identity.proposal_block_hash
                    || hint.proposal_view != finality.commit_qc.proposal_round.view
                {
                    return Err(
                        "historical canonical-body request differs from durable finality"
                            .to_owned(),
                    );
                }
            }
            LaneHistoricalRecoveryKindV1::AutonomousPayload {
                executable_payload_hash,
                prepare_qc_hash,
                commit_qc_hash,
            } => {
                let availability = session
                    .prepare_qc
                    .payload_availability_qc
                    .as_ref()
                    .ok_or_else(|| {
                        "historical autonomous request lacks a READY certificate".to_owned()
                    })?;
                crate::lane_consensus::validate_lane_payload_availability_qc(availability)
                    .map_err(|error| error.to_string())?;
                if availability.body.executable_payload_hash != *executable_payload_hash
                    || HashOf::new(&session.prepare_qc) != *prepare_qc_hash
                    || HashOf::new(&session.commit_qc) != *commit_qc_hash
                {
                    return Err(
                        "historical autonomous request hashes differ from its certificate"
                            .to_owned(),
                    );
                }
            }
            LaneHistoricalRecoveryKindV1::NativeAmxParticipantCanonicalBlock { .. } => {
                return Err(
                    "Native participant carrier recovery cannot carry a lane certificate"
                        .to_owned(),
                );
            }
        }
        Ok(session)
    }

    fn validate_native_participant_recovery_request(
        &self,
        request: &LaneHistoricalRecoveryRequestV1,
        sender: &PeerId,
    ) -> Result<
        (
            NativeAmxParticipantRecoveryMarkerV1,
            wire::finality::V2FinalityArtifact,
            wire::ExecutionCommitment,
        ),
        String,
    > {
        let LaneHistoricalRecoveryKindV1::NativeAmxParticipantCanonicalBlock {
            marker,
            finality_artifact_hash,
            execution_commitment,
        } = &request.kind
        else {
            return Err("request is not a Native participant carrier recovery".to_owned());
        };
        if request.version != LANE_HISTORICAL_RECOVERY_VERSION_V2
            || &request.requester != sender
            || request.certificate.is_some()
            || !request.signer_pops.is_empty()
            || marker.application_block_height > self.context.height
            || !native_participant_recovery_marker_is_well_formed(marker)
            || !self.historical_recovery_request_fits_frame(request)
            || !self.lane_route_active(
                marker.lane_id,
                marker.dataspace_id,
                marker.lane_incarnation,
                marker.application_block_height,
            )
            || self
                .state
                .committed_block_hash_at_height(marker.application_block_height)
                != Some(marker.application_block_hash)
        {
            return Err(
                "Native participant carrier recovery request has invalid shape, size, route, incarnation, or canonical identity"
                    .to_owned(),
            );
        }
        let finality = self
            .kura
            .v2_finality_artifact(marker.application_block_height)
            .map_err(|error| error.to_string())?
            .ok_or_else(|| {
                "Native participant carrier recovery source lacks durable V2 finality".to_owned()
            })?;
        finality.verify().map_err(|error| error.to_string())?;
        let requester_is_authorized = self
            .context
            .roster
            .iter()
            .any(|entry| &entry.validator == sender)
            || finality
                .height_context
                .roster
                .iter()
                .any(|entry| &entry.validator == sender);
        if !requester_is_authorized
            || HashOf::new(&finality) != *finality_artifact_hash
            || finality.height != marker.application_block_height
            || finality.block_hash != marker.application_block_hash
            || finality.commit_qc.execution_commitment != **execution_commitment
            || execution_commitment.validate().is_err()
            || execution_commitment.native_amx_application_manifest_count == 0
        {
            return Err(
                "Native participant carrier recovery request differs from durable finality authority"
                    .to_owned(),
            );
        }
        Ok((**marker, finality, **execution_commitment))
    }

    fn serve_historical_recovery_request(
        &mut self,
        request: LaneHistoricalRecoveryRequestV1,
        sender: Option<&PeerId>,
    ) -> V2LaneIngressOutcome {
        let Some(sender) = sender else {
            return V2LaneIngressOutcome::Rejected;
        };
        if matches!(
            &request.kind,
            LaneHistoricalRecoveryKindV1::NativeAmxParticipantCanonicalBlock { .. }
        ) {
            let (marker, finality, execution_commitment) =
                match self.validate_native_participant_recovery_request(&request, sender) {
                    Ok(validated) => validated,
                    Err(error) => {
                        iroha_logger::debug!(
                            %error,
                            "rejected Native participant carrier recovery request"
                        );
                        return V2LaneIngressOutcome::Rejected;
                    }
                };
            if !Self::peer_is_global_finality_signer(&finality, &self.local_peer) {
                return V2LaneIngressOutcome::Rejected;
            }
            let Some(height) = usize::try_from(marker.application_block_height)
                .ok()
                .and_then(NonZeroUsize::new)
            else {
                return V2LaneIngressOutcome::Rejected;
            };
            let Some(block) = self.kura.get_block(height) else {
                return V2LaneIngressOutcome::Rejected;
            };
            if !native_participant_recovery_block_matches_finality(
                &block,
                &finality,
                &execution_commitment,
                &marker,
            ) {
                return V2LaneIngressOutcome::Rejected;
            }
            let response = LaneHistoricalRecoveryResponseV1 {
                version: LANE_HISTORICAL_RECOVERY_VERSION_V2,
                request_hash: HashOf::new(&request),
                payload: LaneHistoricalRecoveryPayloadV1::CanonicalBlock {
                    block: block.as_ref().clone(),
                    finality_artifact: finality,
                },
            };
            if !self.historical_recovery_response_fits_frame(&response) {
                return V2LaneIngressOutcome::Rejected;
            }
            return if self.push_effect(V2LaneWorkEffect::PostLaneBlock {
                peer: sender.clone(),
                message: BlockMessage::LaneHistoricalRecoveryResponse(Box::new(response)),
            }) {
                V2LaneIngressOutcome::Inserted
            } else {
                V2LaneIngressOutcome::Duplicate
            };
        }
        let session = match self.validate_historical_recovery_request(&request, sender) {
            Ok(session) => session,
            Err(error) => {
                iroha_logger::debug!(%error, "rejected historical lane recovery request");
                return V2LaneIngressOutcome::Rejected;
            }
        };
        let request_hash = HashOf::new(&request);
        let response_payload = match &request.kind {
            LaneHistoricalRecoveryKindV1::CanonicalBlock { .. } => {
                let height = session.proposal.descriptor.proposal_height;
                let finality = match self.kura.v2_finality_artifact(height) {
                    Ok(Some(finality)) => finality,
                    _ => return V2LaneIngressOutcome::Rejected,
                };
                if !Self::peer_is_global_finality_signer(&finality, &self.local_peer) {
                    return V2LaneIngressOutcome::Rejected;
                }
                let Some(height) = usize::try_from(height).ok().and_then(NonZeroUsize::new) else {
                    return V2LaneIngressOutcome::Rejected;
                };
                let Some(block) = self.kura.get_block(height) else {
                    return V2LaneIngressOutcome::Rejected;
                };
                if finality.validate_for_header(&block.header()).is_err()
                    || finality.verify().is_err()
                {
                    return V2LaneIngressOutcome::Rejected;
                }
                LaneHistoricalRecoveryPayloadV1::CanonicalBlock {
                    block: block.as_ref().clone(),
                    finality_artifact: finality,
                }
            }
            LaneHistoricalRecoveryKindV1::AutonomousPayload { .. } => {
                let availability = match session.prepare_qc.payload_availability_qc.as_ref() {
                    Some(availability) => availability,
                    None => return V2LaneIngressOutcome::Rejected,
                };
                if !Self::peer_is_ready_signer(availability, &self.local_peer) {
                    return V2LaneIngressOutcome::Rejected;
                }
                let descriptor = &session.proposal.descriptor;
                let expected_epoch = {
                    let world = self.state.world_view();
                    crate::sumeragi::epoch_for_height_from_world(&world, descriptor.proposal_height)
                };
                let certified = match self.kura.read_certified_lane_block_artifact(
                    descriptor.lane_id,
                    descriptor.lane_block_height,
                ) {
                    Some(certified)
                        if certified.proposal == session.proposal
                            && certified.prepare_qc == session.prepare_qc
                            && certified.commit_qc == session.commit_qc
                            && certified.signer_pops == request.signer_pops =>
                    {
                        certified
                    }
                    _ => return V2LaneIngressOutcome::Rejected,
                };
                let Some((payload, _)) = self.kura.current_autonomous_lane_payload(
                    descriptor.lane_id,
                    descriptor.lane_block_height,
                    self.native_chain_id_hash(),
                    expected_epoch,
                ) else {
                    return V2LaneIngressOutcome::Rejected;
                };
                let durable_availability = self.kura.read_autonomous_lane_block_artifact(
                    descriptor.lane_id,
                    descriptor.lane_block_height,
                    self.native_chain_id_hash(),
                    expected_epoch,
                );
                if durable_availability
                    .as_ref()
                    .and_then(|artifact| artifact.availability_certificate.as_ref())
                    .is_none_or(|certificate| certificate.certificate != session.prepare_qc)
                {
                    return V2LaneIngressOutcome::Rejected;
                }
                LaneHistoricalRecoveryPayloadV1::AutonomousPayload {
                    payload,
                    prepare_qc: certified.prepare_qc,
                    commit_qc: certified.commit_qc,
                }
            }
            LaneHistoricalRecoveryKindV1::NativeAmxParticipantCanonicalBlock { .. } => {
                return V2LaneIngressOutcome::Rejected;
            }
        };
        let response = LaneHistoricalRecoveryResponseV1 {
            version: LANE_HISTORICAL_RECOVERY_VERSION_V2,
            request_hash,
            payload: response_payload,
        };
        if !self.historical_recovery_response_fits_frame(&response) {
            return V2LaneIngressOutcome::Rejected;
        }
        if self.push_effect(V2LaneWorkEffect::PostLaneBlock {
            peer: sender.clone(),
            message: BlockMessage::LaneHistoricalRecoveryResponse(Box::new(response)),
        }) {
            V2LaneIngressOutcome::Inserted
        } else {
            V2LaneIngressOutcome::Duplicate
        }
    }

    fn accept_historical_recovery_response(
        &mut self,
        response: LaneHistoricalRecoveryResponseV1,
        sender: Option<&PeerId>,
    ) -> V2LaneIngressOutcome {
        let Some(sender) = sender else {
            return V2LaneIngressOutcome::Rejected;
        };
        if response.version != LANE_HISTORICAL_RECOVERY_VERSION_V2
            || !self.historical_recovery_response_fits_frame(&response)
        {
            return V2LaneIngressOutcome::Rejected;
        }
        if let Some(marker) = self
            .native_participant_recovery_request_owners
            .get(&response.request_hash)
            .copied()
        {
            return self.accept_native_participant_recovery_response(response, sender, marker);
        }
        let Some(identity) = self
            .historical_recovery_request_owners
            .get(&response.request_hash)
            .copied()
        else {
            return V2LaneIngressOutcome::Rejected;
        };
        let Some(outstanding) = self.historical_recovery_requests.get(&identity) else {
            return V2LaneIngressOutcome::Rejected;
        };
        if outstanding.request_hash != response.request_hash
            || HashOf::new(&outstanding.request) != response.request_hash
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let request = outstanding.request.clone();
        let Some(certificate) = request.certificate.as_ref() else {
            return V2LaneIngressOutcome::Rejected;
        };
        let request_session = CommittedLaneBlockSession {
            proposal: certificate.proposal.clone(),
            prepare_qc: certificate.prepare_qc.clone(),
            commit_qc: certificate.commit_qc.clone(),
        };
        if HistoricalRecoveryIdentity::from_proposal(&request_session.proposal).ok()
            != Some(identity)
            || Kura::validate_certified_lane_block_artifact(&CertifiedLaneBlockArtifact::new(
                request_session,
                request.signer_pops.clone(),
            ))
            .is_err()
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let request_descriptor = &certificate.proposal.descriptor;
        if !self.lane_route_active(
            request_descriptor.lane_id,
            request_descriptor.dataspace_id,
            request_descriptor.lane_incarnation,
            request_descriptor.proposal_height,
        ) || !self
            .state
            .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(
                &certificate.proposal,
            )
        {
            return V2LaneIngressOutcome::Rejected;
        }
        // Authenticate the transport source from the request's frozen proof
        // before consulting or mutating Kura. A canonical body may come only
        // from a signer of the exact CommitQC named by the request; an
        // autonomous payload may come only from a signer selected by its exact
        // READY bitmap. This also rejects a payload-kind substitution before
        // any persistence boundary is crossed.
        match (&request.kind, &response.payload) {
            (
                LaneHistoricalRecoveryKindV1::CanonicalBlock {
                    finality_artifact_hash,
                },
                LaneHistoricalRecoveryPayloadV1::CanonicalBlock {
                    finality_artifact, ..
                },
            ) if HashOf::new(finality_artifact) == *finality_artifact_hash
                && Self::peer_is_global_finality_signer(finality_artifact, sender) => {}
            (
                LaneHistoricalRecoveryKindV1::AutonomousPayload { .. },
                LaneHistoricalRecoveryPayloadV1::AutonomousPayload { .. },
            ) if certificate
                .prepare_qc
                .payload_availability_qc
                .as_ref()
                .is_some_and(|availability| Self::peer_is_ready_signer(availability, sender)) => {}
            _ => return V2LaneIngressOutcome::Rejected,
        }
        let result = match (&request.kind, response.payload) {
            (
                LaneHistoricalRecoveryKindV1::CanonicalBlock {
                    finality_artifact_hash,
                },
                LaneHistoricalRecoveryPayloadV1::CanonicalBlock {
                    block,
                    finality_artifact,
                },
            ) => {
                let Some(hint) = certificate.proposal.payload_block_hint else {
                    return V2LaneIngressOutcome::Rejected;
                };
                let local_finality = match self.kura.v2_finality_artifact(hint.proposal_height) {
                    Ok(Some(finality)) => finality,
                    _ => return V2LaneIngressOutcome::Rejected,
                };
                if HashOf::new(&finality_artifact) != *finality_artifact_hash
                    || finality_artifact != local_finality
                    || finality_artifact.verify().is_err()
                    || finality_artifact
                        .validate_for_header(&block.header())
                        .is_err()
                    || finality_artifact.height != hint.proposal_height
                    || finality_artifact.block_hash != hint.proposal_block_hash
                    || block.header().view_change_index() != hint.proposal_view
                    || !self.historical_block_anchors_proposal(&block, &certificate.proposal)
                    || !Self::peer_is_global_finality_signer(&finality_artifact, sender)
                    || self
                        .state
                        .committed_block_hash_at_height(hint.proposal_height)
                        != Some(hint.proposal_block_hash)
                {
                    return V2LaneIngressOutcome::Rejected;
                }
                self.kura
                    .cache_block_body(&block)
                    .map_err(|error| error.to_string())
            }
            (
                LaneHistoricalRecoveryKindV1::AutonomousPayload {
                    executable_payload_hash,
                    prepare_qc_hash,
                    commit_qc_hash,
                },
                LaneHistoricalRecoveryPayloadV1::AutonomousPayload {
                    payload,
                    prepare_qc,
                    commit_qc,
                },
            ) => {
                let proposal = &certificate.proposal;
                let descriptor = &proposal.descriptor;
                let signer_pops = request.signer_pops.clone();
                let Some(availability) = prepare_qc.payload_availability_qc.as_ref() else {
                    return V2LaneIngressOutcome::Rejected;
                };
                let expected_epoch = {
                    let world = self.state.world_view();
                    crate::sumeragi::epoch_for_height_from_world(&world, descriptor.proposal_height)
                };
                if prepare_qc != certificate.prepare_qc
                    || commit_qc != certificate.commit_qc
                    || HashOf::new(&prepare_qc) != *prepare_qc_hash
                    || HashOf::new(&commit_qc) != *commit_qc_hash
                    || payload.origin_proposal != *proposal
                    || payload.payload_hash != *executable_payload_hash
                    || availability.body.executable_payload_hash != *executable_payload_hash
                    || !Self::peer_is_ready_signer(availability, sender)
                    || payload
                        .validate(self.native_chain_id_hash(), expected_epoch)
                        .is_err()
                    || validate_lane_block_qc_aggregate(&prepare_qc, &signer_pops).is_err()
                    || validate_lane_block_qc_aggregate(&commit_qc, &signer_pops).is_err()
                    || crate::lane_consensus::validate_lane_payload_availability_certificate(
                        &DurableLanePayloadAvailabilityCertificateV1 {
                            certificate: prepare_qc.clone(),
                        },
                        &payload,
                        self.native_chain_id_hash(),
                        expected_epoch,
                    )
                    .is_err()
                {
                    return V2LaneIngressOutcome::Rejected;
                }
                let session = CommittedLaneBlockSession {
                    proposal: proposal.clone(),
                    prepare_qc: prepare_qc.clone(),
                    commit_qc: commit_qc.clone(),
                };
                let candidate =
                    CertifiedLaneBlockArtifact::new(session.clone(), signer_pops.clone());
                if Kura::validate_certified_lane_block_artifact(&candidate).is_err() {
                    return V2LaneIngressOutcome::Rejected;
                }
                self.kura
                    .persist_lane_executable_payload(
                        &payload,
                        self.native_chain_id_hash(),
                        expected_epoch,
                    )
                    .map_err(|error| error.to_string())
                    .and_then(|()| {
                        self.kura
                            .recover_autonomous_lane_block_payload(
                                proposal,
                                self.native_chain_id_hash(),
                                expected_epoch,
                            )
                            .map_err(|error| format!("{error:?}"))
                    })
                    .and_then(|execution| {
                        self.kura
                            .persist_lane_block_execution_input(&execution)
                            .map_err(|error| error.to_string())
                    })
                    .and_then(|()| {
                        self.kura
                            .persist_lane_payload_availability_certificate(
                                descriptor.lane_id,
                                descriptor.lane_block_height,
                                DurableLanePayloadAvailabilityCertificateV1 {
                                    certificate: prepare_qc,
                                },
                                self.native_chain_id_hash(),
                                expected_epoch,
                            )
                            .map_err(|error| error.to_string())
                    })
                    .and_then(|()| {
                        self.kura
                            .persist_committed_lane_block_session(&session, &signer_pops)
                            .map_err(|error| error.to_string())
                    })
            }
            _ => return V2LaneIngressOutcome::Rejected,
        };
        if let Err(error) = result {
            iroha_logger::error!(
                %error,
                lane = identity.lane_id.as_u32(),
                lane_block_height = identity.lane_block_height,
                "authenticated historical recovery import failed; requiring restart"
            );
            self.output_guard.close_admission_for_restart();
            return V2LaneIngressOutcome::Rejected;
        }
        self.retire_historical_recovery_request(identity);
        V2LaneIngressOutcome::Inserted
    }

    fn accept_native_participant_recovery_response(
        &mut self,
        response: LaneHistoricalRecoveryResponseV1,
        sender: &PeerId,
        marker: NativeAmxParticipantRecoveryMarkerV1,
    ) -> V2LaneIngressOutcome {
        let Some(outstanding) = self
            .native_participant_recovery_requests
            .get(&marker)
            .cloned()
        else {
            return V2LaneIngressOutcome::Rejected;
        };
        if outstanding.request_hash != response.request_hash
            || HashOf::new(&outstanding.request) != response.request_hash
            || outstanding.request.certificate.is_some()
            || !outstanding.request.signer_pops.is_empty()
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let LaneHistoricalRecoveryKindV1::NativeAmxParticipantCanonicalBlock {
            marker: requested_marker,
            finality_artifact_hash,
            execution_commitment,
        } = outstanding.request.kind
        else {
            return V2LaneIngressOutcome::Rejected;
        };
        let requested_marker = *requested_marker;
        if requested_marker != marker
            || !native_participant_recovery_marker_is_well_formed(&marker)
            || !self.lane_route_active(
                marker.lane_id,
                marker.dataspace_id,
                marker.lane_incarnation,
                marker.application_block_height,
            )
            || self
                .state
                .committed_block_hash_at_height(marker.application_block_height)
                != Some(marker.application_block_hash)
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let pending = match self.pending_native_participant_recovery_markers() {
            Ok(pending) => pending.contains(&marker),
            Err(_) => return V2LaneIngressOutcome::Rejected,
        };
        if !pending {
            self.retire_native_participant_recovery_request(marker);
            return V2LaneIngressOutcome::Rejected;
        }
        let LaneHistoricalRecoveryPayloadV1::CanonicalBlock {
            block,
            finality_artifact,
        } = response.payload
        else {
            return V2LaneIngressOutcome::Rejected;
        };
        let local_finality = match self
            .kura
            .v2_finality_artifact(marker.application_block_height)
        {
            Ok(Some(finality)) => finality,
            _ => return V2LaneIngressOutcome::Rejected,
        };
        if HashOf::new(&finality_artifact) != finality_artifact_hash
            || finality_artifact != local_finality
            || !Self::peer_is_global_finality_signer(&finality_artifact, sender)
            || !native_participant_recovery_block_matches_finality(
                &block,
                &finality_artifact,
                &execution_commitment,
                &marker,
            )
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let result = self
            .kura
            .cache_block_body(&block)
            .map_err(|error| error.to_string())
            .and_then(|()| {
                self.kura
                    .repair_native_amx_participant_application_evidence(&block)
                    .map_err(|error| error.to_string())
                    .map(|_| ())
            });
        if let Err(error) = result {
            iroha_logger::error!(
                %error,
                lane = marker.lane_id.as_u32(),
                participant_height = marker.participant_height,
                application_block_height = marker.application_block_height,
                "authenticated Native participant carrier import failed; requiring restart"
            );
            self.output_guard.close_admission_for_restart();
            return V2LaneIngressOutcome::Rejected;
        }
        match self.reconcile_native_participant_recovery_requests() {
            Ok(pending) if !pending.contains(&marker) => V2LaneIngressOutcome::Inserted,
            Ok(_) | Err(_) => {
                self.output_guard.close_admission_for_restart();
                V2LaneIngressOutcome::Rejected
            }
        }
    }

    /// Register a deterministic validation blocked only on one exact certified
    /// merge sidecar. The merge QC authenticates its own immutable carrier view,
    /// which may precede the enclosing proposal round and is never rebound to
    /// that proposal's view.
    pub(crate) fn defer_missing_merge_sidecar(
        &mut self,
        round: wire::ConsensusRound,
        subject: wire::BlockSubject,
        reference: CertifiedMergeLedgerReference,
    ) -> Result<MergeSidecarDeferralDisposition, V2LaneWorkError> {
        self.defer_missing_merge_sidecar_with_priority(round, subject, reference, false)
    }

    /// Register a decided Apply dependency using transport capacity reserved
    /// from speculative validation work.
    pub(crate) fn defer_missing_decided_merge_sidecar(
        &mut self,
        round: wire::ConsensusRound,
        subject: wire::BlockSubject,
        reference: CertifiedMergeLedgerReference,
    ) -> Result<MergeSidecarDeferralDisposition, V2LaneWorkError> {
        self.defer_missing_merge_sidecar_with_priority(round, subject, reference, true)
    }

    fn defer_missing_merge_sidecar_with_priority(
        &mut self,
        round: wire::ConsensusRound,
        subject: wire::BlockSubject,
        reference: CertifiedMergeLedgerReference,
        decided: bool,
    ) -> Result<MergeSidecarDeferralDisposition, V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        let result = self.defer_missing_merge_sidecar_guarded(round, subject, reference, decided);
        if result.is_ok() {
            operation.complete();
        }
        result
    }

    fn defer_missing_merge_sidecar_guarded(
        &mut self,
        round: wire::ConsensusRound,
        subject: wire::BlockSubject,
        reference: CertifiedMergeLedgerReference,
        decided: bool,
    ) -> Result<MergeSidecarDeferralDisposition, V2LaneWorkError> {
        let Some(parent_hash) = subject.parent_block_hash else {
            return Ok(MergeSidecarDeferralDisposition::Rejected(
                "height-one body cannot carry a certified merge entry".to_owned(),
            ));
        };
        if round.context_id != self.context.id()
            || round.height != self.context.height
            || reference.merge_qc.carrier_height != round.height
            || reference.merge_qc.carrier_parent_hash != parent_hash
            || reference.merge_qc.view > round.view
        {
            return Ok(MergeSidecarDeferralDisposition::Rejected(
                "certified merge reference is not bound to the body's exact carrier height, parent, and carrier view"
                    .to_owned(),
            ));
        }
        // No transport progress is possible until the reserved outbound queue
        // drains. Avoid repeating a protocol-sized QC/PoP verification twice
        // per runner iteration while the exact deferral remains queued.
        if self.sidecar_effect_slots() == 0 {
            return Ok(MergeSidecarDeferralDisposition::RetryLater);
        }

        match self.kura.merge_entry_by_hash(reference.entry_hash) {
            Ok(Some(entry)) => {
                if !reference.matches_entry(&entry) {
                    return Ok(MergeSidecarDeferralDisposition::Rejected(
                        "durable merge sidecar differs from the block's compact reference"
                            .to_owned(),
                    ));
                }
                if let Err(error) =
                    authenticate_merge_entry_for_height_context(&self.context, &entry)
                {
                    return Ok(MergeSidecarDeferralDisposition::Rejected(error));
                }
                if let Err(error) = self
                    .state
                    .validate_certified_merge_entry_for_global_order(&entry)
                {
                    return Ok(MergeSidecarDeferralDisposition::Rejected(error.to_string()));
                }
                self.completed_merge_sidecars.insert(reference.entry_hash);
                return Ok(MergeSidecarDeferralDisposition::Available);
            }
            Ok(None) => {}
            Err(error) => {
                return Err(V2LaneWorkError::Persistence(error.to_string()));
            }
        }

        if let Err(error) = self.authenticate_merge_sidecar_reference(&reference) {
            return Ok(MergeSidecarDeferralDisposition::Rejected(error));
        }
        let committed_height = u64::try_from(self.state.committed_height())
            .map_err(|_| V2LaneWorkError::StateHeightMismatch)?;
        let deferred = if decided {
            self.merge_sidecars.defer_decided_block(
                subject.block_hash,
                round.height,
                reference.merge_qc.view,
                reference,
                &self.local_peer,
                committed_height,
                Instant::now(),
            )
        } else {
            self.merge_sidecars.defer_block(
                subject.block_hash,
                round.height,
                reference.merge_qc.view,
                reference,
                &self.local_peer,
                committed_height,
                Instant::now(),
            )
        };
        match deferred {
            Ok(Some(post)) => {
                self.push_merge_sidecar_post_or_restart(post)?;
                Ok(MergeSidecarDeferralDisposition::Fetching)
            }
            Ok(None) => Ok(MergeSidecarDeferralDisposition::Fetching),
            Err(MergeSidecarError::Capacity(_)) => Ok(MergeSidecarDeferralDisposition::RetryLater),
            Err(error @ MergeSidecarError::LifecycleJournal(_)) => {
                Err(V2LaneWorkError::Persistence(error.to_string()))
            }
            Err(error) => Ok(MergeSidecarDeferralDisposition::Rejected(error.to_string())),
        }
    }

    fn authenticate_merge_sidecar_reference(
        &mut self,
        reference: &CertifiedMergeLedgerReference,
    ) -> Result<(), String> {
        validate_merge_sidecar_reference_bounds(&self.context, reference)?;
        let qc_key = bounded_merge_qc_authentication_key(reference)?;
        if self.authenticated_merge_qcs.contains(&qc_key) {
            return Ok(());
        }
        #[cfg(test)]
        {
            self.merge_qc_preflight_checks = self.merge_qc_preflight_checks.saturating_add(1);
        }
        authenticate_bounded_merge_sidecar_holders(&self.context, reference)?;
        if self.authenticated_merge_qcs.insert(qc_key) {
            self.authenticated_merge_qc_order.push_back(qc_key);
        }
        while self.authenticated_merge_qc_order.len()
            > self.limits.authenticated_merge_qc_capacity.get()
        {
            let oldest = self
                .authenticated_merge_qc_order
                .pop_front()
                .expect("non-empty authenticated-QC order");
            self.authenticated_merge_qcs.remove(&oldest);
        }
        Ok(())
    }

    /// Take one exact entry hash whose durable installation permits validation
    /// of all retained bodies referencing it to retry.
    pub(crate) fn take_completed_merge_sidecar(&mut self) -> Option<HashOf<MergeLedgerEntry>> {
        let output_guard = Arc::clone(&self.output_guard);
        let _permit = output_guard.acquire()?;
        let hash = self.completed_merge_sidecars.iter().next().copied()?;
        self.completed_merge_sidecars.remove(&hash);
        Some(hash)
    }

    /// Take one exact full-entry rejection to apply to every retained body
    /// referencing the same hash.
    pub(crate) fn take_rejected_merge_sidecar(&mut self) -> Option<RejectedMergeSidecar> {
        let output_guard = Arc::clone(&self.output_guard);
        let _permit = output_guard.acquire()?;
        let entry_hash = self.rejected_merge_sidecars.keys().next().copied()?;
        let reason = self
            .rejected_merge_sidecars
            .remove(&entry_hash)
            .expect("selected rejection exists");
        Some(RejectedMergeSidecar { entry_hash, reason })
    }

    /// Release transport reservations for validation tasks no longer owned by
    /// the executor after a certified view transition or terminal completion.
    pub(crate) fn retain_deferred_merge_sidecars(
        &mut self,
        pending_blocks: &BTreeSet<HashOf<BlockHeader>>,
    ) -> Result<(), V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        let committed_height = u64::try_from(self.state.committed_height())
            .map_err(|_| V2LaneWorkError::StateHeightMismatch)?;
        self.merge_sidecars
            .retain_pending_blocks(pending_blocks, committed_height)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        operation.complete();
        Ok(())
    }

    /// Accept one lane relay, merge signature, or context-bound Native AMX message.
    pub(super) fn accept_relay_message(
        &mut self,
        message: LaneRelayMessage,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        let output_guard = Arc::clone(&self.output_guard);
        let Some(operation) = output_guard.begin_fail_stop_operation() else {
            return V2LaneIngressOutcome::Rejected;
        };
        if self.decision_pending()
            && !matches!(&message, LaneRelayMessage::CertifiedMergeSidecar { .. })
        {
            operation.complete();
            return V2LaneIngressOutcome::Rejected;
        }
        let result = match message {
            LaneRelayMessage::Envelope(envelope) => self.accept_lane_relay(envelope, active_view),
            LaneRelayMessage::MergeSignature(signature) => {
                self.accept_merge_signature(signature, active_view)
            }
            LaneRelayMessage::CertifiedMergeSidecar {
                sender,
                reply_route,
                message,
            } => self.accept_certified_merge_sidecar(sender, reply_route, message),
            LaneRelayMessage::NativeAmx {
                sender,
                reply_route,
                message,
            } => Ok(self.accept_native_amx(sender, reply_route, message, active_view)),
            LaneRelayMessage::DrainVote { sender, vote } => {
                self.accept_lane_drain_vote(sender, vote, active_view)
            }
        };
        match result {
            Ok(outcome) => {
                operation.complete();
                outcome
            }
            Err(error) => {
                iroha_logger::error!(
                    ?error,
                    "Sumeragi v2 lane relay hit a fatal local durability failure"
                );
                drop(operation);
                V2LaneIngressOutcome::Rejected
            }
        }
    }

    /// Clone the next fairly selected effect without transferring its ownership.
    pub(crate) fn next_effect(&self) -> Option<V2LaneWorkEffect> {
        let output_guard = Arc::clone(&self.output_guard);
        let _permit = output_guard.acquire()?;
        let both_ready = !self.sidecar_effects.is_empty() && !self.effects.is_empty();
        let take_sidecar = if both_ready {
            self.drain_sidecar_next
        } else {
            !self.sidecar_effects.is_empty()
        };
        if take_sidecar {
            self.next_sidecar_effect_selection()
                .and_then(|(index, _)| self.sidecar_effects.get(index))
                .cloned()
        } else {
            self.effects.front().cloned()
        }
    }

    /// Number of bounded effects available for one complete fair scheduler scan.
    pub(crate) fn effect_count(&self) -> usize {
        self.effects
            .len()
            .saturating_add(self.sidecar_effects.len())
    }

    /// Return one temporarily unserviceable effect to the tail of its owner lane.
    pub(crate) fn requeue_effect(&mut self, effect: V2LaneWorkEffect) -> bool {
        match effect {
            V2LaneWorkEffect::PostCertifiedMergeSidecar {
                peer,
                reply_routes,
                message,
            } => self.push_merge_sidecar_effect(V2LaneWorkEffect::PostCertifiedMergeSidecar {
                peer,
                reply_routes,
                message,
            }),
            effect => self.push_effect(effect),
        }
    }

    /// Drain at most `limit` explicit transport effects.
    pub(crate) fn drain_effects(&mut self, limit: usize) -> Vec<V2LaneWorkEffect> {
        let output_guard = Arc::clone(&self.output_guard);
        let Some(_permit) = output_guard.acquire() else {
            return Vec::new();
        };
        let mut drained = Vec::with_capacity(
            limit.min(
                self.effects
                    .len()
                    .saturating_add(self.sidecar_effects.len()),
            ),
        );
        while drained.len() < limit {
            let both_ready = !self.sidecar_effects.is_empty() && !self.effects.is_empty();
            let take_sidecar = if both_ready {
                self.drain_sidecar_next
            } else {
                !self.sidecar_effects.is_empty()
            };
            let effect = if take_sidecar {
                let (index, retryable_control) = self
                    .next_sidecar_effect_selection()
                    .expect("sidecar effect selected only when present");
                let effect = self
                    .sidecar_effects
                    .remove(index)
                    .expect("sidecar effect selected only when present");
                self.sidecar_effect_keys
                    .remove(&lane_work_effect_key(&effect));
                if retryable_control {
                    self.sidecar_progress_drain_credit = SIDECAR_PROGRESS_DRAIN_WEIGHT;
                } else {
                    self.sidecar_progress_drain_credit =
                        self.sidecar_progress_drain_credit.saturating_sub(1);
                }
                effect
            } else if let Some(effect) = self.effects.pop_front() {
                self.effect_keys.remove(&lane_work_effect_key(&effect));
                effect
            } else {
                break;
            };
            if both_ready {
                self.drain_sidecar_next = !self.drain_sidecar_next;
            }
            drained.push(effect);
        }
        drained
    }

    /// Emit bounded, independently paced NewView votes for stalled autonomous
    /// lane payloads.
    ///
    /// The durable Kura cursor is the sole transition source. A certified
    /// target changes only retransmission coordination; READY, Prepare,
    /// Commit, and merge certification remain bound to the immutable origin
    /// proposal carried by `LaneExecutablePayloadV1`.
    pub(crate) fn schedule_autonomous_new_view_timeouts(
        &mut self,
        now: Instant,
        active_view: wire::View,
        base_timeout: Duration,
    ) -> Result<(), V2LaneWorkError> {
        if base_timeout.is_zero() {
            return Err(V2LaneWorkError::InvalidContext(
                "autonomous NewView timeout must be positive".to_owned(),
            ));
        }
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        let incomplete_proposals = self
            .lane_sessions
            .proposals_without_commit_qc()
            .into_iter()
            .map(|proposal| proposal.proposal_hash)
            .collect::<BTreeSet<_>>();
        let clocks = self
            .autonomous_new_view_started_at
            .iter()
            .map(|(key, (view, started_at))| (*key, *view, *started_at))
            .collect::<Vec<_>>();

        for (key, clock_view, started_at) in clocks {
            let Some(payload) = self.autonomous_payloads.get(&key).cloned() else {
                self.autonomous_new_view_started_at.remove(&key);
                continue;
            };
            let proposal = &payload.origin_proposal;
            let descriptor = &proposal.descriptor;
            if !incomplete_proposals.contains(&proposal.proposal_hash)
                || !self.voting_enabled
                || self.local_peer.public_key().try_algorithm().ok() != Some(Algorithm::BlsNormal)
                || !descriptor.validator_set.contains(&self.local_peer)
                || !self.autonomous_origin_matches_context(proposal, active_view)
                || (self.decision_pending() && !self.proposal_is_bound_to_decided_carrier(proposal))
            {
                self.autonomous_new_view_started_at.remove(&key);
                continue;
            }
            if self
                .kura
                .read_autonomous_lane_slot_retirement(
                    descriptor.lane_id,
                    descriptor.lane_block_height,
                    self.native_chain_id_hash(),
                    self.context.epoch,
                )
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?
                .is_some()
            {
                self.autonomous_new_view_started_at.remove(&key);
                continue;
            }
            let Some(memory_view) = self.autonomous_payload_views.get(&key).copied() else {
                return Err(V2LaneWorkError::Persistence(
                    "active autonomous payload lacks its volatile NewView cursor".to_owned(),
                ));
            };
            if memory_view != clock_view {
                return Err(V2LaneWorkError::Persistence(
                    "autonomous NewView clock differs from the installed cursor".to_owned(),
                ));
            }
            if now.saturating_duration_since(started_at)
                < autonomous_new_view_timeout(base_timeout, clock_view)
            {
                continue;
            }

            let (durable_payload, durable_source) = self
                .kura
                .current_autonomous_lane_payload(
                    descriptor.lane_id,
                    descriptor.lane_block_height,
                    self.native_chain_id_hash(),
                    self.context.epoch,
                )
                .ok_or_else(|| {
                    V2LaneWorkError::Persistence(
                        "active autonomous NewView clock lacks its exact durable payload"
                            .to_owned(),
                    )
                })?;
            if durable_payload != payload || durable_source.descriptor.lane_block_view != clock_view
            {
                return Err(V2LaneWorkError::Persistence(
                    "active autonomous NewView clock differs from Kura's authoritative cursor"
                        .to_owned(),
                ));
            }
            let target_view = clock_view.checked_add(1).ok_or_else(|| {
                V2LaneWorkError::InvalidContext(
                    "autonomous NewView cursor exhausted its view space".to_owned(),
                )
            })?;
            let body = crate::lane_consensus::LaneBlockNewViewBodyV1::for_transition(
                &durable_source,
                &durable_payload,
                target_view,
                self.native_chain_id_hash(),
                self.context.epoch,
            )
            .map_err(|error| {
                V2LaneWorkError::InvalidContext(format!(
                    "failed to derive autonomous NewView timeout body: {error}"
                ))
            })?;
            if !self.autonomous_new_view_transition_is_current(&body, active_view) {
                return Err(V2LaneWorkError::InvalidContext(
                    "autonomous NewView timeout body failed current-state revalidation".to_owned(),
                ));
            }

            let vote = if let Some(vote) = self
                .autonomous_new_view_votes
                .votes_for_signer(&self.local_peer)
                .into_iter()
                .find(|vote| vote.body == body)
            {
                vote
            } else {
                crate::lane_consensus::LaneBlockNewViewVoteV1::new_signed(
                    body,
                    self.local_peer.clone(),
                    self.key_pair.private_key(),
                )
                .map_err(|error| {
                    V2LaneWorkError::InvalidContext(format!(
                        "failed to sign autonomous NewView timeout vote: {error}"
                    ))
                })?
            };
            let local_peer = self.local_peer.clone();
            match self.try_insert_autonomous_new_view_vote(
                vote.clone(),
                Some(&local_peer),
                active_view,
                now,
            )? {
                V2LaneIngressOutcome::Inserted | V2LaneIngressOutcome::Duplicate => {
                    self.fanout_lane_message(
                        BlockMessage::LaneBlockNewViewVote(vote),
                        &descriptor.validator_set,
                    );
                }
                V2LaneIngressOutcome::Rejected => {
                    return Err(V2LaneWorkError::InvalidContext(
                        "locally derived autonomous NewView vote was rejected".to_owned(),
                    ));
                }
            }
        }
        operation.complete();
        Ok(())
    }

    /// Re-enqueue bounded lane artifacts, Native AMX requests, and merge shares
    /// with rotating class priority for reliable retransmission.
    ///
    /// # Errors
    ///
    /// Returns a restart-required or durable-persistence error before this
    /// process may publish any later consensus output.
    pub(crate) fn schedule_retransmission(&mut self) -> Result<(), V2LaneWorkError> {
        self.schedule_retransmission_at(Instant::now())
    }

    fn schedule_retransmission_at(&mut self, now: Instant) -> Result<(), V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        let _ = self.service_next_certified_merge_sidecar_materialization(now)?;
        let sidecar_posts = self
            .merge_sidecars
            .tick_bounded(&self.local_peer, now, self.sidecar_effect_slots())
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        for post in sidecar_posts {
            self.push_merge_sidecar_post_or_restart(post)?;
        }

        if self.decision_pending() {
            self.collect_committed_lane_sessions();
            if let Some((_, _, Some(decided))) = self.retained_merge_carrier_state {
                self.retain_committed_lane_outputs_for_subject(decided);
            }
            self.purge_queued_global_body_effects_except_committed_outputs();
            self.drive_lane_sessions();
            self.schedule_lane_artifact_retransmissions();
            self.schedule_committed_lane_outputs();
            operation.complete();
            return Ok(());
        }

        let active_merge_view = self
            .pre_apply_unlocked_merge_view()
            .filter(|_| self.merge_parent_frontier_is_exact());
        if let Some(view) = active_merge_view {
            // Revisit the exact leader-selected value on the bounded
            // retransmission cadence. Autonomous execution candidates remain
            // subject to exact carrier-context validation and deterministic
            // follower re-execution before authorization.
            self.refresh_merge_candidates(view)?;
        } else {
            self.purge_queued_merge_broadcasts();
        }
        const REGULAR_RETRANSMIT_CLASS_COUNT: usize = 4;
        let start = self.regular_retransmit_class_cursor % REGULAR_RETRANSMIT_CLASS_COUNT;
        for offset in 0..REGULAR_RETRANSMIT_CLASS_COUNT {
            match (start + offset) % REGULAR_RETRANSMIT_CLASS_COUNT {
                0 => self.schedule_lane_artifact_retransmissions(),
                1 => self.schedule_native_retransmissions(),
                2 => {
                    if let Some(view) = active_merge_view {
                        self.schedule_merge_share_retransmissions(view)?;
                    }
                }
                3 => {
                    let committee = self
                        .lane_drain_votes
                        .active_body()
                        .map(|body| body.intent.validator_set.clone());
                    if let Some(committee) = committee {
                        self.schedule_lane_drain_vote_retransmission(&committee);
                    }
                }
                _ => unreachable!("regular retransmission class is modulo four"),
            }
        }
        self.regular_retransmit_class_cursor = (start + 1) % REGULAR_RETRANSMIT_CLASS_COUNT;

        let Some(active_merge_view) = active_merge_view else {
            operation.complete();
            return Ok(());
        };
        // Quorum formation and Kura publication are separate durability
        // boundaries. Revisit already-quorate candidates on the bounded
        // cadence; any publication failure poisons the process-wide output
        // guard instead of permitting this process to continue signing.
        let merge_keys = self
            .merge_entries
            .keys()
            .filter(|key| key.view == active_merge_view)
            .copied()
            .collect::<Vec<_>>();
        for key in merge_keys {
            self.try_commit_merge(key)?;
        }
        operation.complete();
        Ok(())
    }

    fn schedule_lane_artifact_retransmissions(&mut self) {
        // Peer-queue admission is only a volatile delivery boundary. Begin a
        // fresh bounded fanout round after the previous round transferred all
        // destinations, so loss of an authenticated transport tenure after enqueue
        // cannot permanently erase the final lane certificate. Once Decision
        // is installed, the decision branch above keeps starting bounded
        // rounds only for the exact decided-lane ownerships until their
        // certificates and application receipts cross the durable boundary.
        let committed_proposals = self
            .committed_lane_outputs
            .iter()
            .map(|output| output.session.proposal.proposal_hash)
            .collect::<BTreeSet<_>>();
        let commit_handoff_is_queued = self.effects.iter().any(|effect| {
            matches!(
                effect,
                V2LaneWorkEffect::PostLaneBlock {
                    message: BlockMessage::LaneBlockQc(qc),
                    ..
                } if qc.body.phase == CertPhase::Commit
                    && committed_proposals.contains(&qc.body.proposal_hash)
            )
        });
        if !self.committed_lane_outputs.is_empty()
            && !commit_handoff_is_queued
            && self
                .committed_lane_outputs
                .iter()
                .all(|output| output.next_validator >= output.session.commit_qc.validator_set.len())
        {
            for output in &mut self.committed_lane_outputs {
                output.next_validator = 0;
            }
        }
        self.schedule_committed_lane_outputs();
        let mut lane_artifacts = Vec::new();
        let global_committee = self.frozen_validator_set();
        for payload in self.pending_autonomous_anchor_payloads.values() {
            if payload.producer != self.local_peer
                || payload.origin_proposal.descriptor.proposal_height != self.context.height
                || self.globally_locked_body.is_some()
                || self.decision_pending()
            {
                continue;
            }
            lane_artifacts.push((
                BlockMessage::LaneExecutablePayload(payload.clone()),
                global_committee.clone(),
            ));
        }
        for payload in self.autonomous_payloads.values() {
            if payload.producer != self.local_peer
                || payload.origin_proposal.descriptor.proposal_height != self.context.height
                || (self.decision_pending()
                    && !self.proposal_is_bound_to_decided_carrier(&payload.origin_proposal))
            {
                continue;
            }
            lane_artifacts.push((
                BlockMessage::LaneExecutablePayload(payload.clone()),
                payload.origin_proposal.descriptor.validator_set.clone(),
            ));
        }
        let incomplete_proposal_hashes = self
            .lane_sessions
            .proposals_without_commit_qc()
            .into_iter()
            .map(|proposal| proposal.proposal_hash)
            .collect::<BTreeSet<_>>();
        for vote in self
            .autonomous_new_view_votes
            .votes_for_signer(&self.local_peer)
        {
            let key = AutonomousLanePayloadKey::from(&vote.body);
            let Some(payload) = self.autonomous_payloads.get(&key) else {
                continue;
            };
            if self.autonomous_payload_views.get(&key) != Some(&vote.body.from_view)
                || !incomplete_proposal_hashes.contains(&payload.origin_proposal.proposal_hash)
                || (self.decision_pending()
                    && !self.proposal_is_bound_to_decided_carrier(&payload.origin_proposal))
            {
                continue;
            }
            lane_artifacts.push((
                BlockMessage::LaneBlockNewViewVote(vote),
                payload.origin_proposal.descriptor.validator_set.clone(),
            ));
        }
        for payload in self.autonomous_payloads.values() {
            let proposal = &payload.origin_proposal;
            let descriptor = &proposal.descriptor;
            if !incomplete_proposal_hashes.contains(&proposal.proposal_hash)
                || !descriptor.validator_set.contains(&self.local_peer)
                || (self.decision_pending() && !self.proposal_is_bound_to_decided_carrier(proposal))
            {
                continue;
            }
            let Some(current_view) = self
                .autonomous_payload_views
                .get(&AutonomousLanePayloadKey::from(proposal))
                .copied()
            else {
                continue;
            };
            let Some(artifact) = self.kura.read_autonomous_lane_block_artifact(
                descriptor.lane_id,
                descriptor.lane_block_height,
                self.native_chain_id_hash(),
                self.context.epoch,
            ) else {
                continue;
            };
            if artifact.executable_payload != *payload {
                continue;
            }
            let Some(durable) =
                Self::latest_durable_autonomous_new_view_certificate(&artifact, current_view)
            else {
                continue;
            };
            lane_artifacts.push((
                BlockMessage::LaneBlockNewViewCertificate(durable.certificate.clone()),
                durable.certificate.validator_set.clone(),
            ));
        }
        for proposal in self.lane_sessions.proposals_without_commit_qc() {
            if proposal.descriptor.proposal_height != self.context.height
                || (self.decision_pending()
                    && !self.proposal_is_bound_to_decided_carrier(&proposal))
                || !self.proposal_body_available(&proposal)
            {
                continue;
            }
            lane_artifacts.push((
                BlockMessage::LaneBlockProposal(proposal.clone()),
                proposal.descriptor.validator_set,
            ));
        }
        for (proposal, vote) in self
            .lane_sessions
            .local_vote_rebroadcast_artifacts_for(&self.local_peer)
        {
            if proposal.descriptor.proposal_height != self.context.height
                || (self.decision_pending()
                    && !self.proposal_is_bound_to_decided_carrier(&proposal))
                || !self.proposal_body_available(&proposal)
            {
                continue;
            }
            lane_artifacts.push((
                BlockMessage::LaneBlockVote(vote),
                proposal.descriptor.validator_set,
            ));
        }
        for qc in self.lane_sessions.qcs_for_incomplete_sessions() {
            if qc.body.proposal_height != self.context.height
                || (self.decision_pending()
                    && !self.lane_message_is_allowed_after_decision(&BlockMessage::LaneBlockQc(
                        qc.clone(),
                    )))
                || !self.lane_vote_body_available(&qc.body)
            {
                continue;
            }
            let validators = qc.validator_set.clone();
            lane_artifacts.push((BlockMessage::LaneBlockQc(qc), validators));
        }
        if !lane_artifacts.is_empty() {
            let start = self.lane_artifact_cursor % lane_artifacts.len();
            let mut advanced = 0usize;
            for offset in 0..lane_artifacts.len() {
                let (message, validators) =
                    &lane_artifacts[(start + offset) % lane_artifacts.len()];
                self.fanout_lane_message(message.clone(), validators);
                advanced = advanced.saturating_add(1);
                if self.effects.len() >= self.limits.effect_capacity.get() {
                    break;
                }
            }
            self.lane_artifact_cursor = (start + advanced.max(1)) % lane_artifacts.len();
        }
    }

    fn schedule_native_retransmissions(&mut self) {
        let requests = self
            .native_requests
            .iter()
            .map(|(key, message)| (key.peer.clone(), message.clone()))
            .collect::<Vec<_>>();
        if !requests.is_empty() {
            let start = self.native_retransmit_cursor % requests.len();
            let mut advanced = 0usize;
            for offset in 0..requests.len() {
                let (peer, message) = requests[(start + offset) % requests.len()].clone();
                if !self.push_effect(V2LaneWorkEffect::PostNativeAmx {
                    peer,
                    reply_routes: None,
                    message,
                }) {
                    break;
                }
                advanced = advanced.saturating_add(1);
            }
            self.native_retransmit_cursor = (start + advanced.max(1)) % requests.len();
        }
    }

    fn schedule_merge_share_retransmissions(
        &mut self,
        active_merge_view: wire::View,
    ) -> Result<(), V2LaneWorkError> {
        let mut merge_effects = Vec::new();
        if let Some(local_index) = self.local_validator_index() {
            for (key, pending) in &self.merge_entries {
                if key.view != active_merge_view {
                    continue;
                }
                let Some(signature) = pending.signatures.get(&local_index) else {
                    continue;
                };
                let candidate = match &pending.stage {
                    PendingMergeStage::Collecting(candidate) => candidate.clone(),
                    PendingMergeStage::Certified(entry) => {
                        crate::merge::MergeLedgerCandidate::from(entry)
                    }
                };
                merge_effects.push(V2LaneWorkEffect::BroadcastMerge(self.local_merge_share(
                    *key,
                    &candidate,
                    local_index,
                    signature.clone(),
                )?));
            }
        }
        for effect in merge_effects {
            self.push_effect(effect);
        }
        Ok(())
    }

    fn sidecar_effect_slots(&self) -> usize {
        let progress_effects = self
            .sidecar_effects
            .iter()
            .filter(|effect| retryable_sidecar_server_control_peer(effect).is_none())
            .count();
        self.limits
            .relay_capacity
            .get()
            .saturating_sub(progress_effects)
    }

    fn next_sidecar_effect_selection(&self) -> Option<(usize, bool)> {
        let progress = self
            .sidecar_effects
            .iter()
            .position(|effect| retryable_sidecar_server_control_peer(effect).is_none())
            .map(|index| (index, false));
        let retryable_control = self
            .sidecar_effects
            .iter()
            .position(|effect| retryable_sidecar_server_control_peer(effect).is_some())
            .map(|index| (index, true));
        match (progress, retryable_control) {
            (Some(progress), Some(retryable_control)) => {
                if self.sidecar_progress_drain_credit == 0 {
                    Some(retryable_control)
                } else {
                    Some(progress)
                }
            }
            (Some(progress), None) => Some(progress),
            (None, Some(retryable_control)) => Some(retryable_control),
            (None, None) => None,
        }
    }

    fn push_merge_sidecar_post(&mut self, post: MergeSidecarPost) -> bool {
        let MergeSidecarPost {
            peer,
            reply_route,
            message,
        } = post;
        let reply_routes = match reply_route {
            Some(reply_route) => {
                let Ok(reply_routes) = NetworkReplyRoutes::try_from_route(reply_route) else {
                    return false;
                };
                Some(reply_routes)
            }
            None => None,
        };
        self.push_merge_sidecar_effect(V2LaneWorkEffect::PostCertifiedMergeSidecar {
            peer,
            reply_routes,
            message,
        })
    }

    /// Transfer an already-reserved sidecar post into the lane effect queue.
    ///
    /// Request and chunk posts advance transport ownership before this
    /// boundary, so their transfer must execute in every build and fail closed
    /// if the reserved queue cannot retain it. Request production can be
    /// rolled back exactly; chunk production remains protected until its exact
    /// peer-writer-flush receipt is applied. Stateless GenerationHint and
    /// durable-prefix CloseAck responses are instead reproducible by replay and
    /// may be dropped by their bounded responder-control corridor.
    fn push_merge_sidecar_post_or_restart(
        &mut self,
        post: MergeSidecarPost,
    ) -> Result<(), V2LaneWorkError> {
        let retired_response_route = match (post.message.as_ref(), &post.reply_route) {
            (
                CertifiedMergeSidecarMessage::Chunk(_) | CertifiedMergeSidecarMessage::CloseAck(_),
                Some(route),
            ) => Some(route.clone()),
            _ => None,
        };
        let unsent_request = match post.message.as_ref() {
            CertifiedMergeSidecarMessage::Request(request) => Some(request.clone()),
            CertifiedMergeSidecarMessage::Close(_)
            | CertifiedMergeSidecarMessage::CloseAck(_)
            | CertifiedMergeSidecarMessage::GenerationHint(_)
            | CertifiedMergeSidecarMessage::Chunk(_) => None,
        };
        let retryable_server_control = matches!(
            post.message.as_ref(),
            CertifiedMergeSidecarMessage::CloseAck(_)
                | CertifiedMergeSidecarMessage::GenerationHint(_)
        );
        if self.push_merge_sidecar_post(post) {
            return Ok(());
        }
        if retryable_server_control {
            // Both responses are exactly reproducible from a retransmitted
            // authenticated Request or Close. Before worker handoff they own
            // no writer state, so bounded output pressure may drop them
            // without fail-stop.
            return Ok(());
        }
        if retired_response_route.is_some_and(|route| !route.is_active()) {
            // The sidecar transport still owns the in-flight current chunk.
            // Its next bounded prune records that cursor for a reconnect; one
            // retired source must not poison live siblings already drained in
            // the same service slice.
            return Ok(());
        }
        if let Some(request) = unsent_request {
            self.merge_sidecars
                .release_unsent_request(&request)
                .map_err(|_| V2LaneWorkError::RestartRequired)?;
        }
        Err(V2LaneWorkError::RestartRequired)
    }

    /// Apply one exact peer-writer flush receipt and schedule the source's next
    /// chunk without changing any sibling source cursor.
    pub(crate) fn acknowledge_certified_merge_sidecar_chunk_admission(
        &mut self,
        admission: &CertifiedMergeSidecarChunkAdmission,
        now: Instant,
    ) -> Result<(), V2LaneWorkError> {
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        let acknowledged = self
            .merge_sidecars
            .acknowledge_outbound_chunk(admission, now)
            .map_err(|_| V2LaneWorkError::RestartRequired)?;
        if acknowledged {
            self.remove_acknowledged_sidecar_retry_effect(admission);
        }
        let _ = self.service_next_certified_merge_sidecar_materialization(now)?;
        let posts = self
            .merge_sidecars
            .drain_outbound_chunks_durable(
                self.sidecar_effect_slots()
                    .min(self.limits.sidecar_service_burst.get()),
                now,
            )
            .map_err(|_| V2LaneWorkError::RestartRequired)?;
        for post in posts {
            self.push_merge_sidecar_post_or_restart(post)?;
        }
        operation.complete();
        Ok(())
    }

    fn remove_acknowledged_sidecar_retry_effect(
        &mut self,
        admission: &CertifiedMergeSidecarChunkAdmission,
    ) {
        let mut retained = VecDeque::with_capacity(self.sidecar_effects.len());
        while let Some(mut effect) = self.sidecar_effects.pop_front() {
            let mut keep = true;
            if let V2LaneWorkEffect::PostCertifiedMergeSidecar {
                reply_routes: Some(reply_routes),
                message,
                ..
            } = &mut effect
                && matches!(message.as_ref(), CertifiedMergeSidecarMessage::Chunk(_))
                && admission.matches_materialized_chunk(message)
            {
                let completed_sources = reply_routes
                    .iter()
                    .filter(|route| admission.is_bound_to_source(route))
                    .map(NetworkReplyRoute::source_key)
                    .collect::<Vec<_>>();
                for source in completed_sources {
                    let removed = reply_routes.remove_completed_source(&source);
                    debug_assert!(removed);
                }
                keep = !reply_routes.is_empty();
            }
            if keep {
                retained.push_back(effect);
            }
        }
        self.sidecar_effects = retained;
        self.sidecar_effect_keys = self
            .sidecar_effects
            .iter()
            .map(lane_work_effect_key)
            .collect();
    }

    fn apply_closed_server_prefixes(&mut self) -> bool {
        let mut changed = false;
        for prefix in self.merge_sidecars.drain_closed_server_prefixes() {
            let requester = prefix.requester.clone();
            changed |= self.coalesce_closed_sidecar_prefix(prefix.clone());
            let effects_before = self.sidecar_effects.len();
            self.sidecar_effects.retain(|effect| {
                !matches!(
                    effect,
                    V2LaneWorkEffect::PostCertifiedMergeSidecar { message, .. }
                        if matches!(
                            message.as_ref(),
                            CertifiedMergeSidecarMessage::Chunk(chunk)
                                if chunk.requester == requester
                                    && (chunk.service_generation < prefix.service_generation
                                        || (chunk.service_generation
                                            == prefix.service_generation
                                            && (chunk.stream_epoch < prefix.stream_epoch
                                                || (chunk.stream_epoch == prefix.stream_epoch
                                                    && chunk.semantic_sequence.get()
                                                        <= prefix.closed_through))))
                        )
                )
            });
            changed |= self.sidecar_effects.len() != effects_before;
        }
        self.sidecar_effect_keys = self
            .sidecar_effects
            .iter()
            .map(lane_work_effect_key)
            .collect();
        changed
    }

    fn coalesce_closed_sidecar_prefix(
        &mut self,
        prefix: CertifiedMergeSidecarClosedPrefix,
    ) -> bool {
        let requester = prefix.requester.clone();
        match self.closed_sidecar_prefixes.get_mut(&requester) {
            Some(retained) if prefix.covers(retained) => {
                if retained == &prefix {
                    false
                } else {
                    *retained = prefix;
                    true
                }
            }
            Some(retained) if retained.covers(&prefix) => false,
            Some(retained) => {
                debug_assert_eq!(retained.service_generation, prefix.service_generation);
                debug_assert_eq!(retained.stream_epoch, prefix.stream_epoch);
                if prefix.closed_through <= retained.closed_through {
                    false
                } else {
                    retained.closed_through = prefix.closed_through;
                    true
                }
            }
            None => {
                self.closed_sidecar_prefixes.insert(requester, prefix);
                true
            }
        }
    }

    /// Drain authenticated close prefixes for the worker exact-output owner.
    pub(crate) fn drain_closed_sidecar_prefixes(
        &mut self,
    ) -> Vec<CertifiedMergeSidecarClosedPrefix> {
        std::mem::take(&mut self.closed_sidecar_prefixes)
            .into_iter()
            .map(|(_, prefix)| prefix)
            .collect()
    }

    /// Restore a failed exact-output handoff suffix for an ordered retry.
    ///
    /// Prefixes which arrived after the failed drain are coalesced by the same
    /// lexicographic generation/epoch/floor relation as ordinary ingress.
    pub(crate) fn requeue_closed_sidecar_prefixes(
        &mut self,
        prefixes: impl IntoIterator<Item = CertifiedMergeSidecarClosedPrefix>,
    ) {
        for prefix in prefixes {
            let _ = self.coalesce_closed_sidecar_prefix(prefix);
        }
    }

    /// Confirm that drained sidecar prefixes have terminated every covered
    /// exact-output fanout and writer-flush receipt.
    pub(crate) fn confirm_closed_sidecar_prefix_handoff(&mut self) {
        self.merge_sidecars.confirm_closed_server_prefix_handoff();
    }

    fn stranded_retryable_sidecar_control_index(
        &self,
        candidate: &V2LaneWorkEffect,
    ) -> Option<usize> {
        let candidate_peer = retryable_sidecar_server_control_peer(candidate)?;
        if !retryable_sidecar_server_control_has_writable_route(candidate) {
            return None;
        }
        self.sidecar_effects.iter().position(|retained| {
            retryable_sidecar_server_control_peer(retained) == Some(candidate_peer)
                && !retryable_sidecar_server_control_has_writable_route(retained)
        })
    }

    fn replace_stranded_retryable_sidecar_control(
        &mut self,
        retained_index: usize,
        candidate_key: Hash,
        candidate: V2LaneWorkEffect,
    ) -> bool {
        let Some(retained) = self.sidecar_effects.remove(retained_index) else {
            return false;
        };
        let retained_key = lane_work_effect_key(&retained);
        if !self.sidecar_effect_keys.remove(&retained_key) {
            self.sidecar_effects.insert(retained_index, retained);
            return false;
        }
        if !self.sidecar_effect_keys.insert(candidate_key) {
            self.sidecar_effect_keys.insert(retained_key);
            self.sidecar_effects.insert(retained_index, retained);
            return false;
        }
        // This is new authenticated-source work, so it rejoins at the tail
        // instead of inheriting the stranded occurrence's queue age.
        self.sidecar_effects.push_back(candidate);
        true
    }

    fn push_merge_sidecar_effect(&mut self, effect: V2LaneWorkEffect) -> bool {
        if !matches!(&effect, V2LaneWorkEffect::PostCertifiedMergeSidecar { .. })
            || !lane_work_effect_reply_routes_have_valid_shape(&effect)
        {
            return false;
        }
        let key = lane_work_effect_key(&effect);
        if self.sidecar_effect_keys.contains(&key) {
            let Some(index) = self
                .sidecar_effects
                .iter()
                .position(|queued| lane_work_effect_key(queued) == key)
            else {
                return false;
            };
            if self
                .sidecar_effects
                .get_mut(index)
                .is_some_and(|queued| merge_lane_work_effect_reply_routes(queued, &effect))
            {
                return true;
            }
            if !lane_work_effect_reply_routes_are_valid(&effect)
                || self.stranded_retryable_sidecar_control_index(&effect) != Some(index)
            {
                return false;
            }
            return self.replace_stranded_retryable_sidecar_control(index, key, effect);
        }
        if !lane_work_effect_reply_routes_are_valid(&effect) {
            return false;
        }
        let retryable_peer = retryable_sidecar_server_control_peer(&effect).cloned();
        if let Some(peer) = &retryable_peer {
            if let Some(index) = self.stranded_retryable_sidecar_control_index(&effect) {
                return self.replace_stranded_retryable_sidecar_control(index, key, effect);
            }
            if self
                .sidecar_effects
                .iter()
                .any(|queued| retryable_sidecar_server_control_peer(queued) == Some(peer))
            {
                return false;
            }
            if self.sidecar_effects.len() >= self.limits.relay_capacity.get() {
                return false;
            }
        } else {
            if self.sidecar_effect_slots() == 0 {
                return false;
            }
            if self.sidecar_effects.len() >= self.limits.relay_capacity.get() {
                let Some(index) = self
                    .sidecar_effects
                    .iter()
                    .rposition(|queued| retryable_sidecar_server_control_peer(queued).is_some())
                else {
                    return false;
                };
                let evicted = self
                    .sidecar_effects
                    .remove(index)
                    .expect("located retryable sidecar control remains queued");
                self.sidecar_effect_keys
                    .remove(&lane_work_effect_key(&evicted));
            }
        }
        self.sidecar_effect_keys.insert(key);
        self.sidecar_effects.push_back(effect);
        true
    }

    fn accept_certified_merge_sidecar(
        &mut self,
        sender: PeerId,
        reply_route: Option<NetworkReplyRoute>,
        message: CertifiedMergeSidecarMessage,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        match message {
            CertifiedMergeSidecarMessage::Request(request) => {
                self.accept_certified_merge_sidecar_request(sender, reply_route, request)
            }
            CertifiedMergeSidecarMessage::Close(close) => {
                self.accept_certified_merge_sidecar_close(sender, reply_route, close)
            }
            CertifiedMergeSidecarMessage::CloseAck(ack) => {
                self.accept_certified_merge_sidecar_close_ack(sender, reply_route, &ack)
            }
            CertifiedMergeSidecarMessage::GenerationHint(hint) => {
                self.accept_certified_merge_sidecar_generation_hint(sender, reply_route, &hint)
            }
            CertifiedMergeSidecarMessage::Chunk(chunk) => {
                self.accept_certified_merge_sidecar_chunk(sender, chunk)
            }
        }
    }

    #[cfg(test)]
    pub(in crate::sumeragi) fn accept_certified_merge_sidecar_for_test(
        &mut self,
        sender: PeerId,
        reply_route: NetworkReplyRoute,
        request: crate::merge_sidecar::CertifiedMergeSidecarRequestV1,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        self.accept_certified_merge_sidecar(
            sender,
            Some(reply_route),
            CertifiedMergeSidecarMessage::Request(request),
        )
    }

    #[cfg(test)]
    pub(in crate::sumeragi) fn transition_merge_sidecar_responder_roster_for_test(
        &mut self,
        server_roster: &[PeerId],
    ) -> Result<(), MergeSidecarError> {
        self.merge_sidecars
            .transition_server_service_generation_for_test(server_roster)
    }

    /// Authenticate one local serving decision against the QC-selected carrier.
    ///
    /// A current-height entry is still speculative and therefore uses the live
    /// frozen context. Once this adapter has advanced, only Kura's verified
    /// finality and its exact canonical stripped block may select the historical
    /// context and compact reference; the requester contributes no height or
    /// roster authority.
    fn authenticates_certified_merge_sidecar_service(
        &self,
        entry: &MergeLedgerEntry,
        reference: &CertifiedMergeLedgerReference,
    ) -> bool {
        let carrier_height = entry.merge_qc.carrier_height;
        if carrier_height == 0 || carrier_height > self.context.height {
            return false;
        }
        if carrier_height == self.context.height {
            return merge_entry_has_exact_carrier_binding(&self.context, entry)
                && authenticate_merge_entry_for_height_context(&self.context, entry).is_ok();
        }

        let Ok(Some(finality)) = self.kura.v2_finality_artifact(carrier_height) else {
            return false;
        };
        let Some(carrier_height) = usize::try_from(carrier_height)
            .ok()
            .and_then(NonZeroUsize::new)
        else {
            return false;
        };
        let Some(block) = self.kura.get_block_without_merge_sidecar(carrier_height) else {
            return false;
        };
        // `v2_finality_artifact` has already verified the CommitQC and bound
        // its payload hash to Kura's separately retained canonical proposal
        // wire. Re-read the stripped body only to require the exact compact
        // reference without recursively resolving the sidecar being served.
        let historical_context = &finality.height_context;
        let canonical_reference = block
            .execution_context()
            .and_then(|context| context.merge_entry.as_ref());
        finality.height == historical_context.height
            && finality.height == block.header().height().get()
            && historical_context.chain_id == self.context.chain_id
            && historical_context.protocol_version == self.context.protocol_version
            && block.hash() == finality.block_hash
            && finality.subject.block_hash == block.hash()
            && finality.subject.parent_block_hash == block.header().prev_block_hash()
            && canonical_reference == Some(reference)
            && entry.merge_qc.carrier_height == block.header().height().get()
            && Some(entry.merge_qc.carrier_parent_hash) == block.header().prev_block_hash()
            && entry.merge_qc.view == block.header().view_change_index()
            && merge_entry_has_exact_carrier_binding(historical_context, entry)
            && authenticate_merge_entry_for_height_context(historical_context, entry).is_ok()
    }

    /// Materialize at most one responder request selected by the transport's
    /// durable two-level round-robin scheduler.
    ///
    /// Network ingress may only make a bounded request retryable. It never
    /// owns the Kura lookup directly: this poll uses the scheduler-returned
    /// requester, request, and exact authenticated route, so a flooding relay
    /// cannot substitute its newest occurrence for older roster-owned work.
    fn service_next_certified_merge_sidecar_materialization(
        &mut self,
        now: Instant,
    ) -> Result<bool, V2LaneWorkError> {
        self.merge_sidecars
            .reclaim_inactive_outbound_attempts(now)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        let Some(materialization) = self
            .merge_sidecars
            .next_server_request_materialization(now)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?
        else {
            return Ok(false);
        };
        let requester = materialization.requester;
        let request = materialization.request;
        let reply_route = materialization.reply_route;

        let entry = match self.kura.merge_entry_by_hash(request.entry_hash) {
            Ok(Some(entry)) => entry,
            Ok(None) => {
                self.merge_sidecars
                    .retire_unmaterialized_server_request(&requester, &request)
                    .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
                return Ok(false);
            }
            Err(error) => {
                self.merge_sidecars
                    .retire_unmaterialized_server_request(&requester, &request)
                    .map_err(|retire_error| {
                        V2LaneWorkError::Persistence(retire_error.to_string())
                    })?;
                iroha_logger::warn!(
                    %requester,
                    ?error,
                    "v2 merge-sidecar Kura read failed; retired the exact materialization gate"
                );
                return Ok(false);
            }
        };
        let reference = CertifiedMergeLedgerReference::new(&entry);
        let metadata_matches = request.encoded_len == reference.encoded_len
            && request.epoch_id == reference.epoch_id
            && request.reference_digest == certified_merge_reference_digest(&reference);
        if !metadata_matches {
            self.merge_sidecars
                .retire_unmaterialized_server_request(&requester, &request)
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            return Ok(false);
        }
        let local_is_holder = self
            .authenticates_certified_merge_sidecar_service(&entry, &reference)
            && certified_merge_sidecar_holders(&reference)
                .is_ok_and(|holders| holders.contains(&self.local_peer));
        if !local_is_holder {
            self.merge_sidecars
                .retire_unmaterialized_server_request(&requester, &request)
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            return Ok(false);
        }

        let selected_reply_route = reply_route.clone();
        match self.merge_sidecars.enqueue_response(
            request.clone(),
            reply_route,
            entry.canonical_bytes(),
            now,
        ) {
            Ok(()) => Ok(true),
            Err(MergeSidecarError::Capacity("outbound response budget")) => {
                self.merge_sidecars
                    .cancel_unmaterialized_server_request(&requester, &request);
                iroha_logger::debug!(
                    %requester,
                    "v2 merge-sidecar response budget deferred fair materialization"
                );
                Ok(false)
            }
            Err(MergeSidecarError::UnsolicitedResponse)
                if selected_reply_route
                    .as_ref()
                    .is_some_and(|route| !route.is_active()) =>
            {
                // The exact writer tenure may retire after selection but
                // before the Kura lookup finishes. Preserve the durable
                // pending cursor; a later authenticated route can retry it.
                self.merge_sidecars
                    .cancel_unmaterialized_server_request(&requester, &request);
                Ok(false)
            }
            Err(error @ MergeSidecarError::LifecycleJournal(_)) => {
                Err(V2LaneWorkError::Persistence(error.to_string()))
            }
            Err(error) => {
                iroha_logger::error!(
                    %requester,
                    ?error,
                    "fair v2 merge-sidecar materialization violated its admitted invariant"
                );
                Err(V2LaneWorkError::RestartRequired)
            }
        }
    }

    fn accept_certified_merge_sidecar_request(
        &mut self,
        sender: PeerId,
        reply_route: Option<NetworkReplyRoute>,
        request: crate::merge_sidecar::CertifiedMergeSidecarRequestV1,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        // Admission is owned by the semantic requester, not by an
        // authenticated relay/hub carrying its reply route.  Reject outsiders
        // before the transport can allocate a stream, gate, route attempt, or
        // materialization slot.
        if !self.frozen_roster_contains(&sender) {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let Some(reply_route) = reply_route else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        let now = Instant::now();
        let admission = match self.merge_sidecars.admit_server_request(
            &sender,
            &request,
            Some(&reply_route),
            &self.local_peer,
            now,
        ) {
            Ok(admission) => admission,
            Err(error @ MergeSidecarError::LifecycleJournal(_)) => {
                return Err(V2LaneWorkError::Persistence(error.to_string()));
            }
            Err(error) => {
                iroha_logger::debug!(%sender, ?error, "dropping v2 certified merge-sidecar request");
                return Ok(V2LaneIngressOutcome::Rejected);
            }
        };
        let ingress_selected = matches!(&admission, ServerRequestAdmission::Materialize);
        if let ServerRequestAdmission::GenerationHint(post) = admission {
            // Stale-generation probes are stateless. Generation rollover
            // persists its new fence inside the transport before returning
            // this same outcome, so neither case requires a second snapshot.
            // A full output queue may drop the retryable Hint without
            // fail-stop: the requester will retransmit the stale occurrence
            // and receive the same durable fence.
            let _ = self.apply_closed_server_prefixes();
            return Ok(if self.push_merge_sidecar_post(post) {
                V2LaneIngressOutcome::Inserted
            } else {
                V2LaneIngressOutcome::Duplicate
            });
        }
        self.merge_sidecars
            .persist_lifecycle_state()
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        let _ = self.apply_closed_server_prefixes();
        let materialized = self.service_next_certified_merge_sidecar_materialization(now)?;
        if ingress_selected && !materialized {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let posts = self
            .merge_sidecars
            .drain_outbound_chunks_durable(
                self.sidecar_effect_slots()
                    .min(self.limits.sidecar_service_burst.get()),
                now,
            )
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        let inserted = !posts.is_empty();
        for post in posts {
            self.push_merge_sidecar_post_or_restart(post)?;
        }
        Ok(if inserted {
            V2LaneIngressOutcome::Inserted
        } else {
            V2LaneIngressOutcome::Duplicate
        })
    }

    fn accept_certified_merge_sidecar_close(
        &mut self,
        sender: PeerId,
        reply_route: Option<NetworkReplyRoute>,
        close: CertifiedMergeSidecarCloseV1,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        // A standalone Close may create a server stream even when no request
        // gate exists.  Bind that allocation to the frozen semantic roster;
        // the authenticated relay source is deliberately not admission
        // authority.
        if !self.frozen_roster_contains(&sender) {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let Some(reply_route) = reply_route else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        if !reply_route.is_active() || reply_route.semantic_target() != &sender {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let ack = match self.merge_sidecars.admit_server_close(
            &sender,
            &close,
            Some(&reply_route),
            &self.local_peer,
        ) {
            Ok(ack) => ack,
            Err(error @ MergeSidecarError::LifecycleJournal(_)) => {
                return Err(V2LaneWorkError::Persistence(error.to_string()));
            }
            Err(error) => {
                iroha_logger::debug!(%sender, ?error, "dropping v2 merge-sidecar close");
                return Ok(V2LaneIngressOutcome::Rejected);
            }
        };
        let close_progress = self.apply_closed_server_prefixes();
        let now = Instant::now();
        let _ = self.service_next_certified_merge_sidecar_materialization(now)?;
        let posts = self
            .merge_sidecars
            .drain_outbound_chunks_durable(
                self.sidecar_effect_slots()
                    .min(self.limits.sidecar_service_burst.get()),
                now,
            )
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        let materialized_progress = !posts.is_empty();
        for post in posts {
            self.push_merge_sidecar_post_or_restart(post)?;
        }
        // Both an ordinary CloseAck and a stale-generation Hint are
        // deterministically regenerated by replaying this authenticated Close.
        // They share the bounded, coalesced responder-control corridor and can
        // be dropped under output pressure without process fail-stop.
        Ok(
            if close_progress || self.push_merge_sidecar_post(ack) || materialized_progress {
                V2LaneIngressOutcome::Inserted
            } else {
                V2LaneIngressOutcome::Duplicate
            },
        )
    }

    fn accept_certified_merge_sidecar_close_ack(
        &mut self,
        sender: PeerId,
        reply_route: Option<NetworkReplyRoute>,
        ack: &CertifiedMergeSidecarCloseAckV1,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        let Some(reply_route) = reply_route else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        if !reply_route.is_active() || reply_route.semantic_target() != &sender {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        match self
            .merge_sidecars
            .acknowledge_close(&sender, ack, &self.local_peer)
        {
            Ok(true) => Ok(V2LaneIngressOutcome::Inserted),
            Ok(false) => Ok(V2LaneIngressOutcome::Duplicate),
            Err(error @ MergeSidecarError::LifecycleJournal(_)) => {
                Err(V2LaneWorkError::Persistence(error.to_string()))
            }
            Err(error) => {
                iroha_logger::debug!(%sender, ?error, "dropping v2 merge-sidecar close ACK");
                Ok(V2LaneIngressOutcome::Rejected)
            }
        }
    }

    fn accept_certified_merge_sidecar_generation_hint(
        &mut self,
        sender: PeerId,
        reply_route: Option<NetworkReplyRoute>,
        hint: &crate::merge_sidecar::CertifiedMergeSidecarGenerationHintV1,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        let Some(reply_route) = reply_route else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        if !reply_route.is_active() || reply_route.semantic_target() != &sender {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        match self
            .merge_sidecars
            .acknowledge_generation_hint(&sender, hint, &self.local_peer)
        {
            Ok(true) => {
                self.sidecar_effects.retain(|effect| {
                    !matches!(
                        effect,
                        V2LaneWorkEffect::PostCertifiedMergeSidecar { message, .. }
                            if matches!(
                                message.as_ref(),
                                CertifiedMergeSidecarMessage::Request(request)
                                    if request.responder == sender
                                        && request.service_generation < hint.current_generation
                            ) || matches!(
                                message.as_ref(),
                                CertifiedMergeSidecarMessage::Close(close)
                                    if close.responder == sender
                                        && close.service_generation < hint.current_generation
                            )
                    )
                });
                self.sidecar_effect_keys = self
                    .sidecar_effects
                    .iter()
                    .map(lane_work_effect_key)
                    .collect();
                Ok(V2LaneIngressOutcome::Inserted)
            }
            Ok(false) => Ok(V2LaneIngressOutcome::Duplicate),
            Err(error @ MergeSidecarError::LifecycleJournal(_)) => {
                Err(V2LaneWorkError::Persistence(error.to_string()))
            }
            Err(error) => {
                iroha_logger::debug!(
                    %sender,
                    ?error,
                    "dropping v2 merge-sidecar generation Hint"
                );
                Ok(V2LaneIngressOutcome::Rejected)
            }
        }
    }

    fn accept_certified_merge_sidecar_chunk(
        &mut self,
        sender: PeerId,
        chunk: crate::merge_sidecar::CertifiedMergeSidecarChunkV1,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        let entry_hash = chunk.entry_hash;
        let now = Instant::now();
        let outcome = match self.merge_sidecars.ingest_chunk(&sender, chunk, now) {
            Ok(outcome) => outcome,
            Err(error) => {
                iroha_logger::debug!(%sender, %entry_hash, ?error, "dropping invalid v2 merge-sidecar chunk");
                return Ok(V2LaneIngressOutcome::Rejected);
            }
        };
        let ChunkIngestOutcome::Complete(completed) = outcome else {
            return Ok(V2LaneIngressOutcome::Inserted);
        };
        let reference_digest = certified_merge_reference_digest(&completed.reference);
        let entry = match decode_certified_merge_sidecar(&completed.reference, &completed.bytes) {
            Ok(entry) => entry,
            Err(error) => {
                iroha_logger::warn!(
                    %sender,
                    %entry_hash,
                    ?error,
                    "reassembled v2 certified merge sidecar is corrupt; rotating holder"
                );
                self.retry_completed_merge_sidecar(entry_hash, reference_digest, now)?;
                return Ok(V2LaneIngressOutcome::Rejected);
            }
        };
        if let Err(error) = authenticate_merge_entry_for_height_context(&self.context, &entry) {
            let affected = self
                .merge_sidecars
                .discard_invalid(entry_hash)
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            if !affected.is_empty() {
                self.rejected_merge_sidecars
                    .entry(entry_hash)
                    .or_insert(error);
            }
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        if let Err(error) = self
            .state
            .validate_certified_merge_entry_for_global_order(&entry)
        {
            let affected = self
                .merge_sidecars
                .discard_invalid(entry_hash)
                .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
            if !affected.is_empty() {
                self.rejected_merge_sidecars
                    .entry(entry_hash)
                    .or_insert_with(|| error.to_string());
            }
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        match self.kura.persist_pending_certified_merge_entry(&entry) {
            Ok(persisted_hash) if persisted_hash == entry_hash => {
                let (affected, _) = self
                    .merge_sidecars
                    .finish_completed(entry_hash, reference_digest, true, &self.local_peer, now)
                    .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
                if !affected.is_empty() {
                    self.completed_merge_sidecars.insert(entry_hash);
                }
                Ok(V2LaneIngressOutcome::Inserted)
            }
            Ok(other_hash) => Err(V2LaneWorkError::Persistence(format!(
                "Kura persisted conflicting certified merge sidecar hash {other_hash}"
            ))),
            Err(error) => Err(V2LaneWorkError::Persistence(error.to_string())),
        }
    }

    fn retry_completed_merge_sidecar(
        &mut self,
        entry_hash: HashOf<MergeLedgerEntry>,
        reference_digest: Hash,
        now: Instant,
    ) -> Result<(), V2LaneWorkError> {
        let (_, retry) = self
            .merge_sidecars
            .finish_completed(entry_hash, reference_digest, false, &self.local_peer, now)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        if let Some(post) = retry {
            self.push_merge_sidecar_post_or_restart(post)?;
        }
        Ok(())
    }

    fn round_is_current(&self, round: wire::ConsensusRound) -> bool {
        round.context_id == self.context.id() && round.height == self.context.height
    }

    fn accept_lane_relay(
        &mut self,
        envelope: LaneRelayEnvelope,
        active_view: wire::View,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        let key = (
            envelope.lane_id,
            envelope.dataspace_id,
            envelope.lane_incarnation,
            envelope.block_height,
            Hash::from(envelope.settlement_hash),
        );
        if self.admitted_relays.contains(&key) {
            return Ok(V2LaneIngressOutcome::Duplicate);
        }
        if self.admitted_relays.len() >= self.limits.relay_capacity.get() {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        match self.state.record_lane_relay(&envelope) {
            Ok(crate::state::LaneRelayInsert::Duplicate) => Ok(V2LaneIngressOutcome::Duplicate),
            Ok(
                crate::state::LaneRelayInsert::Inserted | crate::state::LaneRelayInsert::Replaced,
            ) => {
                self.admitted_relays.insert(key);
                self.refresh_merge_candidates(active_view)?;
                Ok(V2LaneIngressOutcome::Inserted)
            }
            Err(_) => Ok(V2LaneIngressOutcome::Rejected),
        }
    }

    fn insert_lane_proposal(
        &mut self,
        proposal: LaneBlockProposalV1,
        sender: Option<&PeerId>,
        local: bool,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        if !self.proposal_body_available(&proposal)
            || !self.lane_proposal_authorized(&proposal, sender, local, active_view)
        {
            return V2LaneIngressOutcome::Rejected;
        }
        match self.lane_sessions.insert_proposal(proposal) {
            Ok(LaneBlockSessionInsertOutcome::Inserted) => V2LaneIngressOutcome::Inserted,
            Ok(LaneBlockSessionInsertOutcome::Duplicate) => V2LaneIngressOutcome::Duplicate,
            Err(_) => V2LaneIngressOutcome::Rejected,
        }
    }

    fn insert_lane_vote(
        &mut self,
        vote: LaneBlockVoteV1,
        sender: Option<&PeerId>,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        if sender != Some(&vote.signer)
            || !self.lane_vote_body_available(&vote.body)
            || !self.lane_vote_authorized(&vote, active_view)
        {
            return V2LaneIngressOutcome::Rejected;
        }
        match self.lane_sessions.insert_vote(vote, sender) {
            Ok(LaneBlockSessionInsertOutcome::Inserted) => V2LaneIngressOutcome::Inserted,
            Ok(LaneBlockSessionInsertOutcome::Duplicate) => V2LaneIngressOutcome::Duplicate,
            Err(_) => V2LaneIngressOutcome::Rejected,
        }
    }

    fn insert_lane_qc(
        &mut self,
        qc: LaneBlockQcV1,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        if !self.lane_vote_body_available(&qc.body) || !self.lane_qc_authorized(&qc, active_view) {
            return V2LaneIngressOutcome::Rejected;
        }
        let pops = self.pops_for_lane_qc(&qc);
        match self.lane_sessions.insert_qc_with_pops(qc, &pops) {
            Ok(LaneBlockSessionInsertOutcome::Inserted) => V2LaneIngressOutcome::Inserted,
            Ok(LaneBlockSessionInsertOutcome::Duplicate) => V2LaneIngressOutcome::Duplicate,
            Err(_) => V2LaneIngressOutcome::Rejected,
        }
    }

    fn insert_lane_certificate(
        &mut self,
        certificate: LaneBlockCertificateV1,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        let LaneBlockCertificateV1 {
            proposal,
            prepare_qc,
            commit_qc,
        } = certificate;
        if prepare_qc.body != proposal.vote_body(CertPhase::Prepare)
            || commit_qc.body != proposal.vote_body(CertPhase::Commit)
        {
            return V2LaneIngressOutcome::Rejected;
        }

        if proposal.descriptor.proposal_height > self.context.height {
            return V2LaneIngressOutcome::Rejected;
        }
        if proposal.descriptor.proposal_height < self.context.height {
            // Historical certificates carry their complete aggregate proof.
            // Admit recoverable missing body/payload dependencies without
            // requiring a proposer-local sidecar, but reject immutable
            // State/Kura identity drift at ingress.
            if self.historical_proposal_anchor_wait(&proposal).is_err() {
                return V2LaneIngressOutcome::Rejected;
            }
            return self.insert_historical_lane_certificate(proposal, prepare_qc, commit_qc);
        }
        if !self.proposal_body_available(&proposal)
            || !self.lane_qc_authorized(&prepare_qc, active_view)
            || !self.lane_qc_authorized(&commit_qc, active_view)
        {
            return V2LaneIngressOutcome::Rejected;
        }
        if self
            .committed_lane_outputs
            .len()
            .saturating_add(self.historical_recovery_sessions.len())
            >= self.limits.session_capacity.get()
        {
            return V2LaneIngressOutcome::Rejected;
        }

        let mut next_sessions = self.lane_sessions.clone();
        let mut inserted = false;
        for outcome in [
            next_sessions.insert_recovered_proposal_replacing_uncommitted_conflict(proposal),
            next_sessions
                .insert_qc_with_pops(prepare_qc.clone(), &self.pops_for_lane_qc(&prepare_qc)),
            next_sessions
                .insert_qc_with_pops(commit_qc.clone(), &self.pops_for_lane_qc(&commit_qc)),
        ] {
            match outcome {
                Ok(LaneBlockSessionInsertOutcome::Inserted) => inserted = true,
                Ok(LaneBlockSessionInsertOutcome::Duplicate) => {}
                Err(_) => return V2LaneIngressOutcome::Rejected,
            }
        }
        self.lane_sessions = next_sessions;
        if inserted {
            V2LaneIngressOutcome::Inserted
        } else {
            V2LaneIngressOutcome::Duplicate
        }
    }

    fn insert_historical_lane_certificate(
        &mut self,
        proposal: LaneBlockProposalV1,
        prepare_qc: LaneBlockQcV1,
        commit_qc: LaneBlockQcV1,
    ) -> V2LaneIngressOutcome {
        let session = CommittedLaneBlockSession {
            proposal,
            prepare_qc,
            commit_qc,
        };
        let pops = self.pops_for_lane_session(&session);
        let candidate = CertifiedLaneBlockArtifact::new(session.clone(), pops);
        if Kura::validate_certified_lane_block_artifact(&candidate).is_err() {
            return V2LaneIngressOutcome::Rejected;
        }
        if self
            .state
            .certified_lane_block_session_is_applied_or_snapshot_anchored_cached(&session)
        {
            return V2LaneIngressOutcome::Duplicate;
        }
        if self
            .historical_recovery_sessions
            .iter()
            .any(|pending| pending.proposal == session.proposal)
        {
            return V2LaneIngressOutcome::Duplicate;
        }
        let retained_sessions = self
            .committed_lane_outputs
            .len()
            .saturating_add(self.historical_recovery_sessions.len());
        if retained_sessions >= self.limits.session_capacity.get() {
            return V2LaneIngressOutcome::Rejected;
        }
        self.historical_recovery_sessions.push_back(session);
        self.note_committed_lane_status_change();
        V2LaneIngressOutcome::Inserted
    }

    fn lane_proposal_authorized(
        &self,
        proposal: &LaneBlockProposalV1,
        sender: Option<&PeerId>,
        local: bool,
        active_view: wire::View,
    ) -> bool {
        let descriptor = &proposal.descriptor;
        if let Some(anchor) = self.canonical_anchor_for_proposal(proposal) {
            return proposal.payload_block_hint.as_ref().is_some_and(|hint| {
                hint.proposal_block_hash == anchor.proposal_block_hash
                    && hint.proposal_height == descriptor.proposal_height
                    && hint.proposal_view == anchor.ownership.proposal_view
            });
        }
        if descriptor.proposal_height != self.context.height
            || descriptor.lane_block_view > active_view
            || proposal.payload_block_hint.as_ref().is_none_or(|hint| {
                hint.proposal_height != descriptor.proposal_height
                    || hint.proposal_view > active_view
            })
            || !self.qc_mode_tag_matches_context(
                &descriptor.qc_mode_tag,
                descriptor.lane_id,
                descriptor.dataspace_id,
            )
            || !self.lane_route_active(
                descriptor.lane_id,
                descriptor.dataspace_id,
                descriptor.lane_incarnation,
                descriptor.proposal_height,
            )
            || self.expected_lane_validators(descriptor.lane_id, descriptor.proposal_height)
                != Some(descriptor.validator_set.clone())
        {
            return false;
        }
        let Some(author) = self.expected_lane_author(proposal) else {
            return false;
        };
        (local && &self.local_peer == author) || sender == Some(author)
    }

    fn expected_lane_author<'a>(&'a self, proposal: &'a LaneBlockProposalV1) -> Option<&'a PeerId> {
        let nexus = self.state.nexus_snapshot();
        if !nexus.enabled
            || !proposal_lookahead_enabled(&nexus, proposal.descriptor.proposal_height)
        {
            // Hint-free autonomous proposals exist before the global carrier
            // view is known. Their producer is therefore the deterministic
            // lane author; an attached ordinary proposal remains authored by
            // the global leader for its finalized carrier view.
            let Some(proposal_view) = proposal.payload_block_hint.map(|hint| hint.proposal_view)
            else {
                return lane_proposal_author(proposal);
            };
            let index = usize::try_from(self.context.leader(proposal_view)).ok()?;
            return self.context.roster.get(index).map(|entry| &entry.validator);
        }
        lane_proposal_author(proposal)
    }

    fn lane_vote_authorized(&self, vote: &LaneBlockVoteV1, active_view: wire::View) -> bool {
        let body = &vote.body;
        if body.proposal_height == self.context.height {
            body.lane_block_view <= active_view
                && self.qc_mode_tag_matches_context(
                    &body.qc_mode_tag,
                    body.lane_id,
                    body.dataspace_id,
                )
                && self.lane_route_active(
                    body.lane_id,
                    body.dataspace_id,
                    body.lane_incarnation,
                    body.proposal_height,
                )
                && self
                    .expected_lane_validators(body.lane_id, body.proposal_height)
                    .is_some_and(|validators| {
                        HashOf::new(&validators) == body.validator_set_hash
                            && validators.contains(&vote.signer)
                    })
        } else {
            self.canonical_proposal_for_vote_body(body)
                .is_some_and(|proposal| proposal.descriptor.validator_set.contains(&vote.signer))
        }
    }

    fn lane_qc_authorized(&self, qc: &LaneBlockQcV1, active_view: wire::View) -> bool {
        let body = &qc.body;
        if body.proposal_height == self.context.height {
            body.lane_block_view <= active_view
                && self.qc_mode_tag_matches_context(
                    &body.qc_mode_tag,
                    body.lane_id,
                    body.dataspace_id,
                )
                && self.lane_route_active(
                    body.lane_id,
                    body.dataspace_id,
                    body.lane_incarnation,
                    body.proposal_height,
                )
                && self
                    .expected_lane_validators(body.lane_id, body.proposal_height)
                    .is_some_and(|validators| validators == qc.validator_set)
        } else {
            self.canonical_proposal_for_vote_body(body)
                .is_some_and(|proposal| proposal.descriptor.validator_set == qc.validator_set)
        }
    }

    fn drive_lane_sessions(&mut self) {
        let proposals = self
            .lane_sessions
            .local_prepare_vote_proposals_for(&self.local_peer);
        for proposal in proposals {
            if proposal.descriptor.proposal_height != self.context.height
                || (self.decision_pending()
                    && !self.proposal_is_bound_to_decided_carrier(&proposal))
                || !self.proposal_body_available(&proposal)
            {
                continue;
            }
            let Some(vote) = self.sign_lane_vote(&proposal, CertPhase::Prepare) else {
                continue;
            };
            if self
                .lane_sessions
                .insert_vote(vote.clone(), Some(&self.local_peer))
                .is_ok()
            {
                self.fanout_lane_message(
                    BlockMessage::LaneBlockVote(vote),
                    &proposal.descriptor.validator_set,
                );
            }
        }

        let commit_requests = self
            .lane_sessions
            .local_commit_vote_requests_for(&self.local_peer);
        for request in commit_requests {
            if request.proposal.descriptor.proposal_height != self.context.height
                || (self.decision_pending()
                    && !self.proposal_is_bound_to_decided_carrier(&request.proposal))
                || !self.proposal_body_available(&request.proposal)
            {
                continue;
            }
            if let Err(error) =
                self.persist_autonomous_prepare_availability(&request.proposal, &request.prepare_qc)
            {
                iroha_logger::error!(
                    %error,
                    lane = %request.proposal.descriptor.lane_id.as_u32(),
                    lane_block_height = request.proposal.descriptor.lane_block_height,
                    "refusing autonomous Commit vote before durable availability publication"
                );
                self.output_guard.close_admission_for_restart();
                return;
            }
            let Some(vote) = self.sign_lane_vote(&request.proposal, CertPhase::Commit) else {
                continue;
            };
            if self
                .lane_sessions
                .insert_vote(vote.clone(), Some(&self.local_peer))
                .is_ok()
            {
                self.fanout_lane_message(
                    BlockMessage::LaneBlockVote(vote),
                    &request.proposal.descriptor.validator_set,
                );
            }
        }

        for qc in self.lane_sessions.drain_newly_sealed_qcs() {
            if qc.body.proposal_height != self.context.height
                || (self.decision_pending()
                    && !self.lane_message_is_allowed_after_decision(&BlockMessage::LaneBlockQc(
                        qc.clone(),
                    )))
            {
                // Other-height certificates are recovery inputs, not fresh
                // current-carrier fanout. Their durable Kura source answers
                // exact proposal retransmissions after local persistence.
                continue;
            }
            let validators = qc.validator_set.clone();
            self.fanout_lane_message(BlockMessage::LaneBlockQc(qc), &validators);
        }
        self.collect_committed_lane_sessions();
    }

    fn sign_lane_vote(
        &self,
        proposal: &LaneBlockProposalV1,
        phase: CertPhase,
    ) -> Option<LaneBlockVoteV1> {
        if !self.voting_enabled
            || self.local_peer.public_key().try_algorithm().ok() != Some(Algorithm::BlsNormal)
        {
            return None;
        }
        let body = proposal.vote_body(phase);
        let payload_availability_vote = if phase == CertPhase::Prepare {
            match self
                .lane_sessions
                .authorized_payload_availability_body_for(proposal)
            {
                Some(availability) => {
                    let world = self.state.world_view();
                    let validator_set_pops = proposal
                        .descriptor
                        .validator_set
                        .iter()
                        .map(|validator| {
                            crate::state::live_consensus_key_pop_for_peer(
                                &world,
                                validator,
                                proposal.descriptor.proposal_height,
                            )
                        })
                        .collect::<Option<Vec<_>>>()?;
                    Some(
                        LanePayloadAvailabilityVoteV1::new_signed(
                            availability,
                            self.local_peer.clone(),
                            validator_set_pops,
                            self.key_pair.private_key(),
                        )
                        .ok()?,
                    )
                }
                None if self.autonomous_payload_is_expected_for(proposal) => return None,
                None => None,
            }
        } else {
            None
        };
        let output_guard = Arc::clone(&self.output_guard);
        let commit_signing_operation = if phase == CertPhase::Commit {
            let operation = output_guard.begin_fail_stop_operation()?;
            let Some(signing_guard) = self.lane_drain_signing_guard.as_ref() else {
                iroha_logger::error!(
                    height = self.context.height,
                    lane = %body.lane_id.as_u32(),
                    lane_block_height = body.lane_block_height,
                    "lane Commit validator has no durable drain/commit signing guard"
                );
                return None;
            };
            if let Err(error) = signing_guard.authorize_commit_vote(&body) {
                iroha_logger::error!(
                    height = self.context.height,
                    lane = %body.lane_id.as_u32(),
                    lane_block_height = body.lane_block_height,
                    %error,
                    "durable lane drain/commit signing guard rejected a Commit vote"
                );
                return None;
            }
            Some(operation)
        } else {
            None
        };
        let signature =
            match Signature::try_new(self.key_pair.private_key(), &body.signature_preimage()) {
                Ok(signature) => signature,
                Err(error) => {
                    iroha_logger::error!(
                        height = self.context.height,
                        lane = %body.lane_id.as_u32(),
                        lane_block_height = body.lane_block_height,
                        %error,
                        "failed to create a lane vote signature"
                    );
                    return None;
                }
            };
        let vote = LaneBlockVoteV1 {
            body,
            payload_availability_vote,
            signer: self.local_peer.clone(),
            bls_signature: signature.payload().to_vec(),
        };
        if let Some(operation) = commit_signing_operation {
            operation.complete();
        }
        Some(vote)
    }

    fn fanout_lane_message(&mut self, message: BlockMessage, validators: &[PeerId]) {
        if lane_fanout_height(&message) != Some(self.context.height)
            || (self.decision_pending() && !self.lane_message_is_allowed_after_decision(&message))
        {
            return;
        }
        let mut seen = BTreeSet::new();
        let peers = validators
            .iter()
            .filter(|peer| *peer != &self.local_peer && seen.insert((*peer).clone()))
            .cloned()
            .collect::<Vec<_>>();
        if peers.is_empty() {
            return;
        }
        let start = self.lane_fanout_cursor % peers.len();
        let mut advanced = 0usize;
        for offset in 0..peers.len() {
            let peer = peers[(start + offset) % peers.len()].clone();
            if !self.push_effect(V2LaneWorkEffect::PostLaneBlock {
                peer,
                message: message.clone(),
            }) {
                break;
            }
            advanced = advanced.saturating_add(1);
        }
        self.lane_fanout_cursor = (start + advanced.max(1)) % peers.len();
    }

    fn push_effect(&mut self, effect: V2LaneWorkEffect) -> bool {
        if !lane_work_effect_reply_routes_have_valid_shape(&effect) {
            return false;
        }
        let key = lane_work_effect_key(&effect);
        if self.effect_keys.contains(&key) {
            return self
                .effects
                .iter_mut()
                .find(|queued| lane_work_effect_key(queued) == key)
                .is_some_and(|queued| merge_lane_work_effect_reply_routes(queued, &effect));
        }
        if !lane_work_effect_reply_routes_are_valid(&effect) {
            return false;
        }
        if self.effects.len() >= self.limits.effect_capacity.get() {
            return false;
        }
        self.effect_keys.insert(key);
        self.effects.push_back(effect);
        true
    }

    fn purge_queued_merge_broadcasts(&mut self) {
        self.effects
            .retain(|effect| !matches!(effect, V2LaneWorkEffect::BroadcastMerge(_)));
        self.effect_keys = self.effects.iter().map(lane_work_effect_key).collect();
    }

    fn purge_queued_global_body_effects_except_committed_outputs(&mut self) {
        let committed_proposals = self
            .committed_lane_outputs
            .iter()
            .map(|output| output.session.proposal.proposal_hash)
            .collect::<BTreeSet<_>>();
        let allowed_durable_certificates = self
            .effects
            .iter()
            .filter_map(|effect| {
                let V2LaneWorkEffect::PostDurableLaneCertificate { certificate, .. } = effect
                else {
                    return None;
                };
                (certificate.proposal.descriptor.proposal_height < self.context.height
                    || self.proposal_is_bound_to_decided_carrier(&certificate.proposal))
                .then(|| lane_work_effect_key(effect))
            })
            .collect::<BTreeSet<_>>();
        self.effects.retain(|effect| match effect {
            V2LaneWorkEffect::PostLaneBlock {
                message: BlockMessage::LaneBlockQc(qc),
                ..
            } => {
                qc.body.phase == CertPhase::Commit
                    && committed_proposals.contains(&qc.body.proposal_hash)
            }
            V2LaneWorkEffect::PostLaneBlock {
                message:
                    BlockMessage::LaneHistoricalRecoveryRequest(_)
                    | BlockMessage::LaneHistoricalRecoveryResponse(_),
                ..
            } => true,
            V2LaneWorkEffect::PostLaneBlock { .. }
            | V2LaneWorkEffect::PostLaneDrainVote { .. }
            | V2LaneWorkEffect::BroadcastMerge(_) => false,
            V2LaneWorkEffect::PostDurableLaneCertificate { .. } => {
                allowed_durable_certificates.contains(&lane_work_effect_key(effect))
            }
            _ => true,
        });
        self.effect_keys = self.effects.iter().map(lane_work_effect_key).collect();
    }

    fn retain_committed_lane_outputs_for_subject(&mut self, subject: wire::BlockSubject) {
        let before = (
            self.pending_committed_lanes.len(),
            self.committed_lane_outputs.len(),
        );
        self.pending_committed_lanes.retain(|session| {
            session
                .proposal
                .payload_block_hint
                .as_ref()
                .is_some_and(|hint| hint.proposal_block_hash == subject.block_hash)
        });
        self.committed_lane_outputs.retain(|output| {
            output
                .session
                .proposal
                .payload_block_hint
                .is_some_and(|hint| hint.proposal_block_hash == subject.block_hash)
        });
        if before
            != (
                self.pending_committed_lanes.len(),
                self.committed_lane_outputs.len(),
            )
        {
            self.note_committed_lane_status_change();
        }
    }

    fn schedule_committed_lane_outputs(&mut self) {
        let output_count = self.committed_lane_outputs.len();
        if output_count == 0 {
            self.committed_lane_output_cursor = 0;
            return;
        }

        let mut consecutive_complete = 0usize;
        while consecutive_complete < output_count {
            let output_index = self.committed_lane_output_cursor % output_count;
            self.committed_lane_output_cursor = (output_index + 1) % output_count;
            let attempt = {
                let output = &self.committed_lane_outputs[output_index];
                let validators = &output.session.commit_qc.validator_set;
                let mut validator_index = output.next_validator;
                while validator_index < validators.len()
                    && validators[validator_index] == self.local_peer
                {
                    validator_index = validator_index.saturating_add(1);
                }
                (validator_index < validators.len()).then(|| {
                    (
                        validator_index,
                        validators[validator_index].clone(),
                        output.session.commit_qc.clone(),
                    )
                })
            };
            let Some((validator_index, peer, commit_qc)) = attempt else {
                self.committed_lane_outputs[output_index].next_validator = self
                    .committed_lane_outputs[output_index]
                    .session
                    .commit_qc
                    .validator_set
                    .len();
                consecutive_complete = consecutive_complete.saturating_add(1);
                continue;
            };
            self.committed_lane_outputs[output_index].next_validator = validator_index;
            if !self.push_effect(V2LaneWorkEffect::PostLaneBlock {
                peer,
                message: BlockMessage::LaneBlockQc(commit_qc),
            }) {
                return;
            }
            self.committed_lane_outputs[output_index].next_validator =
                validator_index.saturating_add(1);
            consecutive_complete = 0;
        }
    }

    /// Return whether a completed lane CommitQC still awaits transfer into the
    /// network actor's exact-output corridor.
    pub(crate) fn has_pending_committed_output_handoff(&self) -> bool {
        let committed_proposals = self
            .committed_lane_outputs
            .iter()
            .map(|output| output.session.proposal.proposal_hash)
            .collect::<BTreeSet<_>>();
        self.committed_lane_outputs.iter().any(|output| {
            output.session.commit_qc.validator_set[output.next_validator..]
                .iter()
                .any(|peer| peer != &self.local_peer)
        }) || self.effects.iter().any(|effect| {
            matches!(
                effect,
                V2LaneWorkEffect::PostLaneBlock {
                    message: BlockMessage::LaneBlockQc(qc),
                    ..
                } if qc.body.phase == CertPhase::Commit
                    && committed_proposals.contains(&qc.body.proposal_hash)
            )
        })
    }

    fn collect_committed_lane_sessions(&mut self) {
        let remaining = self.limits.session_capacity.get().saturating_sub(
            self.committed_lane_outputs
                .len()
                .saturating_add(self.historical_recovery_sessions.len()),
        );
        let mut status_changed = false;
        for session in self.lane_sessions.drain_committed_sessions_up_to(remaining) {
            if session.proposal.descriptor.proposal_height < self.context.height {
                if !self
                    .historical_recovery_sessions
                    .iter()
                    .any(|pending| pending.proposal == session.proposal)
                    && !self
                        .state
                        .certified_lane_block_session_is_applied_or_snapshot_anchored_cached(
                            &session,
                        )
                {
                    self.historical_recovery_sessions.push_back(session);
                    status_changed = true;
                }
                continue;
            }
            self.committed_lane_outputs
                .push_back(PendingCommittedLaneOutput {
                    session: session.clone(),
                    next_validator: 0,
                });
            self.pending_committed_lanes.push_back(session);
            status_changed = true;
        }
        if status_changed {
            self.note_committed_lane_status_change();
        }
        self.schedule_committed_lane_outputs();
    }

    fn proposal_body_available(&self, proposal: &LaneBlockProposalV1) -> bool {
        self.canonical_anchor_for_proposal(proposal).is_some()
            || self
                .locally_bound_lane_proposals
                .get(&proposal.proposal_hash)
                .is_some_and(|hint| proposal.payload_block_hint.as_ref() == Some(hint))
    }

    fn lane_vote_body_available(
        &self,
        body: &iroha_data_model::block::consensus::LaneBlockVoteBodyV1,
    ) -> bool {
        let key = crate::lane_consensus::LaneBlockSessionKey {
            lane_id: body.lane_id,
            dataspace_id: body.dataspace_id,
            lane_incarnation: body.lane_incarnation,
            lane_block_height: body.lane_block_height,
            lane_block_view: body.lane_block_view,
            proposal_hash: body.proposal_hash,
        };
        self.lane_sessions
            .proposal_for_key(&key)
            .as_ref()
            .is_some_and(|proposal| self.proposal_body_available(proposal))
            || self.canonical_proposal_for_vote_body(body).is_some()
    }

    fn expected_lane_validators(
        &self,
        lane_id: LaneId,
        proposal_height: u64,
    ) -> Option<Vec<PeerId>> {
        if proposal_height != self.context.height {
            return None;
        }
        let nexus = self.state.nexus_snapshot();
        let mut validators = if nexus.enabled && proposal_lookahead_enabled(&nexus, proposal_height)
        {
            self.state
                .authoritative_lane_peer_ids_at_height(lane_id, proposal_height)
        } else {
            self.context
                .roster
                .iter()
                .map(|entry| entry.validator.clone())
                .collect()
        };
        validators.sort();
        validators.dedup();
        (!validators.is_empty()).then_some(validators)
    }

    fn lane_route_active(
        &self,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
        lane_incarnation: Hash,
        proposal_height: u64,
    ) -> bool {
        self.state.lane_route_and_incarnation_active_at_height(
            lane_id,
            dataspace_id,
            lane_incarnation,
            proposal_height,
        )
    }

    fn nexus_route_active(
        &self,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
        global_height: u64,
    ) -> bool {
        let nexus = self.state.nexus_snapshot();
        crate::state::consensus_lane_dataspace_at_height(lane_id, &nexus, global_height)
            == Some(dataspace_id)
    }

    fn qc_mode_tag_matches_context(
        &self,
        tag: &str,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
    ) -> bool {
        tag == self.canonical_qc_mode_tag(lane_id, dataspace_id)
    }

    fn canonical_qc_mode_tag(&self, lane_id: LaneId, dataspace_id: DataSpaceId) -> String {
        let base = match self.context.mode {
            wire::ConsensusMode::Permissioned => wire::PERMISSIONED_TAG,
            wire::ConsensusMode::Npos => wire::NPOS_TAG,
        };
        let context_tag = format!(
            "{base}::height-context:{}::epoch:{}",
            hex::encode(self.context.id().0.as_ref()),
            self.context.epoch
        );
        LaneRelayEnvelope::lane_qc_mode_tag_for(lane_id, dataspace_id, &context_tag)
    }

    fn hydrate_canonical_lane_artifacts(&mut self) -> Result<(), V2LaneWorkError> {
        let active_routes = self
            .state
            .consensus_lane_routes_at_height(self.context.height);
        let chain_id_hash = self.native_chain_id_hash();
        let hydration_capacity = self.limits.session_capacity.get();
        let current_height = self.context.height;
        let current_epoch = self.context.epoch;
        let state = Arc::clone(&self.state);
        let recovered_autonomous = self
            .kura
            .latest_autonomous_lane_block_artifacts_snapshot(
                chain_id_hash,
                hydration_capacity.saturating_add(1),
                move |proposal_height| {
                    if proposal_height == current_height {
                        current_epoch
                    } else {
                        let world = state.world_view();
                        crate::sumeragi::epoch_for_height_from_world(&world, proposal_height)
                    }
                },
            )
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        if recovered_autonomous.len() > hydration_capacity {
            self.output_guard.close_admission_for_restart();
            return Err(V2LaneWorkError::InvalidContext(
                "durable autonomous route count exceeds bounded hydration capacity".to_owned(),
            ));
        }
        for (artifact, _) in recovered_autonomous {
            let payload = artifact.executable_payload;
            let proposal = &payload.origin_proposal;
            let descriptor = &proposal.descriptor;
            if descriptor.proposal_height != self.context.height
                || proposal.payload_block_hint.is_some()
                || self
                    .kura
                    .read_autonomous_lane_slot_retirement(
                        descriptor.lane_id,
                        descriptor.lane_block_height,
                        chain_id_hash,
                        self.context.epoch,
                    )
                    .ok()
                    .flatten()
                    .is_some()
                || !self.unanchored_autonomous_origin_matches_context(proposal)
                || self.expected_lane_author(proposal) != Some(&payload.producer)
                || !self.autonomous_reservation_keys_are_canonical(
                    proposal,
                    &payload.producer,
                    &payload.reservation_keys,
                )
            {
                continue;
            }
            let key = AutonomousLanePayloadKey::from(proposal);
            if self
                .pending_autonomous_anchor_payloads
                .insert(key, payload)
                .is_some()
            {
                self.output_guard.close_admission_for_restart();
                return Err(V2LaneWorkError::InvalidContext(
                    "durable autonomous payload index contains a duplicate current slot".to_owned(),
                ));
            }
        }
        // Reconstruct a sidecar if this is the post-application crash window.
        // Normal block persistence writes ownership sidecars transactionally;
        // the exact canonical lookup covers the one interrupted current-height
        // boundary without walking historical global blocks.
        let _ = self
            .kura
            .canonical_lane_block_artifacts_at_proposal_height_matching(
                self.context.height,
                self.limits.session_capacity.get(),
                |ownership| {
                    active_routes.get(&(ownership.lane_id, ownership.dataspace_id))
                        == Some(&ownership.lane_incarnation)
                },
            );

        let pending = self
            .state
            .unapplied_lane_block_artifact_heights_snapshot_cached();
        for ((lane_id, dataspace_id), lane_block_height) in
            pending.into_iter().take(self.limits.session_capacity.get())
        {
            let Some(artifact) = self
                .kura
                .read_lane_block_artifact(lane_id, lane_block_height)
            else {
                continue;
            };
            let ownership = &artifact.ownership;
            if ownership.lane_id != lane_id
                || ownership.dataspace_id != dataspace_id
                || self
                    .state
                    .lane_block_artifact_is_applied_or_snapshot_anchored_cached(&artifact)
                || !self.lane_route_active(
                    ownership.lane_id,
                    ownership.dataspace_id,
                    ownership.lane_incarnation,
                    ownership.proposal_height,
                )
            {
                continue;
            }
            let Some(proposal) =
                proposal_from_ownership(&artifact.ownership, artifact.proposal_block_hash)
            else {
                continue;
            };
            let _ = self
                .lane_sessions
                .insert_recovered_proposal_replacing_uncommitted_conflict(proposal);
        }
        Ok(())
    }

    fn canonical_anchor_for_proposal(
        &self,
        proposal: &LaneBlockProposalV1,
    ) -> Option<crate::kura::LaneBlockArtifact> {
        self.kura
            .read_lane_block_artifact(
                proposal.descriptor.lane_id,
                proposal.descriptor.lane_block_height,
            )
            .filter(|artifact| {
                let ownership = &artifact.ownership;
                self.lane_route_active(
                    ownership.lane_id,
                    ownership.dataspace_id,
                    ownership.lane_incarnation,
                    ownership.proposal_height,
                ) && proposal_from_ownership(ownership, artifact.proposal_block_hash).as_ref()
                    == Some(proposal)
            })
    }

    fn canonical_proposal_for_vote_body(
        &self,
        body: &iroha_data_model::block::consensus::LaneBlockVoteBodyV1,
    ) -> Option<LaneBlockProposalV1> {
        if let Some(autonomous) = self.kura.read_autonomous_lane_block_artifact(
            body.lane_id,
            body.lane_block_height,
            self.native_chain_id_hash(),
            self.context.epoch,
        ) {
            let proposal = autonomous.executable_payload.origin_proposal;
            if proposal.vote_body(body.phase) == *body
                && self.proposal_anchor_is_committed_in_state(&proposal)
            {
                return Some(proposal);
            }
        }
        let artifact = self
            .kura
            .read_lane_block_artifact(body.lane_id, body.lane_block_height)?;
        let proposal = proposal_from_ownership(&artifact.ownership, artifact.proposal_block_hash)?;
        (self.canonical_anchor_for_proposal(&proposal).is_some()
            && proposal.vote_body(body.phase) == *body)
            .then_some(proposal)
    }

    fn session_has_canonical_anchor(&self, session: &CommittedLaneBlockSession) -> bool {
        self.canonical_anchor_for_proposal(&session.proposal)
            .is_some()
            || self.canonical_autonomous_anchor_matches_kura(&session.proposal)
    }

    fn canonical_autonomous_anchor_matches_kura(&self, proposal: &LaneBlockProposalV1) -> bool {
        let Some(hint) = proposal.payload_block_hint else {
            return false;
        };
        let Some(height) = usize::try_from(hint.proposal_height)
            .ok()
            .and_then(NonZeroUsize::new)
        else {
            return false;
        };
        let Some(block) = self.kura.get_block(height) else {
            return false;
        };
        if block.hash() != hint.proposal_block_hash
            || block.header().view_change_index() != hint.proposal_view
        {
            return false;
        }
        let expected_epoch = if hint.proposal_height == self.context.height {
            self.context.epoch
        } else {
            let world = self.state.world_view();
            crate::sumeragi::epoch_for_height_from_world(&world, hint.proposal_height)
        };
        let Some(durable_payload) = self
            .kura
            .read_autonomous_lane_block_artifact(
                proposal.descriptor.lane_id,
                proposal.descriptor.lane_block_height,
                self.native_chain_id_hash(),
                expected_epoch,
            )
            .map(|artifact| artifact.executable_payload)
        else {
            return false;
        };
        durable_payload.origin_proposal == *proposal
            && block.execution_context().is_some_and(|bundle| {
                bundle.autonomous_lane_payloads.iter().any(|envelope| {
                    decode_autonomous_lane_payload_envelope(
                        envelope,
                        self.native_chain_id_hash(),
                        expected_epoch,
                    )
                    .and_then(|payload| {
                        payload.attach_global_hint_exact(
                            hint,
                            self.native_chain_id_hash(),
                            expected_epoch,
                        )
                    })
                    .is_ok_and(|payload| payload == durable_payload)
                })
            })
    }

    fn pops_for_lane_qc(&self, qc: &LaneBlockQcV1) -> BTreeMap<PublicKey, Vec<u8>> {
        let world = self.state.world_view();
        qc.validator_set
            .iter()
            .enumerate()
            .filter(|(index, _)| {
                qc.signers_bitmap
                    .get(index / 8)
                    .is_some_and(|byte| byte & (1_u8 << (index % 8)) != 0)
            })
            .filter_map(|(_, peer)| {
                crate::state::live_consensus_key_pop_for_peer(&world, peer, qc.body.proposal_height)
                    .map(|pop| (peer.public_key().clone(), pop))
            })
            .collect()
    }

    fn pops_for_lane_session(
        &self,
        session: &CommittedLaneBlockSession,
    ) -> BTreeMap<PublicKey, Vec<u8>> {
        let mut pops = self.pops_for_lane_qc(&session.prepare_qc);
        pops.extend(self.pops_for_lane_qc(&session.commit_qc));
        pops
    }

    fn accept_native_amx(
        &mut self,
        sender: PeerId,
        reply_route: Option<NetworkReplyRoute>,
        message: NativeAmxMessage,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        match message {
            NativeAmxMessage::PrepareRequest(request) => {
                self.accept_native_request(sender, reply_route, request, None, active_view)
            }
            NativeAmxMessage::CommitRequest(request) => self.accept_native_request(
                sender,
                reply_route,
                request.request,
                Some(request.prepare_qc),
                active_view,
            ),
            NativeAmxMessage::PrepareVote(vote) => {
                self.accept_native_vote(sender, vote, NativeAmxPhase::Prepare, active_view)
            }
            NativeAmxMessage::CommitVote(vote) => {
                self.accept_native_vote(sender, vote, NativeAmxPhase::Commit, active_view)
            }
        }
    }

    fn accept_native_request(
        &mut self,
        sender: PeerId,
        reply_route: Option<NetworkReplyRoute>,
        request: NativeAmxAttestationRequestV2,
        prepare_qc: Option<NativeAmxAttestationQcV2>,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        let Some(reply_route) = reply_route else {
            return V2LaneIngressOutcome::Rejected;
        };
        let body = request.body;
        if reply_route.semantic_target() != &sender {
            return V2LaneIngressOutcome::Rejected;
        }
        let Ok(reply_routes) = NetworkReplyRoutes::try_from_route(reply_route) else {
            return V2LaneIngressOutcome::Rejected;
        };
        let expected_leader = usize::try_from(self.context.leader(body.round.view))
            .ok()
            .and_then(|index| self.context.roster.get(index))
            .map(|entry| &entry.validator);
        if !self.native_request_matches_context(&request, active_view)
            || expected_leader != Some(&sender)
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let Some((validators, min_signers, pops, _)) = self.native_committee(&body) else {
            return V2LaneIngressOutcome::Rejected;
        };
        if !validators.contains(&self.local_peer) {
            return V2LaneIngressOutcome::Rejected;
        }
        match body.phase {
            NativeAmxPhase::Prepare if prepare_qc.is_some() => {
                return V2LaneIngressOutcome::Rejected;
            }
            NativeAmxPhase::Commit => {
                let Some(prepare_qc) = prepare_qc else {
                    return V2LaneIngressOutcome::Rejected;
                };
                let request = NativeAmxCommitRequestV2 {
                    request: request.clone(),
                    prepare_qc: prepare_qc.clone(),
                };
                if request.validate_shape().is_err()
                    || validate_native_amx_qc(
                        &prepare_qc,
                        &prepare_qc.body,
                        &validators,
                        min_signers,
                        &pops,
                    )
                    .is_err()
                {
                    return V2LaneIngressOutcome::Rejected;
                }
            }
            NativeAmxPhase::Prepare => {}
        }
        let Some(vote) = self.sign_native_request_once(&request, active_view) else {
            return V2LaneIngressOutcome::Rejected;
        };
        if !self.push_effect(V2LaneWorkEffect::PostNativeAmx {
            peer: sender,
            reply_routes: Some(reply_routes),
            message: match body.phase {
                NativeAmxPhase::Prepare => NativeAmxMessage::PrepareVote(vote),
                NativeAmxPhase::Commit => NativeAmxMessage::CommitVote(vote),
            },
        }) {
            return V2LaneIngressOutcome::Rejected;
        }
        V2LaneIngressOutcome::Inserted
    }

    fn accept_native_vote(
        &mut self,
        sender: PeerId,
        vote: NativeAmxVoteV2,
        expected_phase: NativeAmxPhase,
        active_view: wire::View,
    ) -> V2LaneIngressOutcome {
        if !self.native_body_matches_context(&vote.body, active_view)
            || vote
                .validate_ingress(expected_phase, Some(&sender))
                .is_err()
        {
            return V2LaneIngressOutcome::Rejected;
        }
        let Some((validators, _, _, _)) = self.native_committee(&vote.body) else {
            return V2LaneIngressOutcome::Rejected;
        };
        if !validators.contains(&vote.signer) {
            return V2LaneIngressOutcome::Rejected;
        }
        let key = NativeVoteClaimKey {
            session: NativeAmxSessionKey::from_body(&vote.body),
            round: vote.body.round,
            epoch: vote.body.epoch,
            participant_lane: vote.body.participant_lane_id,
            participant_dataspace: vote.body.participant_dataspace_id,
            phase: vote.body.phase,
            signer: HashOf::new(&vote.signer),
        };
        if let Some(existing) = self.native_claims.get(&key) {
            return if existing == &vote.body {
                V2LaneIngressOutcome::Duplicate
            } else {
                V2LaneIngressOutcome::Rejected
            };
        }
        let claim_capacity = self
            .limits
            .session_capacity
            .get()
            .saturating_mul(self.limits.body_buckets_per_session.get());
        while self.native_claims.len() >= claim_capacity {
            let Some(oldest) = self.native_claim_order.pop_front() else {
                return V2LaneIngressOutcome::Rejected;
            };
            self.native_claims.remove(&oldest);
        }
        let body = vote.body;
        match self.native_sessions.insert_vote(vote) {
            Ok(()) => {
                self.native_claims.insert(key, body);
                self.native_claim_order.push_back(key);
                V2LaneIngressOutcome::Inserted
            }
            Err(NativeAmxSessionError::DuplicateSigner) => V2LaneIngressOutcome::Duplicate,
            Err(
                NativeAmxSessionError::PhaseMismatch
                | NativeAmxSessionError::PlanEquivocation
                | NativeAmxSessionError::Capacity,
            ) => V2LaneIngressOutcome::Rejected,
        }
    }

    fn native_body_matches_context(
        &self,
        body: &NativeAmxAttestationBodyV2,
        active_view: wire::View,
    ) -> bool {
        body.round.context_id == self.context.id()
            && body.round.height == self.context.height
            && body.round.view == active_view
            && body.epoch == self.context.epoch
            && body.chain_id_hash == self.native_chain_id_hash()
            && body.authority_context_height == self.context.height
            && self.native_coordinator_height_is_current(body)
            && self.native_participant_predecessor_is_current(body)
            && self.nexus_route_active(
                body.coordinator_lane_id,
                body.coordinator_dataspace_id,
                self.context.height,
            )
            && self.nexus_route_active(
                body.participant_lane_id,
                body.participant_dataspace_id,
                self.context.height,
            )
            && self
                .state
                .lane_incarnation_at_height(body.coordinator_lane_id, body.authority_context_height)
                == Some(body.coordinator_lane_incarnation)
            && self
                .state
                .lane_incarnation_at_height(body.participant_lane_id, body.authority_context_height)
                == Some(body.participant_lane_incarnation)
    }

    fn native_request_matches_context(
        &self,
        request: &NativeAmxAttestationRequestV2,
        active_view: wire::View,
    ) -> bool {
        request.validate_plan_binding().is_ok()
            && self.native_body_matches_context(&request.body, active_view)
            && self.native_coordinator_predecessor_is_current(request)
    }

    fn native_chain_id_hash(&self) -> Hash {
        let chain_id = self.context.chain_id.clone().into_inner();
        Hash::new(chain_id.as_bytes())
    }

    fn native_coordinator_height_is_current(&self, body: &NativeAmxAttestationBodyV2) -> bool {
        let expected = self
            .kura
            .latest_lane_block_artifact_matching(body.coordinator_lane_id, |artifact| {
                let ownership = &artifact.ownership;
                ownership.dataspace_id == body.coordinator_dataspace_id
                    && ownership.lane_incarnation == body.coordinator_lane_incarnation
                    && self.lane_route_active(
                        ownership.lane_id,
                        ownership.dataspace_id,
                        ownership.lane_incarnation,
                        ownership.proposal_height,
                    )
            })
            .map_or(1, |artifact| {
                artifact.ownership.lane_block_height.saturating_add(1)
            });
        body.planned_coordinator_block_height == expected
    }

    fn native_coordinator_predecessor_is_current(
        &self,
        request: &NativeAmxAttestationRequestV2,
    ) -> bool {
        let body = &request.body;
        let descriptor = &request.coordinator_proposal.descriptor;
        let latest =
            self.kura
                .latest_lane_block_artifact_matching(body.coordinator_lane_id, |artifact| {
                    let ownership = &artifact.ownership;
                    ownership.dataspace_id == body.coordinator_dataspace_id
                        && ownership.lane_incarnation == body.coordinator_lane_incarnation
                        && self.lane_route_active(
                            ownership.lane_id,
                            ownership.dataspace_id,
                            ownership.lane_incarnation,
                            ownership.proposal_height,
                        )
                });
        match latest {
            None => {
                descriptor.previous_lane_block_height == 0
                    && descriptor.previous_lane_block_descriptor_hash.is_none()
                    && descriptor.lane_block_height == 1
                    && body.planned_coordinator_block_height == 1
            }
            Some(artifact) => {
                let ownership = &artifact.ownership;
                let Some(predecessor_hash) = ownership.lane_block_descriptor_hash else {
                    return false;
                };
                descriptor.previous_lane_block_height == ownership.lane_block_height
                    && descriptor.previous_lane_block_descriptor_hash == Some(predecessor_hash)
                    && ownership.lane_block_height.checked_add(1)
                        == Some(descriptor.lane_block_height)
                    && body.planned_coordinator_block_height == descriptor.lane_block_height
            }
        }
    }

    fn native_participant_predecessor_is_current(&self, body: &NativeAmxAttestationBodyV2) -> bool {
        if self
            .state
            .unapplied_lane_block_artifact_heights_snapshot_cached()
            .contains_key(&(body.participant_lane_id, body.participant_dataspace_id))
        {
            return false;
        }
        let tip = self
            .state
            .lane_block_artifact_tips_snapshot_cached()
            .into_iter()
            .find(|(lane_id, dataspace_id, incarnation, _, _)| {
                *lane_id == body.participant_lane_id
                    && *dataspace_id == body.participant_dataspace_id
                    && *incarnation == body.participant_lane_incarnation
            });
        match tip {
            None => {
                body.participant_previous_block_height == 0
                    && body.participant_previous_block_descriptor_hash.is_none()
                    && body.participant_lane_block_height == 1
            }
            Some((_, _, _, height, Some(descriptor_hash))) => {
                body.participant_previous_block_height == height
                    && body.participant_previous_block_descriptor_hash == Some(descriptor_hash)
                    && height.checked_add(1) == Some(body.participant_lane_block_height)
            }
            // Conflicting same-height evidence is represented by a missing
            // descriptor hash and must never authorize another participant vote.
            Some((_, _, _, _, None)) => false,
        }
    }

    fn native_committee(
        &self,
        body: &NativeAmxAttestationBodyV2,
    ) -> Option<(
        Vec<PeerId>,
        usize,
        BTreeMap<PublicKey, Vec<u8>>,
        Vec<Vec<u8>>,
    )> {
        let (validators, min_signers, pops, aligned_pops) = self.native_committee_for_route(
            body.participant_lane_id,
            body.participant_dataspace_id,
            body.authority_context_height,
        )?;
        if body.participant_validator_set_hash != HashOf::new(&validators)
            || usize::try_from(body.participant_validator_count).ok() != Some(validators.len())
            || usize::try_from(body.participant_min_quorum).ok() != Some(min_signers)
        {
            return None;
        }
        Some((validators, min_signers, pops, aligned_pops))
    }

    fn native_committee_shape_for_route(
        &self,
        participant_lane: LaneId,
        participant_dataspace: DataSpaceId,
        authority_height: u64,
    ) -> Option<(Vec<PeerId>, usize)> {
        let validators = self.expected_lane_validators(participant_lane, authority_height)?;
        if validators.is_empty()
            || validators.len() > crate::native_amx::MAX_NATIVE_AMX_VALIDATORS
            || validators.windows(2).any(|pair| pair[0] >= pair[1])
            || validators
                .iter()
                .any(|peer| peer.public_key().try_algorithm().ok() != Some(Algorithm::BlsNormal))
        {
            return None;
        }
        let nexus = self.state.nexus_snapshot();
        let fault_tolerance = nexus
            .dataspace_catalog
            .entries()
            .iter()
            .find(|entry| entry.id == participant_dataspace)?
            .fault_tolerance;
        let minimum_committee =
            usize::try_from(fault_tolerance.checked_mul(3)?.checked_add(1)?).ok()?;
        if validators.len() < minimum_committee {
            return None;
        }
        let min_signers = super::network_topology::commit_quorum_from_len(validators.len()).max(1);
        Some((validators, min_signers))
    }

    fn native_committee_for_route(
        &self,
        participant_lane: LaneId,
        participant_dataspace: DataSpaceId,
        authority_height: u64,
    ) -> Option<(
        Vec<PeerId>,
        usize,
        BTreeMap<PublicKey, Vec<u8>>,
        Vec<Vec<u8>>,
    )> {
        let (validators, min_signers) = self.native_committee_shape_for_route(
            participant_lane,
            participant_dataspace,
            authority_height,
        )?;
        let pinned =
            pinned_autoscale_validator_pops_for_set(&self.state, participant_lane, &validators)?;
        let aligned_pops = if let Some(pops) = pinned {
            pops
        } else {
            let world = self.state.world_view();
            validators
                .iter()
                .map(|peer| {
                    let pop = crate::state::live_consensus_key_pop_for_peer(
                        &world,
                        peer,
                        authority_height,
                    )?;
                    iroha_crypto::bls_normal_pop_verify(peer.public_key(), &pop).ok()?;
                    Some(pop)
                })
                .collect::<Option<Vec<_>>>()?
        };
        let pops = verified_native_committee_pops(&validators, &aligned_pops)?;
        Some((validators, min_signers, pops, aligned_pops))
    }

    fn sign_native_request_once(
        &mut self,
        request: &NativeAmxAttestationRequestV2,
        active_view: wire::View,
    ) -> Option<NativeAmxVoteV2> {
        self.sign_native_vote_once_with_context(request.body, |adapter| {
            adapter.native_request_matches_context(request, active_view)
        })
    }

    #[cfg(test)]
    fn sign_native_vote_once(
        &mut self,
        body: NativeAmxAttestationBodyV2,
        active_view: wire::View,
    ) -> Option<NativeAmxVoteV2> {
        self.sign_native_vote_once_with_context(body, |adapter| {
            adapter.native_body_matches_context(&body, active_view)
        })
    }

    fn sign_native_vote_once_with_context<F>(
        &mut self,
        body: NativeAmxAttestationBodyV2,
        context_is_current: F,
    ) -> Option<NativeAmxVoteV2>
    where
        F: Fn(&Self) -> bool,
    {
        if !self.voting_enabled
            || self.local_peer.public_key().try_algorithm().ok() != Some(Algorithm::BlsNormal)
            || !context_is_current(self)
        {
            return None;
        }
        let claim = NativeVoteClaimKey {
            session: NativeAmxSessionKey::from_body(&body),
            round: body.round,
            epoch: body.epoch,
            participant_lane: body.participant_lane_id,
            participant_dataspace: body.participant_dataspace_id,
            phase: body.phase,
            signer: HashOf::new(&self.local_peer),
        };
        if let Some(existing) = self.local_native_claims.get(&claim) {
            if existing != &body {
                return None;
            }
        } else {
            let capacity = self
                .limits
                .session_capacity
                .get()
                .saturating_mul(self.limits.body_buckets_per_session.get());
            if self.local_native_claims.len() >= capacity {
                return None;
            }
        }
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard.begin_fail_stop_operation()?;
        if !context_is_current(self) {
            operation.complete();
            return None;
        }
        let Some(signing_guard) = self.native_signing_guard.as_ref() else {
            iroha_logger::error!(
                height = self.context.height,
                "Native AMX validator has no durable signing guard"
            );
            return None;
        };
        if let Err(error) = signing_guard.record(&body) {
            if error.requires_restart_recovery() {
                iroha_logger::error!(
                    height = self.context.height,
                    ?error,
                    "durable Native AMX signing guard requires restart recovery"
                );
                return None;
            }
            iroha_logger::debug!(
                height = self.context.height,
                ?error,
                "durable Native AMX signing guard rejected a conflicting or stale body"
            );
            operation.complete();
            return None;
        }
        if !context_is_current(self) {
            operation.complete();
            return None;
        }
        let signature =
            Signature::try_new(self.key_pair.private_key(), &body.signature_preimage()).ok()?;
        self.local_native_claims.entry(claim).or_insert(body);
        let vote = NativeAmxVoteV2 {
            body,
            signer: self.local_peer.clone(),
            bls_signature: signature.payload().to_vec(),
        };
        operation.complete();
        Some(vote)
    }

    fn prepare_native_participant_controls(
        &self,
        candidates: &[CandidateDescriptor<'_>],
        coordinator_proposals: &[LaneBlockProposalV1],
    ) -> Result<NativeParticipantControlMap, BTreeSet<usize>> {
        let mut grouped =
            BTreeMap::<(LaneId, DataSpaceId), Vec<(usize, Hash, [u8; Hash::LENGTH])>>::new();
        for (candidate_index, candidate) in candidates.iter().copied().enumerate() {
            let RoutingPlan::NativeAmx(plan) = candidate.routing_plan() else {
                continue;
            };
            let entrypoint_hash = Hash::from(candidate.entrypoint_hash());
            let mut source_id = [0_u8; Hash::LENGTH];
            source_id.copy_from_slice(candidate.transaction().hash().as_ref());
            for participant in &plan.participants {
                grouped
                    .entry((participant.route.lane_id, participant.route.dataspace_id))
                    .or_default()
                    .push((candidate_index, entrypoint_hash, source_id));
            }
        }

        let mut unavailable = BTreeSet::new();
        let mut controls = BTreeMap::new();
        for ((lane_id, dataspace_id), mut members) in grouped {
            let route = RoutingDecision::new(lane_id, dataspace_id);
            members.sort_by_key(|(index, _, _)| *index);
            if members.len() > crate::native_amx::MAX_NATIVE_AMX_PARTICIPANT_CONTROL_SOURCES {
                unavailable.extend(members.iter().map(|(index, _, _)| *index));
                continue;
            }
            let coordinator_proposal = coordinator_proposals.iter().find(|proposal| {
                proposal.descriptor.lane_id == route.lane_id
                    && proposal.descriptor.dataspace_id == route.dataspace_id
            });
            let Some(participant_lane_incarnation) = self
                .state
                .lane_incarnation_at_height(route.lane_id, self.context.height)
            else {
                unavailable.extend(members.iter().map(|(index, _, _)| *index));
                continue;
            };
            let Some((validators, min_signers)) = self.native_committee_shape_for_route(
                route.lane_id,
                route.dataspace_id,
                self.context.height,
            ) else {
                unavailable.extend(members.iter().map(|(index, _, _)| *index));
                continue;
            };
            let proposal = if let Some(proposal) = coordinator_proposal {
                proposal.clone()
            } else {
                let Some((previous_height, previous_hash)) = v2_known_lane_tip_for_route(
                    self.state.as_ref(),
                    self.kura.as_ref(),
                    self.context.height,
                    route.lane_id,
                    route.dataspace_id,
                    participant_lane_incarnation,
                ) else {
                    unavailable.extend(members.iter().map(|(index, _, _)| *index));
                    continue;
                };
                let Some(lane_block_height) = previous_height.checked_add(1) else {
                    unavailable.extend(members.iter().map(|(index, _, _)| *index));
                    continue;
                };
                let lane_block_view = 0;
                let accepted_candidate_indices = members
                    .iter()
                    .map(|(index, _, _)| u64::try_from(*index))
                    .collect::<Result<Vec<_>, _>>();
                let Ok(accepted_candidate_indices) = accepted_candidate_indices else {
                    unavailable.extend(members.iter().map(|(index, _, _)| *index));
                    continue;
                };
                let accepted_transaction_hashes =
                    members.iter().map(|(_, hash, _)| *hash).collect::<Vec<_>>();
                let qc_mode_tag = self.canonical_qc_mode_tag(route.lane_id, route.dataspace_id);
                let mut ownership = SumeragiLanePayloadOwnership {
                    proposal_height: self.context.height,
                    proposal_view: lane_block_view,
                    lane_id: route.lane_id,
                    dataspace_id: route.dataspace_id,
                    lane_incarnation: participant_lane_incarnation,
                    lane_block_height,
                    lane_block_view,
                    subject_hash: Hash::prehashed([0; Hash::LENGTH]),
                    qc_mode_tag: qc_mode_tag.clone(),
                    accepted_candidate_indices: accepted_candidate_indices.clone(),
                    accepted_transaction_hashes: accepted_transaction_hashes.clone(),
                    previous_lane_block_height: previous_height,
                    previous_lane_block_descriptor_hash: previous_hash,
                    lane_block_descriptor_hash: Some(Hash::prehashed([1; Hash::LENGTH])),
                    lane_block_descriptor_validator_set: validators.clone(),
                    lane_block_descriptor_validator_count: u32::try_from(validators.len())
                        .unwrap_or(u32::MAX),
                    lane_block_descriptor_min_quorum: u32::try_from(min_signers)
                        .unwrap_or(u32::MAX),
                    payload_ownership_hash: Hash::prehashed([0; Hash::LENGTH]),
                    rbc_instance_hash: Hash::prehashed([0; Hash::LENGTH]),
                };
                let Ok(replay) = ownership.compute_replay_hashes() else {
                    unavailable.extend(members.iter().map(|(index, _, _)| *index));
                    continue;
                };
                ownership.subject_hash = replay.subject_hash;
                ownership.payload_ownership_hash = replay.payload_ownership_hash;
                ownership.rbc_instance_hash = replay.rbc_instance_hash;
                ownership.lane_block_descriptor_hash = Some(replay.lane_block_descriptor_hash);
                let descriptor = LaneBlockDescriptorV1 {
                    lane_id: ownership.lane_id,
                    dataspace_id: ownership.dataspace_id,
                    lane_incarnation: ownership.lane_incarnation,
                    proposal_height: ownership.proposal_height,
                    previous_lane_block_height: ownership.previous_lane_block_height,
                    previous_lane_block_descriptor_hash: ownership
                        .previous_lane_block_descriptor_hash,
                    lane_block_height: ownership.lane_block_height,
                    lane_block_view: ownership.lane_block_view,
                    subject_hash: ownership.subject_hash,
                    payload_ownership_hash: ownership.payload_ownership_hash,
                    rbc_instance_hash: ownership.rbc_instance_hash,
                    accepted_candidate_indices,
                    accepted_transaction_hashes,
                    validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
                    validator_set_hash: HashOf::new(&validators),
                    validator_set: validators.clone(),
                    validator_count: ownership.lane_block_descriptor_validator_count,
                    min_quorum: ownership.lane_block_descriptor_min_quorum,
                    qc_mode_tag,
                    descriptor_hash: replay.lane_block_descriptor_hash,
                };
                let mut proposal = LaneBlockProposalV1 {
                    descriptor,
                    proposal_hash: Hash::prehashed([0; Hash::LENGTH]),
                    payload_block_hint: None,
                };
                proposal.proposal_hash = proposal.computed_proposal_hash();
                proposal
            };
            if crate::lane_consensus::validate_lane_block_proposal(&proposal).is_err()
                || proposal.descriptor.lane_incarnation != participant_lane_incarnation
                || proposal.descriptor.validator_set != validators
                || usize::try_from(proposal.descriptor.min_quorum).ok() != Some(min_signers)
            {
                unavailable.extend(members.iter().map(|(index, _, _)| *index));
                continue;
            }
            let receipts = members
                .iter()
                .map(|(_, _, source_id)| LaneSettlementReceipt {
                    source_id: *source_id,
                    local_amount: Quantity::zero(),
                    xor_due: Quantity::zero(),
                    xor_after_haircut: Quantity::zero(),
                    xor_variance: Quantity::zero(),
                    timestamp_ms: self.context.height,
                })
                .collect::<Vec<_>>();
            let settlement = LaneBlockCommitment {
                block_height: proposal.descriptor.lane_block_height,
                lane_id: route.lane_id,
                lane_incarnation: participant_lane_incarnation,
                dataspace_id: route.dataspace_id,
                tx_count: u64::try_from(receipts.len()).unwrap_or(u64::MAX),
                total_local_amount: Quantity::zero(),
                total_xor_due: Quantity::zero(),
                total_xor_after_haircut: Quantity::zero(),
                total_xor_variance: Quantity::zero(),
                swap_metadata: None,
                receipts,
                nexus_fee_receipts: Vec::new(),
                native_amx_receipts: Vec::new(),
            };
            controls.insert(
                (route.lane_id, route.dataspace_id),
                NativeParticipantControl {
                    proposal,
                    settlement,
                },
            );
        }
        if unavailable.is_empty() {
            Ok(controls)
        } else {
            Err(unavailable)
        }
    }

    fn prepare_native_receipt(
        &mut self,
        view: wire::View,
        candidate: CandidateDescriptor<'_>,
        coordinator_proposals: &[LaneBlockProposalV1],
        participant_controls: &NativeParticipantControlMap,
    ) -> Option<NativeAmxReceipt> {
        let RoutingPlan::NativeAmx(plan) = candidate.routing_plan() else {
            return None;
        };
        let entrypoint_hash = Hash::from(candidate.entrypoint_hash());
        let mut matching_proposals = coordinator_proposals.iter().filter(|proposal| {
            let descriptor = &proposal.descriptor;
            descriptor.lane_id == plan.coordinator.route.lane_id
                && descriptor.dataspace_id == plan.coordinator.route.dataspace_id
                && descriptor.proposal_height == self.context.height
                && descriptor
                    .accepted_transaction_hashes
                    .iter()
                    .filter(|hash| **hash == entrypoint_hash)
                    .count()
                    == 1
        });
        let coordinator_proposal = matching_proposals.next()?;
        if matching_proposals.next().is_some()
            || crate::lane_consensus::validate_lane_block_proposal(coordinator_proposal).is_err()
        {
            return None;
        }
        let coordinator_descriptor = &coordinator_proposal.descriptor;
        let round = wire::ConsensusRound {
            context_id: self.context.id(),
            height: self.context.height,
            view,
        };
        let mut source_id = [0_u8; Hash::LENGTH];
        source_id.copy_from_slice(candidate.transaction().hash().as_ref());
        let session = NativeAmxSessionKey {
            source_id,
            plan_digest: plan.plan_digest,
        };
        let plan_legs = candidate.routing_plan().legs();
        let mut prepared = Vec::with_capacity(plan.participants.len());
        for participant in &plan.participants {
            let (validators, min_signers, pops, aligned_pops) = self.native_committee_for_route(
                participant.route.lane_id,
                participant.route.dataspace_id,
                self.context.height,
            )?;
            let participant_lane_incarnation = self
                .state
                .lane_incarnation_at_height(participant.route.lane_id, self.context.height)?;
            let participant_control = participant_controls
                .get(&(participant.route.lane_id, participant.route.dataspace_id))?;
            let participant_proposal = &participant_control.proposal;
            let participant_descriptor = &participant_proposal.descriptor;
            let participant_is_coordinator = participant.route == plan.coordinator.route;
            let participant_entrypoint_count = participant_descriptor
                .accepted_transaction_hashes
                .iter()
                .filter(|hash| **hash == entrypoint_hash)
                .count();
            if participant_descriptor.lane_id != participant.route.lane_id
                || participant_descriptor.dataspace_id != participant.route.dataspace_id
                || participant_descriptor.lane_incarnation != participant_lane_incarnation
                || participant_descriptor.proposal_height != self.context.height
                || participant_descriptor.validator_set != validators
                || participant_descriptor.validator_count != u32::try_from(validators.len()).ok()?
                || participant_descriptor.min_quorum != u32::try_from(min_signers).ok()?
                || participant_entrypoint_count > 1
                || (participant_is_coordinator && participant_entrypoint_count != 1)
            {
                return None;
            }
            let participant_settlement = participant_control.settlement.clone();
            let participant_settlement_hash =
                iroha_data_model::nexus::compute_settlement_hash(&participant_settlement).ok()?;
            let prepare_body = NativeAmxAttestationBodyV2 {
                round,
                epoch: self.context.epoch,
                chain_id_hash: self.native_chain_id_hash(),
                source_id,
                tx_entrypoint_hash: candidate.entrypoint_hash(),
                plan_digest: plan.plan_digest,
                phase: NativeAmxPhase::Prepare,
                coordinator_lane_id: plan.coordinator.route.lane_id,
                coordinator_dataspace_id: plan.coordinator.route.dataspace_id,
                coordinator_lane_incarnation: coordinator_descriptor.lane_incarnation,
                participant_lane_id: participant.route.lane_id,
                participant_dataspace_id: participant.route.dataspace_id,
                participant_lane_incarnation,
                participant_previous_block_height: participant_descriptor
                    .previous_lane_block_height,
                participant_previous_block_descriptor_hash: participant_descriptor
                    .previous_lane_block_descriptor_hash,
                participant_lane_block_height: participant_descriptor.lane_block_height,
                participant_lane_block_view: participant_descriptor.lane_block_view,
                participant_proposal_hash: participant_proposal.proposal_hash,
                participant_settlement_commitment: Hash::from(participant_settlement_hash),
                participant_validator_set_hash: HashOf::new(&validators),
                participant_validator_count: u32::try_from(validators.len()).ok()?,
                participant_min_quorum: u32::try_from(min_signers).ok()?,
                authority_context_height: self.context.height,
                planned_coordinator_block_height: coordinator_descriptor.lane_block_height,
                coordinator_lane_block_view: coordinator_descriptor.lane_block_view,
                coordinator_proposal_hash: coordinator_proposal.proposal_hash,
            };
            let request = NativeAmxAttestationRequestV2 {
                body: prepare_body,
                plan_legs: plan_legs.clone(),
                coordinator_proposal: coordinator_proposal.clone(),
                participant_proposal: participant_proposal.clone(),
                participant_settlement,
            };
            if request.validate_plan_binding().is_err() {
                return None;
            }
            self.ensure_native_prepare_requests(&request, &validators, view);
            prepared.push((
                *participant,
                request,
                validators,
                min_signers,
                pops,
                aligned_pops,
            ));
        }

        let mut certified_prepares = Vec::with_capacity(prepared.len());
        for (participant, prepare_request, validators, min_signers, pops, aligned_pops) in prepared
        {
            let prepare_body = prepare_request.body;
            let prepare_votes = self.native_sessions.sorted_votes_for_body_from(
                session,
                &prepare_body,
                &validators,
            );
            if prepare_votes.len() < min_signers {
                return None;
            }
            let prepare_qc = aggregate_votes_to_qc(
                prepare_body,
                validators.clone(),
                aligned_pops.clone(),
                &prepare_votes,
                min_signers,
            )
            .ok()?;
            if validate_native_amx_qc(&prepare_qc, &prepare_body, &validators, min_signers, &pops)
                .is_err()
            {
                return None;
            }
            self.retire_native_requests(&prepare_body);
            let mut commit_request = prepare_request;
            commit_request.body.phase = NativeAmxPhase::Commit;
            self.ensure_native_commit_requests(&commit_request, &prepare_qc, &validators, view);
            certified_prepares.push((
                participant,
                commit_request,
                validators,
                min_signers,
                pops,
                aligned_pops,
                prepare_qc,
            ));
        }

        let mut legs = Vec::with_capacity(certified_prepares.len());
        for (
            participant,
            commit_request,
            validators,
            min_signers,
            pops,
            aligned_pops,
            prepare_qc,
        ) in certified_prepares
        {
            let commit_body = commit_request.body;
            let commit_votes =
                self.native_sessions
                    .sorted_votes_for_body_from(session, &commit_body, &validators);
            if commit_votes.len() < min_signers {
                return None;
            }
            let commit_qc = aggregate_votes_to_qc(
                commit_body,
                validators.clone(),
                aligned_pops,
                &commit_votes,
                min_signers,
            )
            .ok()?;
            if validate_native_amx_qc(&commit_qc, &commit_body, &validators, min_signers, &pops)
                .is_err()
            {
                return None;
            }
            self.retire_native_requests(&commit_body);
            legs.push(NativeAmxLegRecordV2 {
                lane_id: participant.route.lane_id,
                dataspace_id: participant.route.dataspace_id,
                participant_proposal: commit_request.participant_proposal,
                participant_settlement: commit_request.participant_settlement,
                participant_settlement_hash: HashOf::from_untyped_unchecked(
                    commit_body.participant_settlement_commitment,
                ),
                prepare_qc,
                commit_qc,
            });
        }
        self.assemble_native_receipt(
            source_id,
            plan.coordinator.route,
            plan.plan_digest,
            coordinator_proposal,
            legs,
        )
    }

    fn assemble_native_receipt(
        &self,
        source_id: [u8; Hash::LENGTH],
        coordinator: RoutingDecision,
        plan_digest: Hash,
        coordinator_proposal: &LaneBlockProposalV1,
        legs: Vec<NativeAmxLegRecordV2>,
    ) -> Option<NativeAmxReceipt> {
        let descriptor = &coordinator_proposal.descriptor;
        if crate::lane_consensus::validate_lane_block_proposal(coordinator_proposal).is_err()
            || descriptor.lane_id != coordinator.lane_id
            || descriptor.dataspace_id != coordinator.dataspace_id
            || descriptor.proposal_height != self.context.height
            || descriptor.lane_block_height == 0
            || descriptor
                .lane_incarnation
                .as_ref()
                .iter()
                .all(|byte| *byte == 0)
            || coordinator_proposal.proposal_hash != coordinator_proposal.computed_proposal_hash()
        {
            return None;
        }
        let chain_id = self.context.chain_id.clone().into_inner();
        Some(NativeAmxReceipt {
            version: 2,
            source_id,
            chain_id_hash: Hash::new(chain_id.as_bytes()),
            plan_digest,
            lane_id: coordinator.lane_id,
            dataspace_id: coordinator.dataspace_id,
            lane_incarnation: descriptor.lane_incarnation,
            authority_context_height: descriptor.proposal_height,
            lane_block_height: descriptor.lane_block_height,
            lane_block_view: descriptor.lane_block_view,
            coordinator_proposal_hash: coordinator_proposal.proposal_hash,
            legs,
        })
    }

    fn ensure_native_prepare_requests(
        &mut self,
        request: &NativeAmxAttestationRequestV2,
        validators: &[PeerId],
        active_view: wire::View,
    ) {
        let body = request.body;
        for peer in validators {
            if peer == &self.local_peer {
                if self
                    .native_sessions
                    .sorted_votes_for_body(NativeAmxSessionKey::from_body(&body), &body)
                    .iter()
                    .all(|vote| vote.signer != self.local_peer)
                    && let Some(vote) = self.sign_native_request_once(request, active_view)
                {
                    let _ = self.native_sessions.insert_vote(vote);
                }
                continue;
            }
            self.register_native_request(
                body,
                peer.clone(),
                NativeAmxMessage::PrepareRequest(request.clone()),
            );
        }
    }

    fn ensure_native_commit_requests(
        &mut self,
        request: &NativeAmxAttestationRequestV2,
        prepare_qc: &NativeAmxAttestationQcV2,
        validators: &[PeerId],
        active_view: wire::View,
    ) {
        let body = request.body;
        for peer in validators {
            if peer == &self.local_peer {
                if self
                    .native_sessions
                    .sorted_votes_for_body(NativeAmxSessionKey::from_body(&body), &body)
                    .iter()
                    .all(|vote| vote.signer != self.local_peer)
                    && let Some(vote) = self.sign_native_request_once(request, active_view)
                {
                    let _ = self.native_sessions.insert_vote(vote);
                }
                continue;
            }
            self.register_native_request(
                body,
                peer.clone(),
                NativeAmxMessage::CommitRequest(NativeAmxCommitRequestV2 {
                    request: request.clone(),
                    prepare_qc: prepare_qc.clone(),
                }),
            );
        }
    }

    fn register_native_request(
        &mut self,
        body: NativeAmxAttestationBodyV2,
        peer: PeerId,
        message: NativeAmxMessage,
    ) {
        let key = NativeRequestKey {
            body,
            peer: peer.clone(),
        };
        let mut inserted = false;
        if !self.native_requests.contains_key(&key)
            && self.native_requests.len() < self.limits.native_request_capacity.get()
        {
            self.native_requests.insert(key.clone(), message.clone());
            inserted = true;
        }
        if inserted {
            if self.push_effect(V2LaneWorkEffect::PostNativeAmx {
                peer,
                reply_routes: None,
                message,
            }) {
                self.native_retransmit_cursor = self.native_retransmit_cursor.saturating_add(1);
            }
        }
    }

    fn retire_native_requests(&mut self, body: &NativeAmxAttestationBodyV2) {
        self.native_requests.retain(|key, _| &key.body != body);
    }

    fn refresh_lane_drain_body(&mut self) -> Option<(LaneDrainCertificateBodyV1, Vec<PeerId>)> {
        let pending = self.state.pending_autoscale_lane_drain_body();
        self.lane_drain_votes
            .retain_body(pending.as_ref().map(|(body, _)| body.clone()));
        pending
    }

    fn lane_drain_has_local_blockers(&self, body: &LaneDrainCertificateBodyV1) -> bool {
        let intent = &body.intent;
        let route_matches = |lane_id: LaneId, dataspace_id: DataSpaceId, incarnation: Hash| {
            lane_id == intent.lane_id
                && dataspace_id == intent.dataspace_id
                && incarnation == intent.lane_incarnation
        };
        let proposal_matches = |proposal: &LaneBlockProposalV1| {
            let descriptor = &proposal.descriptor;
            route_matches(
                descriptor.lane_id,
                descriptor.dataspace_id,
                descriptor.lane_incarnation,
            )
        };

        let Some(queue) = self.lane_drain_queue.as_ref() else {
            return true;
        };
        if self.state.lane_has_drain_blocking_evidence(
            intent.lane_id,
            intent.dataspace_id,
            intent.lane_incarnation,
        ) || queue.lane_has_pending_work(
            intent.lane_id,
            intent.dataspace_id,
            intent.lane_incarnation,
        ) || self.lane_sessions.has_undrained_work_for_lane(
            intent.lane_id,
            intent.dataspace_id,
            intent.lane_incarnation,
        ) || self
            .pending_committed_lanes
            .iter()
            .any(|session| proposal_matches(&session.proposal))
            || self
                .historical_recovery_sessions
                .iter()
                .any(|session| proposal_matches(&session.proposal))
            || self
                .committed_lane_outputs
                .iter()
                .any(|output| proposal_matches(&output.session.proposal))
            || self
                .planned_lane_proposals
                .values()
                .flatten()
                .any(proposal_matches)
            || self
                .pending_local_lane_proposals
                .values()
                .flatten()
                .any(proposal_matches)
            || self
                .admitted_relays
                .iter()
                .any(|(lane_id, dataspace_id, incarnation, _, _)| {
                    route_matches(*lane_id, *dataspace_id, *incarnation)
                })
            || self
                .pending_autonomous_anchor_payloads
                .values()
                .any(|payload| {
                    lane_executable_payload_carries_lane(
                        payload,
                        intent.lane_id,
                        intent.dataspace_id,
                        intent.lane_incarnation,
                    )
                })
            || self.autonomous_payloads.values().any(|payload| {
                lane_executable_payload_carries_lane(
                    payload,
                    intent.lane_id,
                    intent.dataspace_id,
                    intent.lane_incarnation,
                )
            })
            || self.native_sessions.has_pending_votes_for_lane(
                intent.lane_id,
                intent.dataspace_id,
                intent.lane_incarnation,
            )
            || self.native_requests.keys().any(|key| {
                let native = &key.body;
                route_matches(
                    native.coordinator_lane_id,
                    native.coordinator_dataspace_id,
                    native.coordinator_lane_incarnation,
                ) || route_matches(
                    native.participant_lane_id,
                    native.participant_dataspace_id,
                    native.participant_lane_incarnation,
                )
            })
            || self
                .merge_entries
                .values()
                .any(|pending| match &pending.stage {
                    PendingMergeStage::Collecting(candidate) => merge_candidate_carries_lane(
                        candidate,
                        intent.lane_id,
                        intent.dataspace_id,
                        intent.lane_incarnation,
                    ),
                    PendingMergeStage::Certified(entry) => merge_entry_carries_lane(
                        entry,
                        intent.lane_id,
                        intent.dataspace_id,
                        intent.lane_incarnation,
                    ),
                })
        {
            return true;
        }
        false
    }

    fn seal_lane_drain_certificate_if_quorate(
        &mut self,
        body: &LaneDrainCertificateBodyV1,
        committee: &[PeerId],
    ) -> Result<(), V2LaneWorkError> {
        if self.lane_drain_votes.certificate().is_some() {
            return Ok(());
        }
        let min_quorum = usize::try_from(body.intent.min_quorum).unwrap_or(usize::MAX);
        if self.lane_drain_votes.votes().len() < min_quorum {
            return Ok(());
        }
        let votes = self
            .lane_drain_votes
            .votes()
            .values()
            .cloned()
            .collect::<Vec<_>>();
        let certificate = aggregate_lane_drain_votes(body.clone(), committee.to_vec(), &votes)
            .map_err(|error| {
                V2LaneWorkError::InvalidContext(format!(
                    "validated lane-drain votes failed exact quorum aggregation: {error}"
                ))
            })?;
        self.lane_drain_votes.set_certificate(certificate);
        Ok(())
    }

    fn authorize_and_insert_local_lane_drain_vote(
        &mut self,
        body: &LaneDrainCertificateBodyV1,
        committee: &[PeerId],
    ) -> Result<(), V2LaneWorkError> {
        if !self.voting_enabled
            || !committee.contains(&self.local_peer)
            || self.lane_drain_votes.votes().contains_key(&self.local_peer)
        {
            return Ok(());
        }
        let output_guard = Arc::clone(&self.output_guard);
        let operation = output_guard
            .begin_fail_stop_operation()
            .ok_or(V2LaneWorkError::RestartRequired)?;
        let signing_guard = self.lane_drain_signing_guard.as_ref().ok_or_else(|| {
            V2LaneWorkError::SigningGuard(
                "lane-drain validator has no durable drain/commit signing guard".to_owned(),
            )
        })?;
        signing_guard
            .authorize_drain(body)
            .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?;
        let vote = LaneDrainVoteV1::new_signed(
            body.clone(),
            self.local_peer.clone(),
            self.key_pair.private_key(),
        )
        .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?;
        self.lane_drain_votes
            .insert_vote(vote, Instant::now())
            .map_err(|reason| V2LaneWorkError::InvalidContext(reason.to_owned()))?;
        operation.complete();
        Ok(())
    }

    fn schedule_lane_drain_vote_retransmission(&mut self, committee: &[PeerId]) {
        let Some(vote) = self.lane_drain_votes.votes().get(&self.local_peer).cloned() else {
            return;
        };
        let recipients =
            lane_drain_vote_recipients(committee, &self.frozen_validator_set(), &self.local_peer);
        if recipients.is_empty() {
            return;
        }
        let start = self.lane_drain_fanout_cursor % recipients.len();
        let mut advanced = 0_usize;
        for offset in 0..recipients.len() {
            let peer = recipients[(start + offset) % recipients.len()].clone();
            if !self.push_effect(V2LaneWorkEffect::PostLaneDrainVote {
                peer,
                vote: vote.clone(),
            }) {
                break;
            }
            advanced = advanced.saturating_add(1);
        }
        self.lane_drain_fanout_cursor = (start + advanced.max(1)) % recipients.len();
    }

    fn drive_lane_drain(&mut self, active_view: wire::View) -> Result<(), V2LaneWorkError> {
        if self.pre_apply_unlocked_merge_view() != Some(active_view)
            || !self.merge_parent_frontier_is_exact()
        {
            self.lane_drain_votes.retain_body(None);
            return Ok(());
        }
        let Some((body, committee)) = self.refresh_lane_drain_body() else {
            return Ok(());
        };
        if self.lane_drain_has_local_blockers(&body) {
            return Ok(());
        }
        self.authorize_and_insert_local_lane_drain_vote(&body, &committee)?;
        self.seal_lane_drain_certificate_if_quorate(&body, &committee)?;
        self.schedule_lane_drain_vote_retransmission(&committee);
        Ok(())
    }

    fn accept_lane_drain_vote(
        &mut self,
        sender: PeerId,
        vote: LaneDrainVoteV1,
        active_view: wire::View,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        if sender != vote.signer
            || vote.validate_ingress().is_err()
            || self.pre_apply_unlocked_merge_view() != Some(active_view)
            || !self.merge_parent_frontier_is_exact()
        {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let Some((body, committee)) = self.refresh_lane_drain_body() else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        if self.lane_drain_has_local_blockers(&body) {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let inserted = match self.lane_drain_votes.insert_vote(vote, Instant::now()) {
            Ok(inserted) => inserted,
            Err(reason) => {
                iroha_logger::warn!(%sender, reason, "rejecting invalid lane-drain vote");
                return Ok(V2LaneIngressOutcome::Rejected);
            }
        };
        self.seal_lane_drain_certificate_if_quorate(&body, &committee)?;
        self.drive_lane_drain(active_view)?;
        Ok(if inserted {
            V2LaneIngressOutcome::Inserted
        } else {
            V2LaneIngressOutcome::Duplicate
        })
    }

    fn lane_drain_merge_candidate(
        &self,
        parent_header: &BlockHeader,
        active_view: wire::View,
    ) -> Result<Option<crate::merge::MergeLedgerCandidate>, V2LaneWorkError> {
        let Some(certificate) = self.lane_drain_votes.certificate().cloned() else {
            return Ok(None);
        };
        if self.lane_drain_votes.active_body() != Some(&certificate.body)
            || self.lane_drain_has_local_blockers(&certificate.body)
        {
            return Ok(None);
        }
        self.state
            .merge_drain_candidate_for_next_carrier(parent_header, active_view, certificate)
            .map(Some)
            .map_err(|error| {
                V2LaneWorkError::InvalidContext(format!(
                    "exact lane-drain certificate could not enter canonical merge flow: {error}"
                ))
            })
    }

    fn pre_apply_unlocked_merge_view(&self) -> Option<wire::View> {
        let committed_height = u64::try_from(self.state.committed_height()).ok()?;
        if committed_height.checked_add(1) != Some(self.context.height)
            || self.globally_locked_body.is_some()
        {
            return None;
        }
        self.retained_merge_carrier_state
            .and_then(|(view, locked, decided)| {
                (locked.is_none() && decided.is_none()).then_some(view)
            })
    }

    fn merge_parent_frontier_is_exact(&self) -> bool {
        let committed_height = self.state.committed_height();
        let Some(parent_height) = NonZeroUsize::new(committed_height) else {
            return false;
        };
        let Some(expected_parent) = self
            .context
            .parent_commit_qc
            .as_ref()
            .map(|qc| qc.subject.block_hash)
            .or_else(|| {
                self.context
                    .snapshot_bootstrap
                    .as_ref()
                    .map(|anchor| anchor.snapshot_block_hash)
            })
        else {
            return false;
        };
        self.kura
            .exact_durable_blocks_count()
            .is_ok_and(|durable_height| durable_height == committed_height)
            && self.kura.get_durable_block_hash(parent_height) == Some(expected_parent)
            && self.state.latest_block_hash_fast() == Some(expected_parent)
    }

    fn validate_merge_share_transport_shape(
        &self,
        signature: &MergeCommitteeSignature,
    ) -> Result<(), String> {
        if signature.version != MERGE_COMMITTEE_SIGNATURE_VERSION_V2 {
            return Err("merge share uses an unsupported or legacy wire version".to_owned());
        }
        let leader = self.context.leader(signature.view);
        match (
            signature.signer == leader,
            signature.leader_candidate_body.as_ref(),
        ) {
            (true, None) => {
                return Err("merge leader share is missing its exact candidate body".to_owned());
            }
            (false, Some(_)) => {
                return Err("non-leader merge share carries a candidate body".to_owned());
            }
            (true, Some(body)) => {
                let body_limit = self
                    .limits
                    .merge_share_frame_capacity
                    .get()
                    .checked_sub(self.limits.merge_leader_body_frame_headroom_bytes.get())
                    .unwrap_or(0)
                    .min(MAX_MERGE_LEDGER_ENTRY_BYTES);
                if body.is_empty() || body.len() > body_limit {
                    return Err(
                        "merge leader candidate body exceeds its configured frame partition"
                            .to_owned(),
                    );
                }
            }
            (false, None) => {}
        }
        if signature.bls_sig.len() != MERGE_QC_PROOF_BYTES {
            return Err("merge share has a non-canonical BLS signature length".to_owned());
        }
        let signer = self
            .context
            .roster
            .get(usize::try_from(signature.signer).unwrap_or(usize::MAX))
            .map(|entry| &entry.validator)
            .ok_or_else(|| "merge share signer is outside the frozen roster".to_owned())?;
        let message = crate::NetworkMessage::MergeCommitteeSignature(Arc::new(signature.clone()));
        let mut targets = self
            .context
            .roster
            .iter()
            .map(|entry| &entry.validator)
            .peekable();
        if targets.peek().is_none() {
            return Err("merge share has no frozen transport target".to_owned());
        }
        let frame_capacity = self.limits.merge_share_frame_capacity.get();
        if targets.any(|target| {
            iroha_p2p::network::data_frame_wire_len(
                signer,
                Some(target),
                1,
                Priority::High,
                &message,
            ) > frame_capacity
        }) {
            return Err(
                "merge share full P2P consensus envelope exceeds the configured frame budget"
                    .to_owned(),
            );
        }
        Ok(())
    }

    fn decode_and_validate_leader_candidate(
        &self,
        signature: &MergeCommitteeSignature,
        active_view: wire::View,
        parent_header: &BlockHeader,
    ) -> Result<crate::merge::MergeLedgerCandidate, String> {
        self.validate_merge_share_transport_shape(signature)?;
        if signature.view != active_view || signature.signer != self.context.leader(active_view) {
            return Err("merge candidate body is not from the frozen round leader".to_owned());
        }
        let body = signature
            .leader_candidate_body
            .as_ref()
            .ok_or_else(|| "merge leader candidate body is absent".to_owned())?;
        let candidate = norito::decode_from_bytes::<crate::merge::MergeLedgerCandidate>(body)
            .map_err(|error| format!("merge leader candidate body does not decode: {error}"))?;
        if candidate.canonical_bytes() != *body {
            return Err("merge leader candidate body is not canonical".to_owned());
        }
        let expected_epoch = self
            .state
            .merge_ledger()
            .latest()
            .map_or(1, |entry| entry.epoch_id.saturating_add(1));
        let expected_parent = parent_header.hash();
        if signature.epoch_id != candidate.epoch_id
            || candidate.epoch_id != expected_epoch
            || candidate.view != active_view
            || candidate.carrier_height != self.context.height
            || candidate.carrier_parent_hash != expected_parent
        {
            return Err(
                "merge leader candidate differs from the exact epoch/view/carrier context"
                    .to_owned(),
            );
        }
        self.validate_merge_candidate_for_active_round(&candidate, parent_header, active_view)?;
        let digest = crate::merge::merge_qc_message_digest(
            &self.context.chain_id,
            &candidate,
            VALIDATOR_SET_HASH_VERSION_V1,
            self.frozen_validator_set_hash(),
        );
        if digest != signature.message_digest {
            return Err("merge leader candidate body differs from its signed digest".to_owned());
        }
        Ok(candidate)
    }

    fn validate_merge_candidate_for_active_round(
        &self,
        candidate: &crate::merge::MergeLedgerCandidate,
        parent_header: &BlockHeader,
        active_view: wire::View,
    ) -> Result<(), String> {
        if let Some(batch) = candidate.execution_batch.as_ref() {
            let expected_header =
                self.merge_carrier_context_header(active_view)
                    .map_err(|error| {
                        format!("cannot derive the exact execution carrier context header: {error}")
                    })?;
            if batch.application_block_header != expected_header {
                return Err(
                    "execution candidate is not bound to the exact deterministic carrier context header"
                        .to_owned(),
                );
            }
        }
        self.state
            .validate_merge_candidate_for_global_round(candidate, parent_header, active_view)
            .map_err(|error| error.to_string())
    }

    fn local_merge_share(
        &self,
        key: MergeKey,
        candidate: &crate::merge::MergeLedgerCandidate,
        signer: wire::ValidatorIndex,
        bls_sig: Vec<u8>,
    ) -> Result<MergeCommitteeSignature, V2LaneWorkError> {
        let leader = self.context.leader(key.view);
        let leader_candidate_body = if signer == leader {
            let signing_context = MergeSigningContextV1 {
                epoch_id: candidate.epoch_id,
                view: candidate.view,
                carrier_height: candidate.carrier_height,
                parent_hash: candidate.carrier_parent_hash,
                validator_set_hash: self.frozen_validator_set_hash(),
            };
            let Some((durable_digest, durable_candidate, durable_bytes)) = self
                .merge_signing_guard
                .authorized_candidate(&signing_context)
                .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?
            else {
                return Err(V2LaneWorkError::SigningGuard(
                    "merge leader candidate body is not durable".to_owned(),
                ));
            };
            if durable_digest != key.digest || durable_candidate != *candidate {
                return Err(V2LaneWorkError::SigningGuard(
                    "durable merge leader candidate differs from the signed value".to_owned(),
                ));
            }
            Some(durable_bytes)
        } else {
            None
        };
        let share = MergeCommitteeSignature {
            version: MERGE_COMMITTEE_SIGNATURE_VERSION_V2,
            epoch_id: key.epoch_id,
            view: key.view,
            signer,
            message_digest: key.digest,
            bls_sig,
            leader_candidate_body,
        };
        self.validate_merge_share_transport_shape(&share)
            .map_err(V2LaneWorkError::SigningGuard)?;
        Ok(share)
    }

    /// Publish the exact local merge-signing decision durably before the
    /// private key is used. In-memory claims remain an immediate same-process
    /// equivocation check, while the Kura-root journal is authoritative across
    /// crashes and adapter reconstruction.
    fn authorize_local_merge_claim(
        &mut self,
        candidate: &crate::merge::MergeLedgerCandidate,
        active_view: wire::View,
        signer: wire::ValidatorIndex,
        message_digest: Hash,
    ) -> Result<(), MergeSidecarError> {
        let Some(expected_parent) = self
            .context
            .parent_commit_qc
            .as_ref()
            .map(|qc| qc.subject.block_hash)
            .or_else(|| {
                self.context
                    .snapshot_bootstrap
                    .as_ref()
                    .map(|anchor| anchor.snapshot_block_hash)
            })
        else {
            return Err(MergeSidecarError::SigningGuard(
                "merge signing requires a committed global parent".to_owned(),
            ));
        };
        if self.pre_apply_unlocked_merge_view() != Some(active_view)
            || candidate.view != active_view
            || candidate.carrier_height != self.context.height
            || candidate.carrier_parent_hash != expected_parent
        {
            return Err(MergeSidecarError::LocalSigningEquivocation);
        }
        let expected_digest = crate::merge::merge_qc_message_digest(
            &self.context.chain_id,
            candidate,
            VALIDATOR_SET_HASH_VERSION_V1,
            self.frozen_validator_set_hash(),
        );
        if expected_digest != message_digest {
            return Err(MergeSidecarError::LocalSigningEquivocation);
        }
        let leader = self.context.leader(active_view);
        let durable_context = MergeSigningContextV1 {
            epoch_id: candidate.epoch_id,
            view: candidate.view,
            carrier_height: candidate.carrier_height,
            parent_hash: candidate.carrier_parent_hash,
            validator_set_hash: self.frozen_validator_set_hash(),
        };
        if signer != leader {
            let Some((durable_digest, durable_candidate, durable_bytes)) = self
                .merge_signing_guard
                .authorized_candidate(&durable_context)?
            else {
                return Err(MergeSidecarError::LocalSigningEquivocation);
            };
            if durable_digest != message_digest
                || durable_candidate != *candidate
                || durable_bytes != candidate.canonical_bytes()
            {
                return Err(MergeSidecarError::LocalSigningEquivocation);
            }
        }
        let preflight_share = MergeCommitteeSignature {
            version: MERGE_COMMITTEE_SIGNATURE_VERSION_V2,
            epoch_id: candidate.epoch_id,
            view: candidate.view,
            signer,
            message_digest,
            bls_sig: vec![0_u8; MERGE_QC_PROOF_BYTES],
            leader_candidate_body: (signer == leader).then(|| candidate.canonical_bytes()),
        };
        self.validate_merge_share_transport_shape(&preflight_share)
            .map_err(MergeSidecarError::SigningGuard)?;
        let claim_key = (candidate.epoch_id, candidate.view, signer);
        if self
            .merge_claims
            .get(&claim_key)
            .is_some_and(|existing| *existing != message_digest)
        {
            return Err(MergeSidecarError::LocalSigningEquivocation);
        }
        if self
            .merge_signing_guard
            .authorized_digest(&durable_context)?
            .is_some_and(|authorized| authorized != message_digest)
        {
            return Err(MergeSidecarError::LocalSigningEquivocation);
        }
        let committed_height_usize = self.state.committed_height();
        let committed_height = u64::try_from(committed_height_usize)
            .map_err(|_| MergeSidecarError::SigningGuard("State height overflow".to_owned()))?;
        let durable_height = self
            .kura
            .exact_durable_blocks_count()
            .map_err(|error| MergeSidecarError::SigningGuard(error.to_string()))?;
        if durable_height != committed_height_usize {
            return Err(MergeSidecarError::SigningGuard(
                "merge signing requires identical committed State and durable Kura frontiers"
                    .to_owned(),
            ));
        }
        let parent_height = usize::try_from(committed_height)
            .ok()
            .and_then(NonZeroUsize::new)
            .ok_or_else(|| {
                MergeSidecarError::SigningGuard(
                    "merge signing parent height is not representable".to_owned(),
                )
            })?;
        if self.kura.get_durable_block_hash(parent_height) != Some(expected_parent) {
            return Err(MergeSidecarError::SigningGuard(
                "merge signing parent is not the exact durable Kura tip".to_owned(),
            ));
        }
        let parent_header = self.state.latest_block_header_fast().ok_or_else(|| {
            MergeSidecarError::SigningGuard(
                "merge signing parent header is absent from committed State".to_owned(),
            )
        })?;
        if parent_header.hash() != expected_parent
            || parent_header.height().get() != committed_height
        {
            return Err(MergeSidecarError::SigningGuard(
                "merge signing parent header differs from the frozen context".to_owned(),
            ));
        }
        self.validate_merge_candidate_for_active_round(candidate, &parent_header, active_view)
            .map_err(MergeSidecarError::SigningGuard)?;
        self.merge_signing_guard
            .authorize(durable_context, message_digest, candidate)?;
        self.merge_claims.entry(claim_key).or_insert(message_digest);
        Ok(())
    }

    fn refresh_merge_candidates(&mut self, active_view: wire::View) -> Result<(), V2LaneWorkError> {
        let carrier_protected = self
            .retained_merge_carrier_state
            .is_some_and(|(_, locked, decided)| locked.is_some() || decided.is_some());
        if self.globally_locked_body.is_some() || carrier_protected {
            self.merge_entries.clear();
            self.merge_claims.clear();
            return Ok(());
        }
        self.merge_entries.retain(|key, _| key.view == active_view);
        self.merge_claims
            .retain(|(_, view, _), _| *view == active_view);
        if self.pre_apply_unlocked_merge_view() != Some(active_view)
            || !self.merge_parent_frontier_is_exact()
        {
            return Ok(());
        }

        let Some(expected_parent) = self
            .context
            .parent_commit_qc
            .as_ref()
            .map(|qc| qc.subject.block_hash)
            .or_else(|| {
                self.context
                    .snapshot_bootstrap
                    .as_ref()
                    .map(|anchor| anchor.snapshot_block_hash)
            })
        else {
            return Ok(());
        };
        let Some(parent_header) = self.state.latest_block_header_fast() else {
            return Ok(());
        };
        if parent_header.hash() != expected_parent
            || parent_header.height().get().checked_add(1) != Some(self.context.height)
        {
            return Ok(());
        }
        // Reconcile the durable QueuePlan admission store only at an exact
        // canonical Kura/WSV parent frontier. Exact registry matches are safe
        // to forget after their global carrier is durable; absent claims stay
        // pending across losing proposals and are attached to the next local
        // leader candidate. Authenticated stale or conflicting claims are
        // definitive losers and can be removed; malformed durable evidence
        // still fails closed.
        let mut pending_queue_plan_admissions = Vec::new();
        for (certificate_hash, certificate_bytes) in self
            .kura
            .pending_queue_plan_admission_certificates_bounded(
                self.kura.pending_queue_plan_admission_capacity(),
            )
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?
        {
            let (admission, disposition) = self
                .state
                .classify_pending_queue_plan_admission(&certificate_bytes, self.context.height)
                .map_err(|error| {
                    V2LaneWorkError::Persistence(format!(
                        "pending QueuePlan admission certificate cannot be reconciled: {error}"
                    ))
                })?;
            match disposition {
                PendingQueuePlanAdmissionDisposition::Exact => self
                    .kura
                    .remove_pending_queue_plan_admission_certificate(certificate_hash)
                    .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?,
                PendingQueuePlanAdmissionDisposition::DefinitiveConflict
                | PendingQueuePlanAdmissionDisposition::Stale => {
                    let queue = self.lane_drain_queue.as_ref().ok_or_else(|| {
                        V2LaneWorkError::Persistence(
                            "losing QueuePlan admission cannot be retired without the live queue"
                                .to_owned(),
                        )
                    })?;
                    queue
                        .reject_exact_queue_plan_admission_claim(
                            &admission.certificate.binding,
                        )
                        .map_err(|error| {
                            V2LaneWorkError::Persistence(format!(
                                "losing QueuePlan admission queue claim cannot be durably rejected: {error}"
                            ))
                        })?;
                    self.kura
                        .remove_pending_queue_plan_admission_certificate(certificate_hash)
                        .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
                }
                PendingQueuePlanAdmissionDisposition::EligibleAbsent => {
                    pending_queue_plan_admissions.push(certificate_bytes);
                }
            }
        }
        self.drive_lane_drain(active_view)?;

        let expected_epoch = self
            .state
            .merge_ledger()
            .latest()
            .map_or(1, |entry| entry.epoch_id.saturating_add(1));
        let validator_set_hash = self.frozen_validator_set_hash();
        let signing_context = MergeSigningContextV1 {
            epoch_id: expected_epoch,
            view: active_view,
            carrier_height: self.context.height,
            parent_hash: expected_parent,
            validator_set_hash,
        };
        let authorized_candidate = self
            .merge_signing_guard
            .authorized_candidate(&signing_context)
            .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?;
        let authorized_digest = authorized_candidate.as_ref().map(|(digest, _, _)| *digest);
        if let Some((digest, candidate, bytes)) = authorized_candidate.as_ref() {
            let recomputed = crate::merge::merge_qc_message_digest(
                &self.context.chain_id,
                candidate,
                VALIDATOR_SET_HASH_VERSION_V1,
                validator_set_hash,
            );
            if *digest != recomputed
                || *bytes != candidate.canonical_bytes()
                || self
                    .validate_merge_candidate_for_active_round(
                        candidate,
                        &parent_header,
                        active_view,
                    )
                    .is_err()
            {
                return Err(V2LaneWorkError::SigningGuard(
                    "durable merge candidate no longer revalidates against its exact global round"
                        .to_owned(),
                ));
            }
        }
        let mut installed_candidates = self
            .merge_entries
            .values()
            .filter_map(|pending| match &pending.stage {
                PendingMergeStage::Collecting(candidate)
                    if candidate.epoch_id == expected_epoch
                        && candidate.view == active_view
                        && candidate.carrier_height == self.context.height
                        && candidate.carrier_parent_hash == expected_parent
                        && self
                            .validate_merge_candidate_for_active_round(
                                candidate,
                                &parent_header,
                                active_view,
                            )
                            .is_ok() =>
                {
                    Some(candidate.clone())
                }
                PendingMergeStage::Collecting(_) | PendingMergeStage::Certified(_) => None,
            })
            .collect::<Vec<_>>();
        if let Some((_, candidate, _)) = authorized_candidate {
            installed_candidates.push(candidate);
        }
        let local_is_leader =
            self.local_validator_index() == Some(self.context.leader(active_view));
        let leader_candidates = if authorized_digest.is_none() && local_is_leader {
            let base = if let Some(candidate) =
                self.lane_drain_merge_candidate(&parent_header, active_view)?
            {
                Some(candidate)
            } else {
                let execution_candidate = self
                    .state
                    .has_pending_merge_execution_sources()
                    .then(|| self.merge_carrier_context_header(active_view))
                    .transpose()?
                    .and_then(|header| self.state.build_merge_execution_candidate(header));
                execution_candidate.or_else(|| {
                    self.state
                        .merge_entry_candidates_from_lane_relays_for_view(active_view)
                        .into_iter()
                        .find(|candidate| candidate.epoch_id == expected_epoch)
                })
            };
            self.state
                .merge_candidate_with_queue_plan_admissions(
                    &parent_header,
                    active_view,
                    base,
                    pending_queue_plan_admissions,
                )
                .map_err(|error| {
                    V2LaneWorkError::Persistence(format!(
                        "pending QueuePlan admissions cannot be attached to the canonical merge candidate: {error}"
                    ))
                })?
                .into_iter()
                .collect()
        } else {
            Vec::new()
        };
        let candidates = preferred_merge_candidates(
            authorized_digest,
            leader_candidates,
            installed_candidates,
            |candidate| {
                crate::merge::merge_qc_message_digest(
                    &self.context.chain_id,
                    candidate,
                    VALIDATOR_SET_HASH_VERSION_V1,
                    validator_set_hash,
                )
            },
        );
        for candidate in candidates {
            let digest = crate::merge::merge_qc_message_digest(
                &self.context.chain_id,
                &candidate,
                VALIDATOR_SET_HASH_VERSION_V1,
                validator_set_hash,
            );
            let key = MergeKey {
                epoch_id: candidate.epoch_id,
                view: candidate.view,
                digest,
            };
            if !self.merge_entries.contains_key(&key)
                && self.merge_entries.len() >= self.limits.merge_capacity.get()
            {
                continue;
            }
            self.merge_entries.entry(key).or_insert(PendingMerge {
                stage: PendingMergeStage::Collecting(candidate.clone()),
                signatures: BTreeMap::new(),
            });
            let Some(local_index) = self.local_validator_index() else {
                continue;
            };
            if self.merge_entries[&key]
                .signatures
                .contains_key(&local_index)
            {
                continue;
            }
            if let Err(error) =
                self.authorize_local_merge_claim(&candidate, active_view, local_index, digest)
            {
                if let MergeSidecarError::SigningGuard(reason) = &error {
                    return Err(V2LaneWorkError::SigningGuard(reason.clone()));
                }
                iroha_logger::warn!(
                    ?error,
                    epoch = candidate.epoch_id,
                    view = candidate.view,
                    "refusing local merge signature without durable exact-context authorization"
                );
                continue;
            }
            let signature = Signature::try_new(self.key_pair.private_key(), digest.as_ref())
                .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?;
            let payload = signature.payload().to_vec();
            let share = self.local_merge_share(key, &candidate, local_index, payload.clone())?;
            self.merge_entries
                .get_mut(&key)
                .expect("entry inserted above")
                .signatures
                .insert(local_index, payload);
            self.push_effect(V2LaneWorkEffect::BroadcastMerge(share));
            self.try_commit_merge(key)?;
        }
        Ok(())
    }

    fn accept_merge_signature(
        &mut self,
        signature: MergeCommitteeSignature,
        active_view: wire::View,
    ) -> Result<V2LaneIngressOutcome, V2LaneWorkError> {
        if signature.view != active_view
            || self.pre_apply_unlocked_merge_view() != Some(active_view)
            || !self.merge_parent_frontier_is_exact()
            || self
                .validate_merge_share_transport_shape(&signature)
                .is_err()
        {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let Some(peer) = self
            .context
            .roster
            .get(usize::try_from(signature.signer).unwrap_or(usize::MAX))
            .map(|entry| &entry.validator)
        else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        let Ok(parsed) = Signature::try_from_bytes(&signature.bls_sig) else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        if parsed
            .verify(peer.public_key(), signature.message_digest.as_ref())
            .is_err()
        {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let leader = self.context.leader(active_view);
        if signature.signer == leader {
            let Some(parent_header) = self.state.latest_block_header_fast() else {
                return Ok(V2LaneIngressOutcome::Rejected);
            };
            let candidate = match self.decode_and_validate_leader_candidate(
                &signature,
                active_view,
                &parent_header,
            ) {
                Ok(candidate) => candidate,
                Err(reason) => {
                    iroha_logger::warn!(
                        epoch = signature.epoch_id,
                        view = signature.view,
                        reason,
                        "rejecting invalid authenticated merge leader candidate"
                    );
                    return Ok(V2LaneIngressOutcome::Rejected);
                }
            };
            let signing_context = MergeSigningContextV1 {
                epoch_id: candidate.epoch_id,
                view: candidate.view,
                carrier_height: candidate.carrier_height,
                parent_hash: candidate.carrier_parent_hash,
                validator_set_hash: self.frozen_validator_set_hash(),
            };
            if let Some((durable_digest, durable_candidate, durable_bytes)) = self
                .merge_signing_guard
                .authorized_candidate(&signing_context)
                .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?
                && (durable_digest != signature.message_digest
                    || durable_candidate != candidate
                    || durable_bytes.as_slice()
                        != signature
                            .leader_candidate_body
                            .as_ref()
                            .expect("leader shape validated above")
                            .as_slice())
            {
                return Err(V2LaneWorkError::SigningGuard(
                    "authenticated merge leader equivocated for one durable signing context"
                        .to_owned(),
                ));
            }
            if self
                .merge_claims
                .get(&(signature.epoch_id, signature.view, leader))
                .is_some_and(|digest| *digest != signature.message_digest)
            {
                return Err(V2LaneWorkError::SigningGuard(
                    "authenticated merge leader equivocated after volatile admission".to_owned(),
                ));
            }
            self.merge_signing_guard
                .authorize(signing_context, signature.message_digest, &candidate)
                .map_err(|error| V2LaneWorkError::SigningGuard(error.to_string()))?;
            let key = MergeKey {
                epoch_id: candidate.epoch_id,
                view: candidate.view,
                digest: signature.message_digest,
            };
            self.merge_entries.retain(|existing, pending| {
                existing == &key || matches!(&pending.stage, PendingMergeStage::Certified(_))
            });
            if !self.merge_entries.contains_key(&key)
                && self.merge_entries.len() >= self.limits.merge_capacity.get()
            {
                return Err(V2LaneWorkError::SigningGuard(
                    "authenticated merge leader candidate exceeds bounded admission capacity"
                        .to_owned(),
                ));
            }
            self.merge_entries.entry(key).or_insert(PendingMerge {
                stage: PendingMergeStage::Collecting(candidate),
                signatures: BTreeMap::new(),
            });
        }
        self.refresh_merge_candidates(active_view)?;
        let key = MergeKey {
            epoch_id: signature.epoch_id,
            view: signature.view,
            digest: signature.message_digest,
        };
        let Some(pending) = self.merge_entries.get(&key) else {
            return Ok(V2LaneIngressOutcome::Rejected);
        };
        let expected_digest = match &pending.stage {
            PendingMergeStage::Collecting(candidate) => crate::merge::merge_qc_message_digest(
                &self.context.chain_id,
                candidate,
                VALIDATOR_SET_HASH_VERSION_V1,
                self.frozen_validator_set_hash(),
            ),
            PendingMergeStage::Certified(entry) => entry.merge_qc.message_digest,
        };
        if expected_digest != signature.message_digest {
            return Ok(V2LaneIngressOutcome::Rejected);
        }
        let claim_key = (signature.epoch_id, signature.view, signature.signer);
        if let Some(existing) = self.merge_claims.get(&claim_key) {
            if existing != &signature.message_digest {
                if signature.signer == leader {
                    return Err(V2LaneWorkError::SigningGuard(
                        "authenticated merge leader equivocated after claim admission".to_owned(),
                    ));
                }
                return Ok(V2LaneIngressOutcome::Rejected);
            }
            if self.merge_entries[&key].signatures.get(&signature.signer)
                != Some(&signature.bls_sig)
            {
                return Ok(V2LaneIngressOutcome::Rejected);
            }
            // Re-evaluate the existing exact quorum without accepting another
            // signer claim. Any durable publication failure propagates to the
            // enclosing fail-stop relay operation.
            self.try_commit_merge(key)?;
            return Ok(V2LaneIngressOutcome::Duplicate);
        }
        self.merge_claims
            .insert(claim_key, signature.message_digest);
        self.merge_entries
            .get_mut(&key)
            .expect("pending entry checked above")
            .signatures
            .insert(signature.signer, signature.bls_sig);
        self.try_commit_merge(key)?;
        Ok(V2LaneIngressOutcome::Inserted)
    }

    fn try_commit_merge(&mut self, key: MergeKey) -> Result<(), V2LaneWorkError> {
        let Some(pending) = self.merge_entries.get(&key) else {
            return Ok(());
        };
        let cached_entry = match &pending.stage {
            PendingMergeStage::Certified(entry) => Some(entry.clone()),
            PendingMergeStage::Collecting(_) => None,
        };
        if let Some(entry) = cached_entry {
            return self.persist_certified_merge_entry(key, &entry);
        }
        let Some(PendingMerge {
            stage: PendingMergeStage::Collecting(candidate),
            ..
        }) = self.merge_entries.get(&key)
        else {
            return Ok(());
        };
        let validator_set = self.frozen_validator_set();
        let validator_set_hash = HashOf::new(&validator_set);
        if crate::merge::merge_qc_message_digest(
            &self.context.chain_id,
            candidate,
            VALIDATOR_SET_HASH_VERSION_V1,
            validator_set_hash,
        ) != key.digest
        {
            return Ok(());
        }
        let signers = pending.signatures.keys().copied().collect::<Vec<_>>();
        if !self.frozen_dual_quorum_met(&signers) {
            return Ok(());
        }
        let signatures = signers
            .iter()
            .filter_map(|signer| pending.signatures.get(signer))
            .collect::<Vec<_>>();
        let refs = signatures
            .iter()
            .map(|signature| signature.as_slice())
            .collect::<Vec<_>>();
        let Ok(aggregate_signature) = iroha_crypto::bls_normal_aggregate_signatures(&refs) else {
            return Ok(());
        };
        let mut bitmap = vec![0_u8; self.context.roster.len().div_ceil(8)];
        for signer in &signers {
            let Ok(index) = usize::try_from(*signer) else {
                return Ok(());
            };
            bitmap[index / 8] |= 1_u8 << (index % 8);
        }
        let signer_proofs = {
            let world = self.state.world_view();
            let mut proofs = Vec::with_capacity(signers.len());
            for signer in &signers {
                let Ok(index) = usize::try_from(*signer) else {
                    return Ok(());
                };
                let Some(peer) = validator_set.get(index) else {
                    return Ok(());
                };
                let Some(proof_of_possession) =
                    crate::state::consensus_key_pop_for_public_key(&world, peer.public_key())
                else {
                    return Ok(());
                };
                proofs.push(MergeSignerProof {
                    signer: *signer,
                    proof_of_possession,
                });
            }
            proofs
        };
        let qc = MergeQuorumCertificate::new(
            key.view,
            key.epoch_id,
            candidate.carrier_height,
            candidate.carrier_parent_hash,
            crate::merge::merge_chain_id_digest(&self.context.chain_id),
            VALIDATOR_SET_HASH_VERSION_V1,
            validator_set_hash,
            validator_set,
            bitmap,
            signer_proofs,
            aggregate_signature,
            key.digest,
        );
        let entry = candidate.clone().into_entry(qc);
        if let Err(error) = authenticate_merge_entry_for_height_context(&self.context, &entry) {
            iroha_logger::warn!(
                error,
                epoch = entry.epoch_id,
                view = key.view,
                "rejecting locally certified merge entry whose QC is not authenticated by the frozen height context"
            );
            return Ok(());
        }
        if let Err(error) = self
            .state
            .validate_certified_merge_entry_for_global_order(&entry)
        {
            iroha_logger::warn!(
                ?error,
                epoch = entry.epoch_id,
                view = key.view,
                "rejecting locally certified merge entry before durable carrier staging"
            );
            return Ok(());
        }
        let Some(pending) = self.merge_entries.get_mut(&key) else {
            return Ok(());
        };
        pending.stage = PendingMergeStage::Certified(entry.clone());
        self.persist_certified_merge_entry(key, &entry)
    }

    fn persist_certified_merge_entry(
        &mut self,
        key: MergeKey,
        entry: &MergeLedgerEntry,
    ) -> Result<(), V2LaneWorkError> {
        self.kura
            .persist_pending_certified_merge_entry(entry)
            .map_err(|error| V2LaneWorkError::Persistence(error.to_string()))?;
        self.merge_entries.remove(&key);
        Ok(())
    }

    fn frozen_dual_quorum_met(&self, signers: &[wire::ValidatorIndex]) -> bool {
        self.context.validate_signers(signers).is_ok()
    }

    fn local_validator_index(&self) -> Option<wire::ValidatorIndex> {
        if !self.voting_enabled {
            return None;
        }
        self.context
            .roster
            .iter()
            .position(|entry| entry.validator == self.local_peer)
            .and_then(|index| u32::try_from(index).ok())
    }

    fn frozen_roster_contains(&self, peer: &PeerId) -> bool {
        self.context
            .roster
            .iter()
            .any(|entry| &entry.validator == peer)
    }

    fn frozen_validator_set(&self) -> Vec<PeerId> {
        self.context
            .roster
            .iter()
            .map(|entry| entry.validator.clone())
            .collect()
    }

    fn frozen_validator_set_hash(&self) -> HashOf<Vec<PeerId>> {
        HashOf::new(&self.frozen_validator_set())
    }
}

impl CandidateWorkProvider for &mut V2LaneWorkAdapter {
    fn prepare(
        &mut self,
        context: &wire::HeightContext,
        view: wire::View,
        candidates: &[CandidateDescriptor<'_>],
    ) -> Result<PreparedCandidateWork, CandidateWorkUnavailable> {
        let output_guard = Arc::clone(&self.output_guard);
        let Some(operation) = output_guard.begin_fail_stop_operation() else {
            return Err(all_unavailable(
                candidates.len(),
                "Sumeragi v2 consensus requires process restart",
            ));
        };
        if context != &self.context {
            operation.complete();
            return Err(all_unavailable(candidates.len(), "height context drift"));
        }
        if let Err(error) = self.refresh_merge_candidates(view) {
            drop(operation);
            return Err(all_unavailable(candidates.len(), error.to_string()));
        }
        let result = (|| {
            self.planned_lane_proposals.clear();
            let reserved_routes = self
                .pending_autonomous_anchor_payloads
                .keys()
                .map(|key| (key.lane_id, key.dataspace_id))
                .collect::<BTreeSet<_>>();
            let reserved_entrypoints = self
                .pending_autonomous_anchor_payloads
                .values()
                .flat_map(|payload| payload.entrypoint_hashes.iter().copied())
                .collect::<BTreeSet<_>>();
            let nexus = self.state.nexus_snapshot();
            if proposal_lookahead_enabled(&nexus, self.context.height) && !candidates.is_empty() {
                let autonomous_routes = self
                    .state
                    .consensus_lane_routes_at_height(self.context.height);
                let unavailable = candidates
                    .iter()
                    .copied()
                    .enumerate()
                    .filter_map(|(index, candidate)| {
                        let route = candidate.routing_plan().coordinator_route();
                        autonomous_routes
                            .contains_key(&(route.lane_id, route.dataspace_id))
                            .then_some(index)
                    })
                    .collect::<BTreeSet<_>>();
                if !unavailable.is_empty() {
                    return Err(CandidateWorkUnavailable::new(
                        unavailable,
                        "waiting for deterministic autonomous lane authors to publish durable FIFO reservations",
                    ));
                }
            }
            let unavailable = candidates
                .iter()
                .copied()
                .enumerate()
                .filter_map(|(index, candidate)| {
                    let entrypoint = Hash::from(candidate.entrypoint_hash());
                    let route_conflict = candidate.routing_plan().legs().iter().any(|leg| {
                        reserved_routes.contains(&(leg.route.lane_id, leg.route.dataspace_id))
                    });
                    (reserved_entrypoints.contains(&entrypoint) || route_conflict).then_some(index)
                })
                .collect::<BTreeSet<_>>();
            if !unavailable.is_empty() {
                return Err(CandidateWorkUnavailable::new(
                    unavailable,
                    "ordinary work conflicts with an already-reserved autonomous lane slot",
                ));
            }
            let autonomous_lane_payloads = self
                .pending_autonomous_anchor_payloads
                .values()
                .map(|payload| {
                    autonomous_lane_payload_envelope(
                        payload,
                        self.native_chain_id_hash(),
                        self.context.epoch,
                    )
                })
                .collect::<Result<Vec<_>, _>>()
                .map_err(|error| {
                    all_unavailable(
                        candidates.len(),
                        format!(
                            "reserved autonomous payload cannot form a canonical anchor: {error}"
                        ),
                    )
                })?;
            let routes = candidates
                .iter()
                .map(|candidate| candidate.routing_plan().coordinator_route())
                .collect::<Vec<_>>();
            let hashes = candidates
                .iter()
                .map(|candidate| Hash::from(candidate.entrypoint_hash()))
                .collect::<Vec<_>>();
            let lane_plan = prepare_v2_lane_payload_plan(
                self.state.as_ref(),
                self.kura.as_ref(),
                context,
                view,
                &self.local_peer,
                &routes,
                &hashes,
            )
            .map_err(|error| all_unavailable(candidates.len(), error.to_string()))?;
            if !lane_plan.unavailable_indices.is_empty() {
                return Err(CandidateWorkUnavailable::new(
                    lane_plan.unavailable_indices,
                    "lane-local author, committee, or predecessor unavailable",
                ));
            }
            if lane_plan
                .proposals
                .len()
                .saturating_add(autonomous_lane_payloads.len())
                > self.limits.session_capacity.get()
            {
                return Err(all_unavailable(
                    candidates.len(),
                    "combined lane-local proposal count exceeds the bounded session capacity",
                ));
            }
            let participant_controls = self
                .prepare_native_participant_controls(candidates, &lane_plan.proposals)
                .map_err(|indices| {
                    CandidateWorkUnavailable::new(
                        indices,
                        "Native AMX participant control proposal is unavailable",
                    )
                })?;

            let mut receipts = Vec::with_capacity(candidates.len());
            let mut unavailable = BTreeSet::new();
            for (index, candidate) in candidates.iter().copied().enumerate() {
                match candidate.routing_plan() {
                    RoutingPlan::Single(_) => receipts.push(None),
                    RoutingPlan::NativeAmx(_) => {
                        match self.prepare_native_receipt(
                            view,
                            candidate,
                            &lane_plan.proposals,
                            &participant_controls,
                        ) {
                            Some(receipt) => receipts.push(Some(receipt)),
                            None => {
                                receipts.push(None);
                                unavailable.insert(index);
                            }
                        }
                    }
                }
            }
            if !unavailable.is_empty() {
                return Err(CandidateWorkUnavailable::new(
                    unavailable,
                    "context-bound Native AMX prepare/commit certificates unavailable",
                ));
            }
            self.planned_lane_proposals.insert(
                wire::ConsensusRound {
                    context_id: context.id(),
                    height: context.height,
                    view,
                },
                lane_plan.proposals,
            );
            Ok(PreparedCandidateWork {
                native_amx_receipts: receipts,
                lane_payload_ownerships: lane_plan.ownerships,
                autonomous_lane_payloads,
            })
        })();
        operation.complete();
        result
    }
}

fn all_unavailable(count: usize, reason: impl Into<String>) -> CandidateWorkUnavailable {
    CandidateWorkUnavailable::new((0..count).collect(), reason)
}

fn bitmap_selects(bitmap: &[u8], index: usize) -> bool {
    bitmap
        .get(index / 8)
        .is_some_and(|byte| byte & (1_u8 << (index % 8)) != 0)
}

fn reply_routes_are_live_for_peer(reply_routes: &NetworkReplyRoutes, peer: &PeerId) -> bool {
    !reply_routes.is_empty()
        && reply_routes.semantic_target() == peer
        && reply_routes.iter().any(NetworkReplyRoute::is_active)
}

fn retryable_sidecar_server_control_peer(effect: &V2LaneWorkEffect) -> Option<&PeerId> {
    let V2LaneWorkEffect::PostCertifiedMergeSidecar {
        peer,
        reply_routes,
        message,
    } = effect
    else {
        return None;
    };
    match message.as_ref() {
        CertifiedMergeSidecarMessage::CloseAck(_) if reply_routes.is_some() => Some(peer),
        CertifiedMergeSidecarMessage::GenerationHint(_) if reply_routes.is_some() => Some(peer),
        CertifiedMergeSidecarMessage::Request(_)
        | CertifiedMergeSidecarMessage::Close(_)
        | CertifiedMergeSidecarMessage::CloseAck(_)
        | CertifiedMergeSidecarMessage::GenerationHint(_)
        | CertifiedMergeSidecarMessage::Chunk(_) => None,
    }
}

fn retryable_sidecar_server_control_has_writable_route(effect: &V2LaneWorkEffect) -> bool {
    retryable_sidecar_server_control_peer(effect).is_some()
        && matches!(
            effect,
            V2LaneWorkEffect::PostCertifiedMergeSidecar {
                reply_routes: Some(reply_routes),
                ..
            } if reply_routes
                .iter()
                .any(NetworkReplyRoute::is_reply_writable)
        )
}

fn lane_work_effect_reply_routes_have_valid_shape(effect: &V2LaneWorkEffect) -> bool {
    let reply_routes_target_peer = |reply_routes: &NetworkReplyRoutes, peer: &PeerId| {
        !reply_routes.is_empty() && reply_routes.semantic_target() == peer
    };
    match effect {
        V2LaneWorkEffect::PostLaneBlock { .. }
        | V2LaneWorkEffect::PostLaneDrainVote { .. }
        | V2LaneWorkEffect::BroadcastMerge(_) => true,
        V2LaneWorkEffect::PostDurableLaneCertificate {
            peer,
            reply_routes,
            ingress_ownership,
            ..
        } => reply_routes.as_ref().is_some_and(|routes| {
            reply_routes_target_peer(routes, peer)
                && ingress_ownership.as_ref().map_or(cfg!(test), |ownership| {
                    ownership.validate_exact() && ownership.matches_reply_routes(Some(routes))
                })
        }),
        V2LaneWorkEffect::PostNativeAmx {
            peer,
            reply_routes,
            message,
        } => match message {
            NativeAmxMessage::PrepareRequest(_) | NativeAmxMessage::CommitRequest(_) => {
                reply_routes.is_none()
            }
            NativeAmxMessage::PrepareVote(_) | NativeAmxMessage::CommitVote(_) => reply_routes
                .as_ref()
                .is_some_and(|routes| reply_routes_target_peer(routes, peer)),
        },
        V2LaneWorkEffect::PostCertifiedMergeSidecar {
            peer,
            reply_routes,
            message,
        } => match message.as_ref() {
            CertifiedMergeSidecarMessage::Request(_) | CertifiedMergeSidecarMessage::Close(_) => {
                reply_routes.is_none()
            }
            CertifiedMergeSidecarMessage::CloseAck(_)
            | CertifiedMergeSidecarMessage::GenerationHint(_)
            | CertifiedMergeSidecarMessage::Chunk(_) => reply_routes
                .as_ref()
                .is_some_and(|routes| reply_routes_target_peer(routes, peer)),
        },
    }
}

fn lane_work_effect_reply_routes_are_valid(effect: &V2LaneWorkEffect) -> bool {
    match effect {
        V2LaneWorkEffect::PostLaneBlock { .. }
        | V2LaneWorkEffect::PostLaneDrainVote { .. }
        | V2LaneWorkEffect::BroadcastMerge(_) => true,
        V2LaneWorkEffect::PostDurableLaneCertificate {
            peer,
            reply_routes,
            ingress_ownership,
            ..
        } => reply_routes.as_ref().is_some_and(|routes| {
            reply_routes_are_live_for_peer(routes, peer)
                && ingress_ownership.as_ref().map_or(cfg!(test), |ownership| {
                    ownership.validate_exact() && ownership.matches_reply_routes(Some(routes))
                })
        }),
        V2LaneWorkEffect::PostNativeAmx {
            peer,
            reply_routes,
            message,
        } => match message {
            NativeAmxMessage::PrepareRequest(_) | NativeAmxMessage::CommitRequest(_) => {
                reply_routes.is_none()
            }
            NativeAmxMessage::PrepareVote(_) | NativeAmxMessage::CommitVote(_) => reply_routes
                .as_ref()
                .is_some_and(|routes| reply_routes_are_live_for_peer(routes, peer)),
        },
        V2LaneWorkEffect::PostCertifiedMergeSidecar {
            peer,
            reply_routes,
            message,
        } => match message.as_ref() {
            CertifiedMergeSidecarMessage::Request(_) | CertifiedMergeSidecarMessage::Close(_) => {
                reply_routes.is_none()
            }
            CertifiedMergeSidecarMessage::CloseAck(_)
            | CertifiedMergeSidecarMessage::GenerationHint(_)
            | CertifiedMergeSidecarMessage::Chunk(_) => reply_routes
                .as_ref()
                .is_some_and(|routes| reply_routes_are_live_for_peer(routes, peer)),
        },
    }
}

fn optional_reply_routes_retain_candidate(
    merged: &Option<NetworkReplyRoutes>,
    candidate: &Option<NetworkReplyRoutes>,
) -> bool {
    match (merged, candidate) {
        (Some(merged), Some(candidate)) => candidate.iter().any(|candidate_route| {
            merged
                .iter()
                .any(|route| route.same_delivery(candidate_route))
        }),
        (None, None) => true,
        (Some(_), None) | (None, Some(_)) => false,
    }
}

fn merge_optional_reply_routes(
    queued: &mut Option<NetworkReplyRoutes>,
    candidate: &Option<NetworkReplyRoutes>,
) -> bool {
    match (queued.as_ref(), candidate.as_ref()) {
        (Some(retained), Some(candidate)) => {
            // Both reconciliation and its final liveness snapshot return
            // operation-owned histories. No caller-supplied projection can
            // erase another authenticated source at this coalescing seam.
            let mut merged = retained.clone();
            let Ok(merge_receipt) = merged.merge_observed_with_receipt(candidate) else {
                return false;
            };
            let Some(mut merged) = merge_receipt.into_output(retained, candidate) else {
                return false;
            };
            let before_prune = merged.clone();
            let (_, prune_receipt) = merged.retain_active_with_receipt();
            let Some(merged) = prune_receipt.into_output(&before_prune) else {
                return false;
            };
            let retains_candidate = candidate.iter().any(|candidate_route| {
                merged
                    .iter()
                    .any(|route| route.same_delivery(candidate_route))
            });
            *queued = Some(merged);
            retains_candidate
        }
        (None, None) => true,
        (Some(_), None) | (None, Some(_)) => false,
    }
}

fn merge_lane_work_effect_reply_routes(
    queued: &mut V2LaneWorkEffect,
    candidate: &V2LaneWorkEffect,
) -> bool {
    merge_lane_work_effect_reply_routes_after_route_merge(queued, candidate, || {})
}

fn merge_lane_work_effect_reply_routes_after_route_merge<AfterRouteMerge>(
    queued: &mut V2LaneWorkEffect,
    candidate: &V2LaneWorkEffect,
    after_route_merge: AfterRouteMerge,
) -> bool
where
    AfterRouteMerge: FnOnce(),
{
    // A queued source may have disconnected since reservation. The
    // per-source merge prunes such retained attempts while allowing other live
    // members of the same occurrence to attach.
    if !lane_work_effect_reply_routes_have_valid_shape(candidate) {
        return false;
    }
    match (queued, candidate) {
        (
            V2LaneWorkEffect::PostDurableLaneCertificate {
                reply_routes: queued_routes,
                ingress_ownership: queued_ownership,
                ..
            },
            V2LaneWorkEffect::PostDurableLaneCertificate {
                reply_routes: candidate_routes,
                ingress_ownership: candidate_ownership,
                ..
            },
        ) => {
            let (mut merged_routes, merge_receipt) =
                match (queued_routes.as_ref(), candidate_routes.as_ref()) {
                    (Some(queued), Some(candidate)) => {
                        let mut merged = queued.clone();
                        let Ok(receipt) = merged.merge_observed_with_receipt(candidate) else {
                            return false;
                        };
                        (Some(merged), Some(receipt))
                    }
                    (None, None) if cfg!(test) => (None, None),
                    (Some(_), None) | (None, Some(_)) | (None, None) => return false,
                };
            after_route_merge();
            let mut merged_ownership = queued_ownership.clone();
            match (&mut merged_ownership, candidate_ownership) {
                (Some(retained), Some(candidate)) => {
                    let Some(receipt) = merge_receipt else {
                        return false;
                    };
                    let Some(receipt_routes) =
                        retained.merge_downstream_with_observed_receipt(candidate.clone(), receipt)
                    else {
                        return false;
                    };
                    merged_routes = Some(receipt_routes);
                }
                (None, None) if cfg!(test) => {}
                (Some(_), None) | (None, Some(_)) | (None, None) => return false,
            }
            if merged_ownership.as_ref().is_some_and(|ownership| {
                !ownership.validate_exact()
                    || !ownership.matches_reply_routes(merged_routes.as_ref())
            }) {
                return false;
            }
            let retained_candidate_route =
                optional_reply_routes_retain_candidate(&merged_routes, candidate_routes);
            *queued_routes = merged_routes;
            *queued_ownership = merged_ownership;
            retained_candidate_route
        }
        (
            V2LaneWorkEffect::PostNativeAmx {
                reply_routes: queued,
                ..
            },
            V2LaneWorkEffect::PostNativeAmx {
                reply_routes: candidate,
                ..
            },
        )
        | (
            V2LaneWorkEffect::PostCertifiedMergeSidecar {
                reply_routes: queued,
                ..
            },
            V2LaneWorkEffect::PostCertifiedMergeSidecar {
                reply_routes: candidate,
                ..
            },
        ) => merge_optional_reply_routes(queued, candidate),
        (V2LaneWorkEffect::PostLaneBlock { .. }, V2LaneWorkEffect::PostLaneBlock { .. })
        | (
            V2LaneWorkEffect::PostLaneDrainVote { .. },
            V2LaneWorkEffect::PostLaneDrainVote { .. },
        )
        | (V2LaneWorkEffect::BroadcastMerge(_), V2LaneWorkEffect::BroadcastMerge(_)) => true,
        _ => false,
    }
}

fn verified_native_committee_pops(
    validators: &[PeerId],
    aligned_pops: &[Vec<u8>],
) -> Option<BTreeMap<PublicKey, Vec<u8>>> {
    if aligned_pops.len() != validators.len()
        || validators.iter().zip(aligned_pops).any(|(peer, pop)| {
            pop.len() != crate::native_amx::NATIVE_AMX_BLS_PROOF_BYTES
                || iroha_crypto::bls_normal_pop_verify(peer.public_key(), pop.as_slice()).is_err()
        })
    {
        return None;
    }
    Some(
        validators
            .iter()
            .zip(aligned_pops)
            .map(|(peer, pop)| (peer.public_key().clone(), pop.clone()))
            .collect(),
    )
}

fn lane_work_effect_key(effect: &V2LaneWorkEffect) -> Hash {
    let mut encoded = Vec::new();
    match effect {
        V2LaneWorkEffect::PostLaneBlock { peer, message } => {
            encoded.push(0);
            encoded.extend(peer.encode());
            encoded.extend(message.encode());
        }
        V2LaneWorkEffect::PostDurableLaneCertificate {
            peer, certificate, ..
        } => {
            encoded.push(4);
            encoded.extend(peer.encode());
            encoded.extend(certificate.encode());
        }
        V2LaneWorkEffect::PostNativeAmx { peer, message, .. } => {
            encoded.push(1);
            encoded.extend(peer.encode());
            encoded.extend(message.encode());
        }
        V2LaneWorkEffect::BroadcastMerge(signature) => {
            encoded.push(2);
            encoded.extend(signature.encode());
        }
        V2LaneWorkEffect::PostCertifiedMergeSidecar { peer, message, .. } => {
            encoded.push(3);
            encoded.extend(peer.encode());
            encoded.extend(message.as_ref().encode());
        }
        V2LaneWorkEffect::PostLaneDrainVote { peer, vote } => {
            encoded.push(5);
            encoded.extend(peer.encode());
            encoded.extend(vote.encode());
        }
    }
    Hash::new(encoded)
}

fn lane_proposal_author(proposal: &LaneBlockProposalV1) -> Option<&PeerId> {
    let count = u64::try_from(proposal.descriptor.validator_set.len()).ok()?;
    if count == 0 {
        return None;
    }
    let index = proposal.descriptor.lane_block_height.saturating_sub(1) % count;
    proposal
        .descriptor
        .validator_set
        .get(usize::try_from(index).ok()?)
}

/// Return whether every lane ownership in an authenticated finality artifact
/// has crossed its exact durability boundary.
///
/// Ordinary control-only lane ownerships require both the certificate and the
/// application receipt produced by this finalized carrier. Autonomous anchors
/// require the certified executable bundle only; their economic application
/// receipt is intentionally created by a later canonical merge carrier.
///
/// Missing evidence is the recoverable applied-tip crash boundary. Conflicting
/// evidence is an invalid durable state and therefore returns an error instead
/// of being treated as incomplete.
pub(crate) fn durable_lane_completion_matches_finality(
    kura: &Kura,
    finality_artifact: &wire::finality::V2FinalityArtifact,
) -> Result<bool, String> {
    finality_artifact
        .validate()
        .map_err(|error| error.to_string())?;
    let height = usize::try_from(finality_artifact.height)
        .ok()
        .and_then(NonZeroUsize::new)
        .ok_or_else(|| "lane finality has an invalid zero height".to_owned())?;
    let block = kura
        .get_block(height)
        .ok_or_else(|| "lane finality has no canonical block body".to_owned())?;
    let canonical_payload_hash = block
        .canonical_proposal_wire_hash()
        .map_err(|error| error.to_string())?;
    let canonical_subject = wire::BlockSubject {
        parent_block_hash: block.header().prev_block_hash(),
        block_hash: block.hash(),
        payload_hash: canonical_payload_hash,
    };
    if block.header().height().get() != finality_artifact.height
        || canonical_subject != finality_artifact.subject
        || finality_artifact.height_context.height != finality_artifact.height
    {
        return Err("lane finality differs from its canonical block or height context".to_owned());
    }
    let bundle = block.execution_context();
    let ownerships = bundle.map_or(&[][..], |bundle| bundle.lane_payload_ownerships.as_slice());
    let mut proposal_hashes = BTreeSet::new();
    for ownership in ownerships {
        if ownership.proposal_height != finality_artifact.height {
            return Err("lane ownership is bound to another global height".to_owned());
        }
        let proposal = proposal_from_ownership(ownership, finality_artifact.block_hash)
            .ok_or_else(|| "lane ownership cannot reconstruct its exact proposal".to_owned())?;
        if !proposal_hashes.insert(proposal.proposal_hash) {
            return Err("canonical block contains duplicate lane proposal ownership".to_owned());
        }
        let Some(certified) =
            kura.read_certified_lane_block_artifact(ownership.lane_id, ownership.lane_block_height)
        else {
            return Ok(false);
        };
        Kura::validate_certified_lane_block_artifact(&certified)
            .map_err(|message| format!("durable certified lane artifact is invalid: {message}"))?;
        let Some(receipt) = kura
            .read_lane_block_application_receipt(ownership.lane_id, ownership.lane_block_height)
        else {
            return Ok(false);
        };
        if certified.proposal != proposal
            || receipt.proposal != proposal
            || receipt.artifact.proposal_block_hash != finality_artifact.block_hash
            || receipt.artifact.ownership != *ownership
            || receipt.application_block_height != finality_artifact.height
            || receipt.application_block_hash != finality_artifact.block_hash
        {
            return Err(
                "durable lane certificate or receipt conflicts with the finalized ownership"
                    .to_owned(),
            );
        }
    }
    let autonomous_envelopes =
        bundle.map_or(&[][..], |bundle| bundle.autonomous_lane_payloads.as_slice());
    let chain_id = finality_artifact
        .height_context
        .chain_id
        .clone()
        .into_inner();
    let chain_id_hash = Hash::new(chain_id.as_bytes());
    for envelope in autonomous_envelopes {
        let payload = decode_autonomous_lane_payload_envelope(
            envelope,
            chain_id_hash,
            finality_artifact.height_context.epoch,
        )
        .and_then(|payload| {
            payload.attach_global_hint_exact(
                LaneBlockProposalPayloadHintV1 {
                    proposal_height: finality_artifact.height,
                    proposal_view: block.header().view_change_index(),
                    proposal_block_hash: finality_artifact.block_hash,
                },
                chain_id_hash,
                finality_artifact.height_context.epoch,
            )
        })
        .map_err(|error| format!("canonical autonomous lane anchor is invalid: {error}"))?;
        let proposal = &payload.origin_proposal;
        let descriptor = &proposal.descriptor;
        if !proposal_hashes.insert(proposal.proposal_hash) {
            return Err("canonical block contains duplicate autonomous lane proposal".to_owned());
        }
        let Some(autonomous) = kura.read_autonomous_lane_block_artifact(
            descriptor.lane_id,
            descriptor.lane_block_height,
            chain_id_hash,
            finality_artifact.height_context.epoch,
        ) else {
            return Ok(false);
        };
        let Some(certified) = kura
            .read_certified_lane_block_artifact(descriptor.lane_id, descriptor.lane_block_height)
        else {
            return Ok(false);
        };
        Kura::validate_certified_lane_block_artifact(&certified)
            .map_err(|message| format!("durable autonomous certificate is invalid: {message}"))?;
        if autonomous.executable_payload != payload || certified.proposal != *proposal {
            return Err(
                "durable autonomous bundle conflicts with its finalized control anchor".to_owned(),
            );
        }
    }
    Ok(true)
}

/// Verify that a Kura-durable current-height body carries the exact lane plan
/// which was validated before its interrupted State application.
///
/// Re-running ordinary planning after `Kura::store_block` is incorrect because
/// the just-persisted lane artifacts intentionally block the next lane slot.
/// Recovery therefore authenticates the canonical block hash, exact sidecars,
/// frozen lifecycle/committee/tag bindings, proposer authority, and applied
/// predecessor instead of consulting the post-persistence frontier.
pub(crate) fn canonical_v2_lane_payload_matches_kura(
    state: &State,
    kura: &Kura,
    context: &wire::HeightContext,
    block: &SignedBlock,
) -> bool {
    let block_hash = block.hash();
    let Some(height) = usize::try_from(context.height)
        .ok()
        .and_then(NonZeroUsize::new)
    else {
        return false;
    };
    if block.header().height().get() != context.height
        || kura.block_hash_at_height(height) != Some(block_hash)
    {
        return false;
    }
    let Some(bundle) = block.execution_context() else {
        return block.external_entrypoint_count() == 0;
    };
    let ownerships = &bundle.lane_payload_ownerships;
    if ownerships.is_empty() {
        return bundle.external.is_empty();
    }

    let view = block.header().view_change_index();
    let Some(global_leader) = usize::try_from(context.leader(view))
        .ok()
        .and_then(|index| context.roster.get(index))
        .map(|entry| &entry.validator)
    else {
        return false;
    };
    let nexus = state.nexus_snapshot();
    let shared_committee = !nexus.enabled || !proposal_lookahead_enabled(&nexus, context.height);
    let base_mode_tag = match context.mode {
        wire::ConsensusMode::Permissioned => wire::PERMISSIONED_TAG,
        wire::ConsensusMode::Npos => wire::NPOS_TAG,
    };
    let context_mode_tag = format!(
        "{base_mode_tag}::height-context:{}::epoch:{}",
        hex::encode(context.id().0.as_ref()),
        context.epoch
    );

    let ownership_is_valid = |ownership: &SumeragiLanePayloadOwnership| {
        if ownership.proposal_height != context.height
            || ownership.proposal_view != view
            || ownership.lane_block_view != 0
            || ownership.validate_replay_material().is_err()
            || !state.lane_route_and_incarnation_active_at_height(
                ownership.lane_id,
                ownership.dataspace_id,
                ownership.lane_incarnation,
                ownership.proposal_height,
            )
            || ownership.qc_mode_tag
                != LaneRelayEnvelope::lane_qc_mode_tag_for(
                    ownership.lane_id,
                    ownership.dataspace_id,
                    &context_mode_tag,
                )
        {
            return false;
        }
        let mut expected_validators = if shared_committee {
            context
                .roster
                .iter()
                .map(|entry| entry.validator.clone())
                .collect::<Vec<_>>()
        } else {
            state.authoritative_lane_peer_ids_at_height(ownership.lane_id, context.height)
        };
        expected_validators.sort();
        expected_validators.dedup();
        if expected_validators.is_empty()
            || ownership.lane_block_descriptor_validator_set != expected_validators
        {
            return false;
        }
        let Some(proposal) = proposal_from_ownership(ownership, block_hash) else {
            return false;
        };
        let expected_author = if shared_committee {
            Some(global_leader)
        } else {
            lane_proposal_author(&proposal)
        };
        expected_author.is_some()
            && (!shared_committee || expected_author == Some(global_leader))
            && state
                .certified_lane_block_predecessor_is_applied_or_snapshot_anchored_cached(&proposal)
    };

    let artifacts = kura.canonical_lane_block_artifacts_at_proposal_height_matching(
        context.height,
        ownerships.len(),
        ownership_is_valid,
    );
    artifacts.len() == ownerships.len()
        && artifacts
            .iter()
            .zip(ownerships)
            .all(|(artifact, ownership)| {
                artifact.proposal_block_hash == block_hash && artifact.ownership == *ownership
            })
}

fn proposal_from_ownership(
    ownership: &SumeragiLanePayloadOwnership,
    block_hash: HashOf<BlockHeader>,
) -> Option<LaneBlockProposalV1> {
    let descriptor_hash = ownership.lane_block_descriptor_hash?;
    let descriptor = LaneBlockDescriptorV1 {
        lane_id: ownership.lane_id,
        dataspace_id: ownership.dataspace_id,
        lane_incarnation: ownership.lane_incarnation,
        proposal_height: ownership.proposal_height,
        previous_lane_block_height: ownership.previous_lane_block_height,
        previous_lane_block_descriptor_hash: ownership.previous_lane_block_descriptor_hash,
        lane_block_height: ownership.lane_block_height,
        lane_block_view: ownership.lane_block_view,
        subject_hash: ownership.subject_hash,
        payload_ownership_hash: ownership.payload_ownership_hash,
        rbc_instance_hash: ownership.rbc_instance_hash,
        accepted_candidate_indices: ownership.accepted_candidate_indices.clone(),
        accepted_transaction_hashes: ownership.accepted_transaction_hashes.clone(),
        validator_set_hash_version: iroha_data_model::consensus::VALIDATOR_SET_HASH_VERSION_V1,
        validator_set_hash: HashOf::new(&ownership.lane_block_descriptor_validator_set),
        validator_set: ownership.lane_block_descriptor_validator_set.clone(),
        validator_count: ownership.lane_block_descriptor_validator_count,
        min_quorum: ownership.lane_block_descriptor_min_quorum,
        qc_mode_tag: ownership.qc_mode_tag.clone(),
        descriptor_hash,
    };
    if descriptor.computed_descriptor_hash() != descriptor_hash {
        return None;
    }
    let mut proposal = LaneBlockProposalV1 {
        descriptor,
        proposal_hash: Hash::prehashed([0; Hash::LENGTH]),
        payload_block_hint: Some(LaneBlockProposalPayloadHintV1 {
            proposal_height: ownership.proposal_height,
            proposal_view: ownership.proposal_view,
            proposal_block_hash: block_hash,
        }),
    };
    proposal.proposal_hash = proposal.computed_proposal_hash();
    Some(proposal)
}

