        candidate.execution_batch = Some(synthetic_merge_execution_batch_for_test(
            &adapter,
            exact_header,
        ));
        let leader = adapter.context.leader(view);
        let share = signed_merge_share_for_test(&adapter, &keys, &candidate, leader);
